int N;
ll A[200005];
ll B[200005];
ll D[35];

//! under以上になる最小のindex
inline int getUnder(vector<ll> c, ll under)
{
    int ok = N, ng = -1;
    while (abs(ok - ng) > 1)
    {
        int mid = (ok + ng) / 2;
        if (c[mid] >= under)
        {
            ok = mid;
        }
        else
        {
            ng = mid;
        }
    }
    return ok;
}
//! top未満になる最大のindex
inline int getTop(vector<ll> c, ll top)
{
    int ok = -1, ng = N;
    while (abs(ok - ng) > 1)
    {
        int mid = (ok + ng) / 2;
        if (c[mid] < top)
        {
            ok = mid;
        }
        else
        {
            ng = mid;
        }
    }
    return ok;
}

int main()
{
    cin >> N;
    REP(i, N)
    {
        cin >> A[i];
    }
    REP(i, N)
    {
        cin >> B[i];
    }
    REP(i, 31)
    {
        ll m = 0;
        REP(j, i)
        {
            m |= (1 << j);
        }
        vector<ll> c;
        REP(j, N)
        {
            c.push_back(B[j] & m);
        }
        sort(c.begin(), c.end());

        ll u = pow(2, i);
        ll t = pow(2, (i + 1));
        REP(j, N)
        {
            ll a = A[j] & m;
            {
                int ui = getUnder(i, u - a);
                int ti = getTop(i, t - a);
                if (ui <= ti)
                {
                    D[i] += (ti - ui + 1);
                }
            }
            {
                int ui = getUnder(i, u + t - a);
                int ti = getTop(i, 2 * t - a);
                if (ui <= ti)
                {
                    D[i] += (ti - ui + 1);
                }
            }
        }
    }

    ll ans = 0;
    REP(i, 31)
    {
        ans |= ((D[i] % 2) << i);
    }
    cout << ans << endl;
    return 0;
}

