    long long ans = 0;
    for (int i = 0; i < 28; i++) {
        //i桁目に1が立つ数を数える
        long long num_1 = 0;

        //i桁より大きい部分は影響しないのでマスクする
        vector<long long> aa = a, bb = b;
        for (int j = 0; j < N; j++) {
            aa[j] &= (1 << (i + 1)) - 1;
            bb[j] &= (1 << (i + 1)) - 1;
        }

        //aa[j] + bb[k] が 2^i ~ 2^(i + 1) - 1, 2^(i + 1) + (2^i ~ 2^(i + 1) - 1)の範囲にあれば1がi桁目に立つ
        //つまりaa[j]を決めるとbb[k]が取れる範囲が定まる
        sort(bb.begin(), bb.end());

        for (int j = 0; j < N; j++) {
            auto left1 = lower_bound(bb.begin(), bb.end(), (1LL << i) - aa[j]);
            auto right1 = upper_bound(bb.begin(), bb.end(), (1LL << (i + 1)) - 1 - aa[j]);

            auto left2 = lower_bound(bb.begin(), bb.end(), (3LL << i) - aa[j]);
            auto right2 = upper_bound(bb.begin(), bb.end(), (3LL << (i + 1)) - 1 - aa[j]);

            num_1 += right1 - left1;
            num_1 += right2 - left2;
        }

        ans |= ((num_1 % 2) << i);
    }

    cout << ans << endl;
}

