	ll n, tem = 1;
	cin>>n;
	map<ll, ll>m;
	rep(i,0,n)cin>>A[i];
	rep(i,0,n)cin>>B[i];
	rep(i,0,n)
	rep(j,0,n)
	m[A[i]+B[j]]++;
	ll ans = 0;
	for(auto it = m.begin(); it!=m.end(); it++){
		if(it->y % 2){
			if(tem){
			ans = it->x;
			tem = 0;
			}
			else ans ^= it->x;
		}
	}
	cout<<ans<<endl;
}
