//shakyo
//http://tutuz.hateblo.jp/entry/2018/06/02/180133

ll a[200001] = {};
ll b[200001] = {};

int main() {
	ll N; cin >> N;
	rep(i, 0, N)cin >> a[i];
	rep(i, 0, N)cin >> b[i];

	ll ans = 0;
	for (ll k = 30; k >= 0; k--) {
		ll cnt = 0;

		//2^k+1 で MOD
		ll t = 1 << (k + 1);
		rep(i, 0, N) {
			a[i] %= t;
			b[i] %= t;
		}

		//b をソート。２分探索用に
		sort(b, b + N);

		//2^k 桁目の１の数を数える
		rep(j, 0, N) {
			ll T = 1 << k;
			cnt += lower_bound(b, b + N, 2 * T - a[j]) - lower_bound(b, b + N, 1 * T - a[j]);
			cnt += lower_bound(b, b + N, 4 * T - a[j]) - lower_bound(b, b + N, 3 * T - a[j]);
		}

		//2^k 桁目の１の数が奇数だったら2^k 桁目を1とする
		if (cnt % 2 & 1) {
			ans |= 1 << k;
		}
	}

	cout << ans << endl;

	return 0;
}

