using namespace std;
typedef long long ll;

#define FOR(i,a,b) for(int i=(a);i<(b);++i)
#define ALL(v) (v).begin(), (v).end()
#define p(s) cout<<(s)<<endl
#define p2(s, t) cout << (s) << " " << (t) << endl
#define pn(s) cout << (#s) << " " << (s) << endl

int N;
vector<ll> A;
vector<ll> B;
vector<ll> modA;
vector<ll> modB;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    // input
    cin >> N;

    A.resize(N);
    B.resize(N);
    modA.resize(N);
    modB.resize(N);

    FOR(i, 0, N){
        cin >> A.at(i);
    }
    FOR(i, 0, N){
        cin >> B.at(i);
    }

    ll answer = 0;

    FOR(bit, 0, 32){
        ll T = pow(2L, bit);
        // p("------------------------------");
        // pn(T);

        FOR(i, 0, N){
            modA.at(i) = A[i] % (T*2);
        }
        FOR(i, 0, N){
            modB.at(i) = B[i] % (T*2);
        }
        sort(ALL(modA));
        sort(ALL(modB));

        int count = 0;
        FOR(i, 0, N){
            ll ai = modA[i];
            // pn(ai);
            ll a_begin = 1 * T - ai;
            ll a_end   = 2 * T - ai;
            ll b_begin = 3 * T - ai;
            ll b_end   = 4 * T - ai;
            //cout << "探す範囲 " << a_begin << "," << a_end << " " << b_begin << "," << b_end << endl;

            // [T-ai, 2T-ai), [3T-ai, 4T-ai)
            auto it0 = lower_bound(ALL(modB), a_begin);
            auto it1 = lower_bound(ALL(modB), a_end);
            ll num0 = it1 - it0;
            // pn(num0);

            auto it2 = lower_bound(ALL(modB), b_begin);
            auto it3 = lower_bound(ALL(modB), b_end);
            ll num1 = it3 - it2;
            // pn(num1);
            // p("");

            count += num0 + num1;
        }
        //cout << "bit " << bit << "番目の1の数は " << count << "個でした" << endl;
        if(count % 2 == 1){
            //s[bit] = '1';
            answer += (1 << bit);
        }
        // p("");
    }

    p(answer);

    return 0;
}

