/*
考察1
ビットごとに考える

考察2
kビット目を考える際、2^k+1以降の数は無視できるので
mod 2^(k+1)をとってよい

考察3
すると、ai+bjのとる範囲は 4 * 2^k 未満になり、
kビット目が立つということは
ai+bjが [2^k, 2 * 2^k) [3 * 2^k, 4 * 2^k)
の中に入るということを意味する

すなわち、そのようなai+bjの数を求めるには
各aiについて↑-aiでソートしたbj乗を二分探索する
*/

int main() {
    int N; cin >> N; 
    vector<ll> a(N), b(N),c(N),d(N);
    for (int i = 0; i < N; i++) cin >> a[i];
    for (int i = 0; i < N; i++) cin >> b[i];

    ll res = 0, T = 1;
    for (ll k = 0; k < 28; k++) {
        for (int i = 0; i < N; i++) {
            c[i] = a[i] % (2 * T);
            d[i] = b[i] % (2 * T);
        }
        sort(d.begin(),d.end());
        ll cnt = 0;
        for (int i = 0; i < N; i++) {
            cnt +=
            (lower_bound(d.begin(),d.end(),4*T-c[i]) -
            lower_bound(d.begin(),d.end(),T-c[i])) -
            (lower_bound(d.begin(),d.end(),3*T-c[i])-
            lower_bound(d.begin(),d.end(),2*T-c[i]));

        }
        if (cnt % 2 == 1) res ^= T;
        //cout << T << " " << cnt << endl;
        T *= 2;
    }
    cout << res << endl;
}

