int main()
{
	int n, a[200000], b[200000], ar[200000][29], br[29][200000], c[29], x[29], ans=0, a1[29], b1[29];

	c[0]=1;
	x[0]=0, a1[0]=0, b1[0]=0;
	for(int i=0; i<28; i++){
		c[i+1]=c[i]*2;
		x[i+1]=0, a1[i+1]=0, b1[i+1]=0;
	}

	scanf("%d", &n);
	for(int i=0; i<n; i++){
		scanf("%d", &a[i]);
		for(int j=0; j<29; j++){
			ar[i][j]=a[i]%c[j];
			if(a[i]/c[j]%2==1){
				a1[j]++;
			}
		}
	}
	for(int i=0; i<n; i++){
		scanf("%d", &b[i]);
		for(int j=0; j<29; j++){
			br[j][i]=b[i]%c[j];
			if(b[i]/c[j]%2==1){
				b1[j]++;
			}
		}
	}

	for(int s=1;s<29;s++){
		sort(br[s], br[s]+n);
		for(int i=0; i<n; i++){
			if(br[s][n-1]<c[s]-ar[i][s]){
				continue;
			}else{
			int j1=0, j2=n-1;
			while(j1!=j2){
				int jmid=(j1+j2)/2;
				if(br[s][jmid]<c[s]-ar[i][s]){
					j1=jmid+1;
				}else{
					j2=jmid;
				}
			}
			x[s]=(x[s]+n-j1)%2;
			}
		}
	}

	for(int s=0; s<29; s++){
		x[s]=(x[s]+n%2*(a1[s]+b1[s])%2)%2;
		ans=ans+x[s]*c[s];
	}

	printf("%d\n", ans);

	return 0;

}

