            if(A[i] >> b & 1) {
                lb = (1 << (b+1)) - numA;
                ub = lb + (1 << b) - 1;
            }
            else {
                lb = (1 << b) - numA;
                ub = lb + (1 << b) - 1;
            }
            // fprintf(stderr, "b = %lld, A[%lld] = %lld, numA = %lld, lb = %lld, ub = %lld\n", b, i, A[i], numA, lb, ub);

            int t = (1 << (b+1));
            if(lb / t != ub / t) {
                segs.push_back(make_pair(lb%t, t-1));
                segs.push_back(make_pair(0, ub%t));
            }
            else {
                segs.push_back(make_pair(lb%t, ub%t));
            }
        }

        int tmp = 0;
        for(auto x : segs) {
