		sort(b.begin(), b.end());
		int sum = 0;
		for (auto ai : a) {
			if (ai&dx) {
				sum += lower_bound(b.begin(), b.end(), dx * 2 - ai) - b.begin();
				sum += b.end() - lower_bound(b.begin(), b.end(), dx * 3 - ai);
			}
			else {
				sum += lower_bound(b.begin(), b.end(), dx * 2 - ai) 
					- lower_bound(b.begin(), b.end(), dx - ai);
			}
			/*
			auto r1 = lower_bound(b.begin(), b.end(), dx - ai);
			auto r2 = lower_bound(b.begin(), b.end(), dx*2 - ai);
			auto r3 = lower_bound(b.begin(), b.end(), dx*3 - ai);
			auto r4 = lower_bound(b.begin(), b.end(), dx*4 - ai);
			int t1 = distance(r1, r2);
			int t2 = distance(r3, r4);
			sum += t1 + t2;
			*/
		}
		if(sum%2==1)
			result += dx;
	}
	cout << result << endl;
	return 0;
}

