int main(){

	POW[0] = 1;
	for(int i = 1; i <= 30; i++){

		POW[i] = POW[i-1]*2;
	}

	scanf("%d",&N);

	for(int i = 0; i < N; i++){

		scanf("%d",&A[i]);
	}

	for(int i = 0; i < N; i++){

		scanf("%d",&B[i]);
	}

	for(int i = 0; i <= 29; i++){

		table[i] = 0;
	}

	int left,right,mid,L1,R1,L2,R2,L,R;
	int tmp;

	for(int i = 30; i >= 1; i--){ //2の何乗で余りを求めるか

		for(int k = 0; k < N; k++){
			A[k] %= POW[i];
			B[k] %= POW[i];
		}

		sort(B,B+N);

		//第i-1桁目のビット数を数える
		for(int k = 0; k < N; k++){ //Aを走査

			tmp = 0;

			L1 = POW[i-1]-A[k];
			R1 = 2*POW[i-1]-A[k];

			//2分探索で、L1 <= b[] < R1となるbの範囲を求める
			left = N;
			L = 0,R = N-1,mid = (L+R)/2;

			while(L <= R){

				if(B[mid] >= L1){

					left = mid;
					R = mid-1;

				}else{

					L = mid+1;
				}
				mid = (L+R)/2;
			}

			right = -1;
			L = 0,R = N-1,mid = (L+R)/2;

			while(L <= R){

				if(B[mid] < R1){

					right  = mid;
					L = mid+1;

				}else{

					R = mid-1;
				}
				mid = (L+R)/2;
			}

			tmp += max(0,right-left+1);

			L2 = 3*POW[i-1]-A[k];
			R2 = 4*POW[i-1]-A[k];


			//2分探索で、L2 <= b[] < R2となるbの範囲を求める
			left = N;
			L = 0,R = N-1,mid = (L+R)/2;

			while(L <= R){

				if(B[mid] >= L2){

					left = mid;
					R = mid-1;

				}else{

					L = mid+1;
				}
				mid = (L+R)/2;
			}

			right = -1;
			L = 0,R = N-1,mid = (L+R)/2;

			while(L <= R){

				if(B[mid] < R2){

					right  = mid;
					L = mid+1;

				}else{

					R = mid-1;
				}
				mid = (L+R)/2;
			}

			tmp += max(0,right-left+1);

			table[i-1] += tmp%2;
			table[i-1] %= 2;
		}
	}

	int ans = 0;

	for(int i = 0; i <= 29; i++){

		if(table[i]%2 == 1){

			ans += POW[i];
		}
