    sort(c+1,c+n+1); sort(d+1,d+n+1); LL s = 0;
    for(LL j=1;j<=n;j++)
    {
      LL x = c[j]; LL ss = 0; LL l,r;
      if(x<bin(i+1))
      {
        l = lower_bound(d+1,d+n+1,bin(i) - x) - d;
        r = upper_bound(d+1,d+n+1,bin(i+1) - 1 - x) - (d+1);
        ss += r-l+1;
      }

      l = lower_bound(d+1,d+n+1,bin(i) + bin(i+1) - x) - d;
      r = upper_bound(d+1,d+n+1,bin(i+2) - 1 -x) - (d+1);

      ss += r-l+1;
      if(ss&1) s=(s+1)&1;
    }
    ans += s * bin(i);
  }
  return printf("%lld\n",ans),0;
}

