        while(b[it2] < 2 * t - a[i] && it2 < n) it2++;
        while(b[it3] < 3 * t - a[i] && it3 < n) it3++;
        while(b[it4] < 4 * t - a[i] && it4 < n) it4++;
        ans += it4 - it3 + it2 - it1;

    }

    return ans;
}

