void init(vector<pair<int,int> >&_B){
	memset(pre,0,sizeof pre);
	memset(suf,0,sizeof suf);
	for(int i=1;i<=n;i++)dat[i]=_B[i-1].first;
	for(int i=1;i<=n;i++){
