ll count_range(ll l,ll u,vector<ll> &v){
    return lower_bound(v.begin(),v.end(),u)-lower_bound(v.begin(),v.end(),l);
}

ll solve(vector<ll> &a,vector<ll> &b,ll n){
    ll res = 0;

    for(int i = 0;i <= 28;i ++){
        vector<ll> amod,bmod;
        ll mod = pow(2,i+1),cnt = 0,T = pow(2,i);

        for(int i = 0;i < n;i ++){
            amod.push_back(a[i]%mod);
            bmod.push_back(b[i]%mod);
        }
        sort(bmod.begin(),bmod.end());

        for(int j = 0;j < n;j ++){
            cnt += count_range(T-amod[j],2*T-amod[j],bmod) +
                   count_range(3*T-amod[j],4*T-amod[j],bmod);
        }

        if(cnt%2) res += pow(2,i);
    }
    return res;
}

