int solve(int n, std::vector<int>& as, std::vector<int>& bs) {
  int ans = 0;
  for(int k = 0; k < 29; k++) {
    const int T = 1 << k;
    int tmp = 0;
    std::vector<int> cs;
    for(int b: bs) {
      cs.push_back(b % (2 * T));
    }
    std::sort(cs.begin(), cs.end());
    for(int a: as) {
      a = a % (T * 2);
      int t1 = lower_bound(cs.begin(), cs.end(), T - a) - cs.begin();
      int t2 = lower_bound(cs.begin(), cs.end(), 2 * T - a) - cs.begin();
      int t3 = lower_bound(cs.begin(), cs.end(), 3 * T - a) - cs.begin();
      int t4 = n;
      tmp += ((t2 - t1) + (t4 - t3));
    }
    ans += (tmp % 2) << k;
  }

  return ans;
}

