  int pow2 = 2;
  for(int i = 0; i < 29; i++){
    for(int j = 0; j < N; j++){
      a_sort[i].push_back(a[j] % pow2);
    }
    sort(a_sort[i].begin(), a_sort[i].end());
    pow2 = pow2 * 2;
  }

  vector<int> ans(29);
