ll decide(int k) {
  // printf("k: %d\n", k);

  // for (int i = 0; i < n; ++i) {
  //   printf("%lld ", b[i]);
  // }
  // printf("\n");

  ll t = mypow(2LL, k);

  vector<ll> ma;
  vector<ll> mb;

  for (int i = 0; i < n; ++i) {
    ma.push_back(a[i] % (2LL * t));
    mb.push_back(b[i] % (2LL * t));
  }

  sort(mb.begin(), mb.end());

  // for (auto &e : mb) {
