  // }
  // printf("\n");

  ll cnt = 0LL;

  for (auto &e : ma) {
    ll fst = upper_bound(mb.begin(), mb.end(), 2LL * t - e - 1LL) - lower_bound(mb.begin(), mb.end(), t - e);
    ll snd = upper_bound(mb.begin(), mb.end(), 4LL * t - e - 1LL) - lower_bound(mb.begin(), mb.end(), 3LL * t - e);
    cnt += fst + snd;
  }

  return cnt % 2LL;
}

