using namespace std;
const int N = 1e6 + 10;
int a[N];
struct Trie
{
    int count;//有此前缀的数的个数
    Trie* next[2];//next[0],next[1]就代表了是该位0还是1
    Trie()
    {
        count = 0;
        memset(next,NULL, sizeof(next));
    }
};
//构建字典树
void insert(Trie* root, int val)
{
    Trie *p = root;//树根不存值
    for (int i = 31; i >= 0; i--) //int型最大到2的32次幂
        {
        int cur = (val >> i) & 1;//从高到低计算第i位的值
        if (p->next[cur] == NULL) {
            p->next[cur] = new Trie();
        }
        p = p->next[cur];
        p->count++;
    }
}
int find(Trie* root, int val, int m)
{
    if (root == NULL)
        return 0;
    Trie *p = root;
    int result = 0;
    for (int i = 31; i >= 0; i--) 
    {
        int cur = (val >> i) & 1;
        int key = (m >> i) & 1;
        if (key == 1)
        {
            p = p->next[cur ^ 1];//若m在此位是1，那么要异或结果在此位也是1
        }
        else
        {
            if (p->next[cur ^ 1] != NULL)
            {
                result += p->next[cur ^ 1]->count;//若m在此位是0，那么异或结果若为1直接累加
            }
            p = p->next[cur];//若m在此位是0，异或结果为0，继续查找
        }
        if (p == NULL) break;
    }
    return result;
}

int main()
{
    int n, m;
    long long result = 0;
    cin >> n >> m;
    Trie *root = new(Trie);
    for (int i = 0; i < n; i++)
    {
        cin >> a[i];
        insert(root, a[i]);
    }
    for (int i = 0; i < n; i++)
        result += (long long)find(root, a[i], m);
    cout<<( result >> 1);
    return 0;
}

