		sort(all(v[1]));
		int zero = 0, l, r, ans = 0;
		for (int i = 1; i <= n; ++i) {
			int k = a[i] % (1 << (x + 1));
			if ((a[i] & (1 << x)) != 0) {
				r = upper_bound(all(v[0]), (1 << (x + 1)) - 1 - k) - v[0].begin() - 1;
				l = lower_bound(all(v[0]), (1 << x) - k) - v[0].begin();
				ans += max(r - l + 1, zero);
				r = upper_bound(all(v[1]), (1 << (x + 2)) - 2 - k) - v[1].begin() - 1;
				l = lower_bound(all(v[1]), (1 << x) + (1 << (x + 1)) - k) - v[1].begin();
				ans += max(r - l + 1, zero);
			} else {
				r = upper_bound(all(v[1]), (1 << (x + 1)) - 1 - k) - v[1].begin() - 1;
				l = lower_bound(all(v[1]), (1 << x) - k) - v[1].begin();
