				r = upper_bound(all(v[0]), (1 << (x + 1)) - 2 - k) - v[0].begin() - 1;
				l = lower_bound(all(v[0]), (1 << x) - k) - v[0].begin();
				ans += max(r - l + 1, zero);
			}             	
		}
		ans %= 2;
		res += (1 << x) * ans; 
		v[0].clear();
		v[1].clear();
	}
	cout << res;
}	    

