int calc(int x,int mask){
	int l=0,r=n+1;
	int less=mask-x%mask;
	while(r-l>1){
		int mid=l+r>>1;
		if(dat[mid]>=less)r=mid;
		else l=mid;
	}
	return pre[r]+suf[r+1];
}
