using int_t = unsigned long long;

int main() {
    int N;
    scanf("%d", &N);
    vector<int_t> Ais;
    vector<int_t> Bis;
    for (int i = 0; i < N; i++) {
        int Ai;
        scanf("%d", &Ai);
        Ais.push_back(Ai);
    }
    for (int i = 0; i < N; i++) {
        int Bi;
        scanf("%d", &Bi);
        Bis.push_back(Bi);
    }
    function<int_t(int, int, int, int)> processSubSeq = [&Ais, &Bis, N, &processSubSeq](int aBegin, int aEnd, int bBegin, int bEnd) -> int_t {
        if (aBegin == aEnd || bBegin == bEnd) {
            return 0;
        }
        if (aEnd - aBegin == 1 && bEnd - bBegin == 1) {
            return Ais[aBegin] + Bis[bBegin];
        }
        int aLenHalf = (aEnd - aBegin) / 2;
        int bLenHalf = (bEnd - bBegin) / 2;
        int_t x1 = processSubSeq(aBegin, aBegin + aLenHalf, bBegin, bBegin + bLenHalf);
        int_t x2 = processSubSeq(aBegin, aBegin + aLenHalf, bBegin + bLenHalf, bEnd);
        int_t x3 = processSubSeq(aBegin + aLenHalf, aEnd,   bBegin, bBegin + bLenHalf);
        int_t x4 = processSubSeq(aBegin + aLenHalf, aEnd,   bBegin + bLenHalf, bEnd);
        return x1 ^ x2 ^ x3 ^ x4;
    };
    printf("%lld", processSubSeq(0, (int)Ais.size(), 0, (int)Bis.size()));
    printf("\n");
    return 0;
}

