using namespace std;

int N;
int A[202020];
int B[202020];


int main(int argc, const char * argv[]) {
    cin >> N;
    for (int i = 0; i < N; ++i)
        cin >> A[i];
    for (int i = 0; i < N; ++i)
        cin >> B[i];

    int r = 0;
    for (int c = 1 << 28; 1 < c; c >>= 1) {
        for (int i = 0; i < N; ++i) {
            A[i] &= (c - 1);
            B[i] &= (c - 1);
        }
        sort(A, A + N);
        sort(B, B + N);

        int cn = 0;
        int j = N;
        for (int i = 0; i < N; ++i) {
            int ai = A[i];
            int ci = c - ai;
            cn += N - j;
            while (0 < j) {
                if (ci <= B[j - 1]) {
                    cn ^= 1;
                    --j;
                } else break;
            }
            if (j == 0) {
                cn += (N - i - 1) * N;
                break;
            }
        }
        if (cn & 1) {
            r |= c;
        }
    }
    long i = lower_bound(A, A + N, 1) - A;
    long j = lower_bound(B, B + N, 1) - B;
    r |= (i * (N - j) + j * (N - i)) & 1;

    cout << r << endl;
    return 0;
}

