    ll abmax = amax + bmax;

    int t = 1 << 1;

    ll ans = 0;
    while ((t >> 1) <= abmax)
    {

        ll mask = t - 1;

        ll cntsum = 0;

        ll K = t >> 1;

        ll K3 = K + t;

        REP (i, N)
