typedef long long ll;

const int INF = 1000000000;

int main()
{
  int N; scanf("%d", &N);
  vector<int> A(N), B(N);
  for (int i = 0; i < N; ++i) {
    scanf("%d", &A[i]);
  }
  for (int i = 0; i < N; ++i) {
    scanf("%d", &B[i]);
  }
  int ans = 0;
  for (int k = 0; k < 30; ++k) {
    int m = (1 << (k + 1));
    vector<int> BB(N);
    for (int i = 0; i < N; ++i) {
      BB[i] = B[i] % m;
    }
    sort(BB.begin(), BB.end());
    ll cnt = 0;
    ll c = (1LL << k);
    for (int i = 0; i < N; ++i) {
      int a = A[i] % m;
      cnt += distance(lower_bound(BB.begin(), BB.end(), c - a),
                      lower_bound(BB.begin(), BB.end(), 2 * c - a));
      cnt += distance(lower_bound(BB.begin(), BB.end(), 3 * c - a),
                      lower_bound(BB.begin(), BB.end(), 4 * c - a));
    }
    if (cnt % 2) { ans |= (1 << k); }
  }
  printf("%d\n", ans);
  return 0;
}

