long long ruijou(int n, int k){
    if(k==0) return 1;
    int x=k/2;
    long long t=ruijou(n,x);

    if(k%2==1) return n*t*t;
    else return t*t;
}

int main(){
    ll N; cin>>N;
    vector<ll> a(N),b(N);
    for(int i=0;i<N;i++) cin>>a.at(i);
    for(int i=0;i<N;i++) cin>>b.at(i);

    ll ans=0;
    for(int i=0;i<30;i++){
        ll M=ruijou(2,i);
        vector<ll> c(N);
        for(int j=0;j<N; j++) c.at(j)=b.at(j)%(2*M);
        sort(c.begin(),c.end());
        ll count=0;
        for(int k=0;k<N;k++){
            ll x=a.at(k)%(2*M);
            count+=(upper_bound(c.begin(),c.end(),4*M-x-1)-lower_bound(c.begin(),c.end(),3*M-x));
            count+=(upper_bound(c.begin(),c.end(),2*M-x-1)-lower_bound(c.begin(),c.end(),M-x));
        }
        ans+=M*(count%2);
    }
    cout<<ans<<endl;
}

