long long POW(long long a, long long n) {
	long long x = 1LL;
	for (; n > 0; n >>= 1, a *= a)
		x *= (n & 1 == 1) ? a : 1;
	return x;
}

int main()
{
	int N;
	cin >> N;
	vi a(N), b(N);
	cin >> a >> b;

	int ans = 0;

	int mod = POW(2, 29);
	for (int bit = 1 << 28; bit > 0; bit >>= 1) {
		for (int idx = 0; idx < N; idx++) {
			a[idx] %= (bit << 1);
			b[idx] %= (bit << 1);
		}

		sortall(b);

		int tmp = 0;
		for (int aidx = 0; aidx < N; aidx++) {
			int T1 = bit - a[aidx];
			int T2 = 2 * bit - a[aidx];
			int T3 = 3 * bit - a[aidx];
			int T4 = 4 * bit - a[aidx];
			int bottomidx = lower_bound(all(b), T1) - b.begin();
			int topidx = lower_bound(all(b), T2) - b.begin();
			tmp += topidx - bottomidx;
			bottomidx = lower_bound(all(b), T3) - b.begin();
			topidx = lower_bound(all(b), T4) - b.begin();
			tmp += topidx - bottomidx;
		}

		if (tmp % 2 == 1) {
			ans += bit;
		}

		mod /= 2;
	}

	cout << ans << endl;

	return 0;
}

