struct Fenv {
    int n;
    vector<int> t;

    Fenv(int n) : n(n), t(n, 0) { }

    int sum(int r) {
        int res = 0;
        for (; r >= 0; r = (r & (r + 1)) - 1) res += t[r];
        return res;
    }

    void inc(int i, int d) {
        for (; i < n; i = (i | (i + 1))) t[i] += d;
    }

    int sum(int l, int r) {
        return sum(r - 1) - sum(l - 1);
    }
};

