      int low2 = lower_bound(v.begin(), v.end(), (2 << i) - a[j] % (1 << (i + 1))) - v.begin();
      int low3 = lower_bound(v.begin(), v.end(), (3 << i) - a[j] % (1 << (i + 1))) - v.begin();
      int low4 = lower_bound(v.begin(), v.end(), (4 << i) - a[j] % (1 << (i + 1))) - v.begin();
      t+=-low1+low2-low3+low4;
    }
    // cout << ans <<endl;
    t%= 2;
    ans+=t << i;
  }
  cout << ans <<endl;
  return 0;
}

