typedef long long LL;


void solve(long long N, std::vector<long long> a, std::vector<long long> b){

  vector<long long> moda(N), modb(N);
  vector<long long> ans(30);

  for(auto i=1;i<30;++i){
    long long T = pow(2.0, i-1);
    for(auto j=0;j<N;++j){
      moda[j] = a[j]%(2*T);
      modb[j] = b[j]%(2*T);
    }
    sort(modb.begin(), modb.end());
    long long counter=0;
    for(auto j=0;j<N;++j){
      counter += (long long)(lower_bound(modb.begin(), modb.end(), 2*T-moda[j])
                             - lower_bound(modb.begin(), modb.end(), T-moda[j]));
      counter += (long long)(lower_bound(modb.begin(), modb.end(), 4*T-moda[j])
                             - lower_bound(modb.begin(), modb.end(),3*T-moda[j]));
    }
    ans[i]=(long long)(counter%2==1);
  }
  long long A=0;
  for(auto i=1;i<30;++i){
    A <<= 1;
    A += ans[30-i];
  }
  cout << A << endl;

}

