using namespace std;

long long g(vector<long long> &b, long long th) {
    long long lb = 0;
    long long ub = b.size()-1;
    while (true){
        long long cur = (lb+ub+1)/2;
        if (b[cur] < th) {
            if (lb == cur) break;
            lb = cur;
        } else {
            if (ub == cur) break;
            ub = cur;
        }
    }
    if (b[lb] >= th) {
        lb -= 1;
    }
    return lb;
}

int main() {
    long long res = 0;
    long long n; cin >> n;
    vector<long long> a0(n); for (long long i = 0; i < n; ++i) cin >> a0[i];
    vector<long long> b0(n); for (long long i = 0; i < n; ++i) cin >> b0[i];
    vector<long long> a(n), b(n);
    for (long long k=0; k < 32; ++k) {
        long long T = 1<<k;
        for (long long i = 0; i < n; ++i) a[i] = a0[i] % (2*T);
        for (long long i = 0; i < n; ++i) b[i] = b0[i] % (2*T);
        sort(b.begin(), b.end());
        long long v = 0;
        for (long long i = 0; i < n; ++i) {
            v += g(b, 2*T-a[i]) - g(b, T-a[i]) + g(b, 4*T-a[i]) - g(b, 3*T-a[i]);
        }
        res += (v % 2) * T;
    }
    cout << res << endl;
}

