    if (carry[i] ^ 1) continue;

    for (int j = 0; j < N; ++j) {
      unsigned int k = 1 << i;
      unsigned int a = A[i];
      k |= k << 1 & a;
      a &= a << 1;
      k |= k << 2 & a;
      a &= a << 2;
      k |= k << 4 & a;
      a &= a << 4;
      k |= k << 8 & a;
      a &= a << 8;
      k |= k << 16 & a;

      ans ^= k ^ (1 << i);
    }
  }

  cout << ans << endl;

  return 0;
}

