inline int search(int v, int n){
	if(d[n - 1] < v)return n;
	int l = 0, r = n - 1;
	while(l < r){
		int m = l + (r - l)/2;
		if(v <= d[m])r = m;
		else l = m + 1;
	}
	return l;
}

