int main() {
	int n;
	scanf("%d", &n);
	for(int i = 0; i < n; i++) scanf("%d", a + i);
	for(int i = 0; i < n; i++) scanf("%d", b + i);
	int res = 0;
	for(int i = 0; i < 28; i++) {
		for(int j = 0; j < n; j++) c[j] = a[j] & ((1 << (i + 1)) - 1);
		for(int j = 0; j < n; j++) d[j] = b[j] & ((1 << (i + 1)) - 1);
		sort(c, c + n); sort(d, d + n);
		int j, tot = 0;
		for(int j = 0; j < n; j++) {
			int st = lower_bound(d, d + n, (1 << i) - c[j]) - d;
			int ed = lower_bound(d, d + n, (1 << (i + 1)) - c[j]) - d;
			if(ed) ed--;
			if(st <= ed)tot += ed - st + 1;
			st = lower_bound(d, d + n, (3 << i) - c[j]) - d;
			ed = lower_bound(d, d + n, (4 << i) - c[j]) - d;
			if(ed) ed--;
			if(st <= ed)	tot += ed - st + 1;
		}
		if(tot & 1) res ^= 1 << i;
	}
	printf("%d\n", res);
	return 0;
}

