int n,ans;
int a[200005],b[200005];
int pre[200005],suf[200005],dat[200005];
void init(vector<pair<int,int> >&_B){
	memset(pre,0,sizeof pre);
	memset(suf,0,sizeof suf);
	for(int i=1;i<=n;i++)dat[i]=_B[i-1].first;
	for(int i=1;i<=n;i++){
		pre[i]=pre[i-1]+(1-_B[i-1].second);
	}
	for(int i=n;i>=1;i--){
		suf[i]=suf[i+1]+(_B[i-1].second);
	}
}
int calc(int x,int mask){
	int l=0,r=n+1;
	int less=mask-x%mask;
	while(r-l>1){
		int mid=l+r>>1;
		if(dat[mid]>=less)r=mid;
		else l=mid;
	}
//	cerr<<r<<" "<<x<<" "<<mask<<" "<<pre[r-1]<<" "<<suf[r]<<endl;
	return (x&mask)==0?n-pre[r-1]-suf[r]:pre[r-1]+suf[r];
}
