int search(const vector<int>& a, int t){
    int l = -1;
    int r = a.size();
    while(r - l > 1){
        int m = (l + r) / 2;
        if(a[m] < t){
            l = m;
        }else{
            r = m;
        }
    }
    return r;
}

int solve(vector<int> a, vector<int> b, int k){
    int t = 1 << k;
    int m = 1 << (k+1) ;
    int n = a.size();
    rep(i, n){
        b[i] %= m;
    }
    sort(b.begin(), b.end());

    int ans = 0;
    rep(i, n){
        int aa = a[i] % m;
        int it1 = search(b, t - aa);
        int it2 = search(b, t*2 - aa);
        int it3 = search(b, t*3 - aa);
        int it4 = search(b, t*4 - aa);
        ans += it4 - it3 + it2 - it1;

    }

    return ans;
}

