	for (auto &e : a)
		scanf("%u", &e);
	for (auto &e : b)
		scanf("%u", &e);
	if (n & 1) {
		for (const auto e : a)
			ans ^= e;
		for (const auto e : b)
			ans ^= e;
	}
	for (auto &e : a)e = ~e;
	for (uint32 i = 0;i < 28;++i) {
		const uint32 pbit = (uint32)1 << i;
		uint32 midA = n, midB = n;
		for (const auto e : a)
			midA -= e >> i & 1;
		for (const auto e : b) 
			midB -= e >> i & 1;
		uint32 lA = 0, lB = 0;
		for (const auto e : a)
			c[e & pbit ? midA++ : lA++] = e;
		for (const auto e : b)
			d[e & pbit ? midB++ : lB++] = e;
		std::swap(a, c);
		std::swap(b, d);
		lA = 0;
		lB = 0;
		const uint32 mask = (pbit << 1) - 1;
		while (lA < n) {
			while (lB < n && (a[lA] & mask) >= (b[lB] & mask))
				++lB;
			if (n - lB & 1)
				ans ^= pbit << 1;
			++lA;
		}
	}
	printf("%u\n", ans);
	return 0;
}

