ll n;
ll a[MAXN], b[MAXN];

bool check(int k) {
  ll mod = 1 << (k + 1);
  for (int i=0;i<n;i++) {
    a[i] = a[i] % mod;
    b[i] = b[i] % mod;
  }
  sort(b, b+n);

  ll cnt = 0;
  ll mask = 1 << k;
  for (int i=0;i<n;i++) {
    cnt += lower_bound(b, b+n, 2 * mask - a[i]) - lower_bound(b, b+n, mask - a[i]);
    cnt += lower_bound(b, b+n, 4 * mask - a[i]) - lower_bound(b, b+n, 3 * mask - a[i]);
  }
  return cnt % 2 == 1;
}

void solve() {
  ll ans = 0;
  // 2^k+1でmodを取るので大きい方からやればコピーしなくていい
  for (int i=30;i>=0;i--) {
    if (check(i)) {
      ans += 1 << i;
    }
  }
  cout << ans << endl;
}

