            sum += lower_bound(b.begin(), b.end(), 2*k-a[i]) - lower_bound(b.begin(), b.end(), k-a[i]);
            sum += lower_bound(b.begin(), b.end(), 4*k-a[i]) - lower_bound(b.begin(), b.end(), 3*k-a[i]);
        }
        ans += k * (sum % 2);
    }
    cout << ans << endl;

    return 0;
}

