bool solve(const int k,vector<int> a,vector<int> b){
    REP(i,SZ(a)) a[i] %= 1<<k+1;
    REP(i,SZ(b)) b[i] %= 1<<k+1;

    SORT(b);
    int ret = 0;

    REP(i,SZ(a)){
        ret += LB(ALL(b),(1<<k+1)-a[i]) - LB(ALL(b),(1<<k)-a[i])
            +  LB(ALL(b),(1<<k+2)-a[i]) - LB(ALL(b),(1<<k)*3-a[i]);
    }

    return ret%2;
}

