    }
    for(ll j = 0; j < n; j++) {
        ll l = lower_bound(v[d-1].begin(), v[d-1].end(), (1 << d) - b[j]) - v[d-1].begin();
        cnt[d] += n - l;
    }
    ll ans = 0;
    for(ll i = 0; i <= d; i++) {
        if(cnt[i] % 2) ans += 1 << i;
    }
