void solve() {
  int n;
  cin >> n;
  vector<int> a(n);
  cin >> a;
  vector<int> b(n);
  cin >> b;

  ll ans = 0;
  // ai+bj で k bit目が 1 のものが何個あるか
  // その xor
  rep(k, 60) {
    vector<int> a2 = a, b2 = b;
    ll t = (1LL << k);
    // 2^(k+1) までに制限することで, 範囲が狭まる
    // しかも, k bit 目 (ほぼ最高桁) だから, 見るべき範囲が狭い
    rep(i, n) a2[i] %= t * 2;
    rep(i, n) b2[i] %= t * 2;
    sort(all(b2));

    int tmp = 0;
    rep(i, n) {
      int it = lb(b2, t - a2[i]);
      int it2 = lb(b2, 2 * t - a2[i]);
      tmp += it2 - it;

      it = lb(b2, 3 * t - a2[i]);
      it2 = lb(b2, 4 * t - a2[i]);
      tmp += it2 - it;
    }

    if (tmp % 2) ans += 1LL << k;
  }
  cout << ans << endl;
}

