unsigned int solve(size_t n, unsigned int *a, unsigned int *b) {
	unsigned int res = 0;
	for (size_t i = 0; i < n; i++)
		for (size_t j = 0; j < n; j++)
			res ^= a[i]+b[j];
	return res;
}


