/* -----  2019/03/11  Problem: ABC 091 D / Link: http://abc091.contest.atcoder.jp/tasks/abc091_d  ----- */


int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	LL N; cin >> N;
	vector<LL> a(N), b(N);
	for (int i = 0; i < N; ++i) {
		cin >> a[i];
	}
	for (int i = 0; i < N; ++i) {
		cin >> b[i];
	}


	LL ans = 0;
	auto A = a;
	auto B = b;
	auto cnt = [&](int L,int R) {
		return lower_bound(ALL(B), R) - lower_bound(ALL(B), L);
	};
	FOR(k, 0, 30) {
		const int base2 = 1 << k;
		const int base22 = 1 << (k + 1);
		FOR(i, 0, N) {
			A[i] = a[i] % base22;
			B[i] = b[i] % base22;
		}
		SORT(B);
		LL ret = 0;
		FOR(i, 0, N) {
			if (A[i] <= base2) {
				ret += cnt(base2 - A[i], base22 - A[i]);
			}
			else {
				ret += cnt(0, base22 - A[i]);
				ret += cnt(base22 + base2 - A[i], base22);
			}
		}
		ans += base2 * (ret & 1);
	}

	cout << (ans) << "\n";

	return 0;
}

