int solve() {
    ll n;
    cin>>n;
    Vec a(n);
    Vec b(n);
    cin>>a>>b;

    auto binary_count=[](Vec &v,ll L, ll R){
        //[L,R]に含まれるvの要素の個数を返す
        return upper_bound(ALL(v),R) - lower_bound(ALL(v),L);
    };

    ll ans = 0;
    per(k, 31){
        ll T = 1LL<<k;
        ll tmp = 0;
        rep(i,n){
            a[i] %= T*2;
            b[i] %= T*2;
        }
        sort(ALL(b));
        rep(i,n){
            tmp += binary_count(b,T-a[i],2*T-1-a[i]);
            tmp += binary_count(b,3*T-a[i],4*T-1-a[i]);
        }
        if(tmp%2==1){
            ans += T;
        }
    }
    out(ans);
    return 0;
}

