template<class T> void gc(T &x)
{
    char c;
    int s = 0;
    x = 0;

    c = getchar_unlocked();

    if (c == '-') s = 1;
    else if ('0' <= c && c <= '9')  x = c - '0';

    while (true)
    {
        c = getchar_unlocked();

        if (c < '0' || '9' < c) break;
        x = x * 10 + (c - '0');
    }

    if (s) x = -x;
}

int main()
{
    ui N;
    gc(N);

    va.resize(N);
    vb.resize(N);
    ta.resize(N);
    tb.resize(N);

    for (ui i = 0; i < N; i++)
    {
        gc(va[i]);
    }

    for (ui i = 0; i < N; i++)
    {
        gc(vb[i]);
    }

    sort(va.begin(), va.end());
    sort(vb.begin(), vb.end());

    ui amax = va[N - 1];
    ui bmax = vb[N - 1];

    ui d = 2;
    ui x = 1;
    ui ans = 0;
    while ((d >> 1) <= amax + bmax)
    {
        ui t0 = 1 << x;

        for (ui i = 0; i < N; i++)
        {
            ta[i] = va[i] % t0;
            tb[i] = vb[i] % t0;
        }

        // ソートは b だけ
        sort(tb.begin(), tb.end());

        ui a = 0;
        ui suma = 0;
        for (ui i = 0; i < N; i++)
        {
            ui t1 = 1 << (x - 1);
            ui t2 = 2 * t1;

            // 負の場合 ゼロ
            ui l = ta[i] < t1 ? t1 - ta[i] : (ui)0;
            ui h = ta[i] < t2 ? t2 - ta[i] : (ui)0;

            // [T - ai, 2T - ai) 区間 1
            ui l1 = lower_bound(tb.begin(), tb.end(), l) - tb.begin();
            ui u1 = lower_bound(tb.begin(), tb.end(), h) - tb.begin() - 1;

            ui t3 = 3 * t1;
            ui t4 = 4 * t1;

            l = ta[i] < t3 ? t3 - ta[i] : (ui)0;
            h = ta[i] < t4 ? t4 - ta[i] : (ui)0;

            // [3T - ai, 4T - ai) 区間 2
            ui l2 = lower_bound(tb.begin(), tb.end(), l) - tb.begin();
            ui u2 = lower_bound(tb.begin(), tb.end(), h) - tb.begin() - 1;

            a = 0;
            if (l1 == N)
            {
                // 区間 1 無し
                if (l2 == N)
                {
                    // 区間 2 無し
                    a = 0;
                }
                else
                {
                    // 区間 2 有り
                    a = u2 - l2 + 1;
                }
            }
            else if (l2 == N)
            {
                // 区間 2 無し
                a = u1 - l1 + 1;
            }
            else if (l2 <= u1 && l1 <= u2)
            {
                // 区間が交差する
                a = max(u1, u2) -min(l1, l2) + 1;
            }
            else
            {
                // 区間が交差しない
                a = u1 - l1 + u2 -l2 + 2;
            }
            suma += a;
        }

        if (suma % 2 == 0) suma = 0;
        else suma = 1;

        ans += suma * (1 << (x - 1));

        x++;
        d <<= 1;
    }

    printf("%" pu32 "\n", ans);
    return 0;
}

