    for (int i = 0; i < 29; ++i) {
        int mask = (1 << (i + 1)) - 1;
        vector<int> c(n);
        for (int j = 0; j < n; ++j) {
            c[j] = b[j] & mask;
        }
        sort(c.begin(), c.end());
        int k = 0;
        for (int j = 0; j < n; ++j) {
            int a_j = a[j] & mask;
            int l1 = (1 << i) - a_j;
            int r1 = (1 << (i + 1)) - 1 - a_j;
            int l2 = (3 << i) - a_j;
            int r2 = ((3 << i) | ((1 << i) - 1)) - a_j;

            int li1 = lower_bound(c.begin(), c.end(), l1) - c.begin();
            int ri1 = upper_bound(c.begin(), c.end(), r1) - c.begin();
            int li2 = lower_bound(c.begin(), c.end(), l2) - c.begin();
            int ri2 = upper_bound(c.begin(), c.end(), r2) - c.begin();

            k += (ri1 - li1) & 1;
            k += (ri2 - li2) & 1;
        }
        ans |= (k & 1) << i;
    }

    cout << ans << endl;
    return 0;
}

