            int cnt_4 = lower_bound(sub_a.begin(),sub_a.begin()+n,4*tmp-sub_b[j])-sub_a.begin();
            cnt = cnt + (cnt_1+cnt_2+cnt_3+cnt_4-2*n);
        }
        if(cnt%2==1)ans+=tmp;
        tmp *= 2;
    }

    cout << ans<<endl;

    return 0;
}

