    RREP(k,29){
        int bekihigh = 1<<(k+1), bekilow = 1<<k;
        for (int i = 0; i < N; ++i) a[i] %= bekihigh, b[i] %= bekihigh;
        sort(b.begin(), b.end());
        ll bitans=0;
        ll T=1<<k;
