int main() {
	int N;
	int A[MAX], B[MAX];
	int ans = 0;

	cin >> N;
	for (int i = 0; i < N; i++)cin >> A[i];
	for (int i = 0; i < N; i++)cin >> B[i];

	for (int i = 0; i < 29; i++) {
		int T = pow(2, i);
		vector<int>a, b;

		for (int i = 0; i < N; i++) {
			a.push_back(A[i] % (2 * T));
			b.push_back(B[i] % (2 * T));
		}

		sort(b.begin(), b.end());

		int sum = 0;

		for (int i = 0; i < N; i++) {
			int t1 = lower_bound(b.begin(), b.end(), 1 * T - a[i]) - b.begin();
			int t2 = lower_bound(b.begin(), b.end(), 2 * T - a[i]) - b.begin();
			int t3 = lower_bound(b.begin(), b.end(), 3 * T - a[i]) - b.begin();
			sum += (t2 - t1) + (N - t3);
		}

		if (sum % 2)ans |= T;
	}


	cout << ans << endl;

	return 0;
}

