			if(B[mid]&d) ub=mid;
			else lb=mid;
		}
		z=ub;
		ub=z;
		lb=-1;
		while(ub-lb>1){
			mid=(ub+lb)/2;
			if( ((x+B[mid])&d) ^ (x & d) ) ub=mid;
			else lb=mid;
		}
		if(m){
			res+= lb+1;
		}
		else{
			res+= z-ub;
		}

		ub=N;
		lb=z-1;
		while(ub-lb>1){
			mid=(ub+lb)/2;
