            ans ^= b[i];
        }
    }
    //2進数で表したときの下から(i+1)桁目の繰り上がりの回数を調べる
    rep(i, 30){
        //繰り上がりの回数
        int cnt = 0;
        //A[i]:=a[i]の下i桁、B[i]:=b[i]の下i桁
        ll A[N], B[N];
        fill(A, A+N, 0), fill(B, B+N, 0);
        rep(j, N){
            //下(k+1)桁目を足す
            rep(k, i){
                if(a[j] & (1<<k)) A[j] += (1<<k);
                if(b[j] & (1<<k)) B[j] += (1<<k);
            }
        }
        sort(B, B+N);
        rep(j, N){
            cnt += B+N - lower_bound(B, B+N, (1<<i)-A[j]);
        }
        if(cnt%2 == 1) ans ^= (1<<i);
    }
    cout << ans << endl;
}

