using namespace std;

int main(){
    int N;
    cin>>N;
    long long a[200000],b[200000];
    for(int i=0;i<N;i++){
        cin>>a[i];
    }
    for(int i=0;i<N;i++){
        cin>>b[i];
    }
    const int MAX_I=31;
    long long pow2[MAX_I];
    pow2[0]=1;
    for(int i=1;i<MAX_I;i++){
        pow2[i]=2*pow2[i-1];
    }
    long long ans=0;
    for(int k=0;k<MAX_I-1;k++){
        //ansのk桁目を求める
        long long modiA[200000],modiB[200000];
        for(int i=0;i<N;i++){
            modiA[i]=a[i]%pow2[k+1];
            modiB[i]=b[i]%pow2[k+1];
        }
        sort(modiB,modiB+N);
        long long tmp=0;
        for(int i=0;i<N;i++){
            //modiA[i]と足し合わせてk桁目が1になるmodiBの数を数える
            //「pow2[k]以上，2*pow2[k]未満」と「3*pow2[k]以上，4*pow2[k]未満」の2パターンある．
            long long x,y,z,w;
            x=pow2[k]-modiA[i];
            y=2*pow2[k]-modiA[i];
            z=3*pow2[k]-modiA[i];
            w=4*pow2[k]-modiA[i];
            long long* posX=lower_bound(modiB,modiB+N,x);
            long long* posY=lower_bound(modiB,modiB+N,y);
            long long* posZ=lower_bound(modiB,modiB+N,z);
            long long* posW=lower_bound(modiB,modiB+N,w);
            tmp += (posY-posX)+(posW-posZ);
            //cout<<k<<' '<<i<<' '<<(int)(posY-posX)<<' '<<(int)(posW-posZ)<<endl;
        }
        if(tmp%2==1){
            ans += pow2[k];
        }
    }
    cout<<ans<<endl;
    return 0;
}

