using namespace std;
vector<ll>q[2];
ll x[maxn],y[maxn];
ll bit[100];
int n;
ll solve()
{
    ll ans=0;
    for(ll i=0;i<62;i++)
    {
        ll tot=0;
        q[0].clear();q[1].clear();
        for(ll j=1;j<=n;j++)
            q[(x[j]>>i)&1].push_back(x[j]);
        for(ll j=0;j<q[0].size();j++)
            x[++tot]=q[0][j];
        for(ll j=0;j<q[1].size();j++)
            x[++tot]=q[1][j];
        tot=0;
        q[0].clear();q[1].clear();
        for(ll j=1;j<=n;j++)
            q[(y[j]>>i)&1].push_back(y[j]);
        for(ll j=0;j<q[0].size();j++)
            y[++tot]=q[0][j];
        for(ll j=0;j<q[1].size();j++)
            y[++tot]=q[1][j];
        ll len1=1,len2=1,len3=1;
        ll limit1=1ll<<i;
        ll limit2=1ll<<(i+1);
        ll all=(1ll<<(i+1))-1;
        ll sum=0;
        for(ll j=n;i>=1;i--)
        {
            while((((x[j]&all)+(y[len1]&all))<limit1) && (len1<=n)) len1++;
            while((((x[j]&all)+(y[len2]&all))<limit2) && (len2<=n)) len2++;
            while(((x[j]&all)+(y[len3]&all)<limit1+limit2) && (len3<=n)) len3++;
            sum+=n-(len1-1-len2+1+len3-1);
        }
        if(sum&1) ans+=bit[i];
    }
    return ans;
}

