      continue;

    size_t i1=0, i2=0, i3=0;
    unsigned cur=0;
    for (size_t j=N; j--;) {
      while (i1 < N && a[j]+b[i1] < 1*i) ++i1;
      while (i2 < N && a[j]+b[i2] < 2*i) ++i2;
      while (i3 < N && a[j]+b[i3] < 3*i) ++i3;
      cur += (i2-i1) + (N-i3);
    }

    if (cur & 1)
      res |= i;

    for (size_t j=0; j<N; ++j) {
      a[j] &= i-1;
      b[j] &= i-1;
    }
    rxsort(a.begin(), a.end(), k);
    rxsort(b.begin(), b.end(), k);
  }

  printf("%u\n", res);
}

