ll ar[MAX_10p5 * 2], br[MAX_10p5 * 2];

ll solv(ll t) {
	ll ret = 0;
	repi(i, 0, N) {
		ar[i] = a[i] % (2 * t);
		br[i] = b[i] % (2 * t);
	}
	sort(br, br + N);
	repi(i, 0, N) {
		ll p1 = distance(br, lower_bound(br, br + N, 1 * t - ar[i]));
		ll p2 = distance(br, lower_bound(br, br + N, 2 * t - ar[i])) - p1;
		ll p3 = distance(br, lower_bound(br, br + N, 3 * t - ar[i])) - p1 - p2;
		ll p4 = N - p1 - p2 - p3;
		ret += (p2 + p4) % 2;
	}
	return ret % 2;
}

