#define FOR(i, a, b) for(int (i) = (a); (i) < (b); ++(i))
#define REP(i, n) FOR(i, 0, n)

std::vector<uint> A, B, P, Q;

bool isBitUpAllXor(int n, int t){
    uint mask1 = 1U << t;
    uint mask2 = 1U << (t + 1); bool res = false;
    REP(i, n) P[i] = A[i] & (mask2 - 1), Q[i] = B[i] & (mask2 - 1);
    std::sort(Q.begin(), Q.end());
    REP(i, n){
        int x = P[i];
        uint u1 = (mask2 < x) ? 0 : mask2 - x,
             l1 = (mask1 < x) ? 0 : mask1 - x,
             u2 = ((mask2 << 1) < x) ? 0 : (mask2 << 1) - x,
             l2 = ((mask1 | mask2) < x) ? 0 : (mask1 | mask2) - x;
        auto uitr1 = std::lower_bound(Q.begin(), Q.end(), u1),
             litr1 = std::lower_bound(Q.begin(), Q.end(), l1),
             uitr2 = std::lower_bound(Q.begin(), Q.end(), u2),
             litr2 = std::lower_bound(Q.begin(), Q.end(), l2);
        uint s1 = std::distance(litr1, uitr1);
        uint s2 = std::distance(litr2, uitr2);
        if((s1 ^ s2) & 1) res = not res;
    }
    return res;
}

