  //static constexpr std::size_t W = sizeof(__m512) / sizeof(float);

  int N;
  fin >> N;
  int* A;
  int* B;
  int* ans;
  posix_memalign((void**)&A, 32, N * sizeof(int));
  posix_memalign((void**)&B, 32, N * 2 * sizeof(int));
  posix_memalign((void**)&ans, 32, 4 * sizeof(int));

  rep(i, 0, N) fin >> A[i];
  rep(i, 0, N) fin >> B[i], B[i + N] = B[i];

  __m128i ansm = _mm_set_epi32(0, 0, 0, 0);
  int res = 0;
  for(int i = 0;i < N;i++) {
    int j;
    for(j = 0;j + 3 < N;j += 4) {
      __m128i am = _mm_loadu_si128((__m128i*)(A + j));
      __m128i bm = _mm_loadu_si128((__m128i*)(B + i + j));
      __m128i cm = _mm_add_epi32(am, bm);
      ansm = _mm_xor_si128(ansm, cm);
    }
    for(;j < N;j++) {
      res ^= (A[j] + B[i + j]);
    }
  }
  _mm_store_si128((__m128i*)(ans), ansm);
  fout << (ans[0] ^ ans[1] ^ ans[2] ^ ans[3] ^ res) << "\n"; 
}

