	odda = oddb = evena = evenb = 0;
	for (int i = 1; i <= n; i++) {
		scanf("%d",&a[i]);
		if (a[i] & 1) odda++;
		else evena++;
	} 
	for (int i = 1; i <= n; i++) { 
		scanf("%d",&b[i]);
