int getXOR(int offset, int l = 0, int r = n) {
	if(r-l == 1) {
		return b[l]+offset;
	} else {
		int m = (l+r)/2;
		int lx = getXOR(offset, l, m);
		int rx = getXOR(offset, m, r);
		return lx ^ rx;
	}
}


