int main(){
	int n; cin >> n;
	vector<int> a(n),b(n);
	for(int i=0;i<n;i++) cin >> a[i];
	for(int i=0;i<n;i++) cin >> b[i];
	vector<int> bits(30,0);
	for(int k=0;k<bits.size();k++){
		int T=1<<k;
		vector<int> ta(n),tb(b);
		for(int i=0;i<n;i++) {
			ta[i]=a[i]%(T*2);
			tb[i]=b[i]%(T*2);
		}
		sort(tb.begin(),tb.end());
		for(int i=0;i<n;i++){
			auto it1=lower_bound(tb.begin(),tb.end(),T-ta[i]);
			auto it2=lower_bound(tb.begin(),tb.end(),2*T-ta[i]);
			auto it3=lower_bound(tb.begin(),tb.end(),3*T-ta[i]);
			auto it4=lower_bound(tb.begin(),tb.end(),4*T-ta[i]);
			bits[k]+=(it2-it1)+(it4-it3);
		}
	}
	int ans=0;
	for(int k=0;k<bits.size();k++){
		ans+=((bits[k]%2)<<k);
	}
	cout << ans << endl;
}

