		int64_t bi;
		cin >> bi;
		b.push_back(bi);
	}
	int64_t result = 0;
	int64_t dx = 2;
	for (int i = 0; i < 60; ++i) {
		vector<int64_t>ad, bd;
		for (int j = 0; j < n; ++j) {
			ad.push_back(a[j] % dx);
			bd.push_back(b[j] % dx);
		}
		sort(bd.begin(), bd.end());
		int sum = 0;
		for (auto ai : ad) {
			auto r1 = lower_bound(bd.begin(), bd.end(), dx/2 - ai);
			auto r2 = lower_bound(bd.begin(), bd.end(), dx/2*2 - ai);
			auto r3 = lower_bound(bd.begin(), bd.end(), dx/2*3 - ai);
			auto r4 = lower_bound(bd.begin(), bd.end(), dx/2*4 - ai);
			int t1 = distance(r1, r2);
			int t2 = distance(r3, r4);
			sum += t1 + t2;
		}
		if(sum%2==1)
			result += (dx / 2);
		dx *= 2;
	}
	cout << result << endl;
