    for (int bit = 0; bit < 30; bit++)
    {
        vector<ll> Amod,Bmod;
        ll T = (1LL<<bit);
        for(auto a:A) Amod.push_back(a%(1LL<<(bit+1)));
        for(auto b:B) Bmod.push_back(b%(1LL<<(bit+1)));
