  // aを固定して考えたときに a[i] + b[j] の kbit 目が立っているbの条件を探し、
  // 条件を満たすbの数をカウント
  rep(k,30){
    ll T = 1LL<<k;

    rep(i,n) {
      a[i] = _a[i] % (2LL*T);
