const int MAX_N = (int)(2e5 + 5);

int n;
ll a[MAX_N];
ll b[MAX_N];

ll decide(int k) {
  ll t = mypow(2LL, k);

  vector<ll> ma;
  vector<ll> mb;

  for (int i = 0; i < n; ++i) {
    ma.push_back(a[i] % (2LL * t));
    mb.push_back(b[i] % (2LL * t));
  }

  sort(mb.begin(), mb.end());

  ll cnt = 0LL;

  for (auto &e : ma) {
    ll fst = upper_bound(mb.begin(), mb.end(), 2LL * t - e - 1LL) - lower_bound(mb.begin(), mb.end(), t - e);
    ll snd = upper_bound(mb.begin(), mb.end(), 4LL * t - e - 1LL) - lower_bound(mb.begin(), mb.end(), 3LL * t - e);
    cnt += fst + snd;
  }

  return cnt % 2LL;
}

