      ans[keta] += distance(lower_bound(all(B), M*3-i), lower_bound(all(B), M*4-i));
    }
  }
  // debugv(ans);
  ll ANS{};
  rep(keta,0,28){
    ANS += ans[keta]%2*multi(2,keta);
  }
  cout << ANS;
}

