int f(const int bit, const int target, const int orig_a, const int N, const vector<int> ns) {
    int left = -1, right = N, mid;
    while (right - left > 1) {
        mid = left + (right - left) / 2;
        int a = orig_a % (1 << (bit + 1));
        int b = ns[mid] % (1 << (bit + 1));
#ifdef DEBUG
        printf("left: %d, right: %d, mid: %d, a: %d, b: %d\n", left, right, mid, a, b);
#endif
        if (a + b < target) {
            left = mid;
        } else {
            right = mid;
        }
    }
    return right;
}

