template<class T> long long counterSumIsLT(int As, T A[], int Bs, T B[], T val){
  int i = 0;
  int j = Bs;
  long long res = 0;
  while(i < As){
    while(j && A[i] + B[j-1] >= val){
      j--;
    }
    if(!j){
      break;
    }
    while(i<As && A[i] + B[j-1] < val){
      i++;
      res += j;
    }
  }
  return res;
}
