template<class T> void gc(T &x)
{
    char c;
    int s = 0;
    x = 0;

    c = getchar_unlocked();

    if (c == '-') s = 1;
    else if ('0' <= c && c <= '9')  x = c - '0';

    while (true)
    {
        c = getchar_unlocked();

        if (c < '0' || '9' < c) break;
        x = x * 10 + (c - '0');
    }

    if (s) x = -x;
}

int main()
{
    int N;
    if (scanf("%d", &N) < 1) return 0;

    va.resize(N);
    vb.resize(N);
    ta.resize(N);
    tb.resize(N);

    for (int i = 0; i < N; i++)
    {
        gc(va[i]);
    }

    for (int i = 0; i < N; i++)
    {
        gc(vb[i]);
    }

    sort(va.begin(), va.end());
    sort(vb.begin(), vb.end());

    int amax = va[N - 1];
    int bmax = vb[N - 1];

    int d = 2;
    int x = 1;
    int ans = 0;
    while ((d >> 1) <= amax + bmax)
    {
        int t0 = 1 << x;

        for (int i = 0; i < N; i++)
        {
            ta[i] = va[i] % t0;
            tb[i] = vb[i] % t0;
        }

        sort(ta.begin(), ta.end());
        sort(tb.begin(), tb.end());

        int a = 0;
        int suma = 0;
        for (int i = 0; i < N; i++)
        {
            int t1 = 1 << (x - 1);
            int t2 = 2 * t1;

            int l = t1 - ta[i];
            int h = t2 - ta[i];

            int l1 = lower_bound(tb.begin(), tb.end(), l) - tb.begin();
            int u1 = lower_bound(tb.begin(), tb.end(), h) - tb.begin() - 1;

            int t3 = 3 * t1;
            int t4 = 4 * t1;

            l = t3 - ta[i];
            h = t4 - ta[i];

            int l2 = lower_bound(tb.begin(), tb.end(), l) - tb.begin();
            int u2 = lower_bound(tb.begin(), tb.end(), h) - tb.begin() - 1;

            a = 0;
            if (l1 == N)
            {
                // 区間 1 無し
                if (l2 == N)
                {
                    // 区間 2 無し
                    a = 0;
                }
                else
                {
                    // 区間 2 有り
                    a = u2 - l2 + 1;
                }
            }
            else if (l2 == N)
            {
                // 区間 2 無し
                a = u1 - l1 + 1;
            }
            else if (l2 <= u1 && l1 <= u2)
            {
                // 区間が交差する
                a = max(u1, u2) -min(l1, l2) + 1;
            }
            else
            {
                // 区間が交差しない
                a = u1 - l1 + u2 -l2 + 2;
            }
            suma += a;
        }

        if (suma < 0) suma = 0;
        else if (suma % 2 == 0) suma = 0;
        else suma = 1;

        ans += suma * (1 << (x - 1));

        x++;
        d <<= 1;
    }

    printf("%d\n", ans);
    return 0;
}

