inline void readx(int& x)
{
	x=0; int k=1; register char ch=0;
	while (ch<'0' || ch>'9') { ch=getchar(); if (ch=='-') k=-1; }
	while (ch>='0' && ch<='9') { x=x*10+ch-'0'; ch=getchar(); }
	x*=k;
}

inline void process()
{
	for (int i=1;i<=n;i++)
	{
		int pren=0;
		for (int w=0;w<=28;w++)
		{
			if ((a[i]&(1<<w)))
			{
				opos[w]++;
				oset[w][opos[w]]=pren;
			}
			else
			{
				zpos[w]++;
				zset[w][zpos[w]]=pren;
			}
			pren+=((1<<w)&a[i]);
		}
	}

	for (int w=0;w<=28;w++)
	{
		sort(zset[w]+1,zset[w]+zpos[w]+1);
		sort(oset[w]+1,oset[w]+opos[w]+1);
	}
}

inline int BinSearchO(int lim,int wx)
{
	int mid,ansx=0,lx=1,rx=opos[wx];
	while (lx<=rx)
	{
		mid=(lx+rx)>>1;
		if (oset[wx][mid]<lim)
		{
			ansx=mid;
			lx=mid+1;
		}
		else rx=mid-1; 
	}
	return ansx;
}

inline int BinSearchZ(int lim,int wx)
{
	int mid,ansx=0,lx=1,rx=zpos[wx];
	while (lx<=rx)
	{
		mid=(lx+rx)>>1;
		if (zset[wx][mid]<lim)
		{
			ansx=mid;
			lx=mid+1;
		}
		else rx=mid-1; 
	}
	return ansx;
}

int main()
{
	readx(n);
	for (int i=1;i<=n;i++) readx(a[i]);
	for (int i=1;i<=n;i++) readx(b[i]);

	process();

	for (int i=1;i<=n;i++)
	{
		int preb=0,upat;
		for (int w=0;w<=28;w++)
		{
			upat=(1<<w)-preb;//>= inc

			if (((1<<w)&b[i]))//nowbit = 1
			{
				ans[w]+=BinSearchZ(upat,w);
				ans[w]+=opos[w]-BinSearchO(upat,w);
			}
			else//nowbit = 0
			{
				ans[w]+=BinSearchO(upat,w);
				ans[w]+=zpos[w]-BinSearchZ(upat,w);
			}

			preb+=((1<<w)&b[i]);
		}
	}

	for (int w=0;w<=28;w++) ans[w]%=2;
	for (int w=0;w<=28;w++) if (ans[w]) result+=(1<<w);
	printf("%d\n",result);
	return 0;
}

