int N;
vector<long long> a, b;

int main()
{
    long long ans = 0;

    cin >> N;
    a.resize(N);
    b.resize(N);
    for (int i = 0; i < N; i++)
    {
        cin >> a[i];
    }
    for (int i = 0; i < N; i++)
    {
        cin >> b[i];
    }

    vector<long long> aa, bb;
    aa.resize(N);
    bb.resize(N);
    int num;
    for (int k = 0; k < 29; k++)
    {
        long long T1 = pow(2, k);
        long long T2 = 2 * T1;
        long long T3 = 3 * T1;
        long long T4 = 4 * T1;
        for (int i = 0; i < N; i++)
        {
            aa[i] = a[i] % T2;
            bb[i] = b[i] % T2;
        }
        sort(bb.begin(), bb.end());
        num = 0;
        for (int j = 0; j < N; j++)
        {
            int l1 = distance(bb.begin(), lower_bound(bb.begin(), bb.end(), T1 - aa[j]));
            int r1 = distance(bb.begin(), lower_bound(bb.begin(), bb.end(), T2 - aa[j]));
            int l2 = distance(bb.begin(), lower_bound(bb.begin(), bb.end(), T3 - aa[j]));
            int r2 = distance(bb.begin(), lower_bound(bb.begin(), bb.end(), T4 - aa[j]));
            //printf("%d %d %d %d\n", l1, r1, l2, r2);
            num += r1 - l1 + r2 - l2;
        }
        //cout << num << endl;
        ans += T1 * (num % 2);
    }

    cout << ans << endl;

    return 0;
}

