const int maxn = 2e6+6;
int n, A[maxn], B[maxn], C[maxn];

int first_y(const int a, const int x)
{
    int lo = 0, hi = n-1;
    while (lo < hi) {
        const int m = lo+(hi-lo)/2;
        if (a+C[m] >= x)
            hi = m;
        else
            lo = m+1;
    }
    if (!(a+C[lo] >= x))
        return -1;
    return lo;
}

int last_y(const int a, const int x)
{
    int lo = 0, hi = n-1;
    while (lo < hi) {
        const int m = lo+(hi-lo+1)/2;
        if (a+C[m] < x)
            lo = m;
        else
            hi = m-1;
    }
    if (!(a+C[hi] < x))
        return -1;
    return hi;
}

int main()
{
    while (cin >> n) {
        FOR(i,0,n)
            cin >> A[i];
        FOR(i,0,n)
            cin >> B[i];
        int ans = 0;
        FOR(i,0,30) {
            int T = 1<<i;
            FOR(j,0,n)
                C[j] = B[j]%(2*T);
            sort(C,C+n);
            LL cnt = 0;
            FOR(j,0,n) {
                const int a = A[j]%(2*T);
                const int i1 = first_y(a,T);
                const int j1 = last_y(a,2*T);
                if (i1 >= 0 && j1 >= 0 && i1 <= j1)
                    cnt += j1-i1+1;
                const int i2 = first_y(a,3*T);
                const int j2 = last_y(a,4*T);
                if (i2 >= 0 && j2 >= 0 && i2 <= j2)
                    cnt += j2-i2+1;
            }
            if (cnt&1)
                ans += 1<<i;
        }
        cout << ans << endl;
    }
    return 0;
}

