/*
考察1
ビットごとに考える

考察2
kビット目を考える際、2^k+1以降の数は無視できるので
mod 2^(k+1)をとってよい

考察3
すると、ai+bjのとる範囲は 4 * 2^k 未満になり、
kビット目が立つということは
ai+bjが [2^k, 2 * 2^k) [3 * 2^k, 4 * 2^k)
の中に入るということを意味する

すなわち、そのようなai+bjの数を求めるには
各aiについて↑-aiでソートしたbj乗を二分探索する
*/

int main() {
    int N; cin >> N; 
    vector<ll> a(N), b(N);
    for (int i = 0; i < N; i++) cin >> a[i] >> b[i];

    ll k = 28, res = 0, T = 1;
    for (int i = 0; i < k; i++) T *= 2;
    for (k = 28; k >= 0; k--) {
        for (int i = 0; i < N; i++) {
            a[i] = a[i] % (2 * T);
            b[i] = b[i] % (2 * T);
        }
        sort(b.begin(),b.end());
        ll cnt = 0;
        for (int i = 0; i < N; i++) {
            cnt +=
            (lower_bound(b.begin(),b.end(),2*T-a[i]) -
            lower_bound(b.begin(),b.end(),T-a[i])) +
            (lower_bound(b.begin(),b.end(),4*T-a[i]) -
            lower_bound(b.begin(),b.end(),3*T-a[i]));

        }
        if (cnt % 2 == 1) res += T;

        T /= 2;
    }
    cout << res << endl;
}

