    REP(i, N) { cin >> a_in[i]; }

    REP(i, N) { cin >> b_in[i]; }

    int res = 0;
    for (int k = sizeof(int) * 8 - 2; k >= 0; --k) {
        res <<= 1;

        REP(i, N) {
            a[i] = a_in[i] % (1 << (k + 1));
            b[i] = b_in[i] % (1 << (k + 1));
        }

        sort(ALL(a));
        sort(ALL(b));

