        int flag = 0;
        REP(i, N) {
            auto l1 = lower_bound(ALL(b), T - a[i]);
            auto u1 = upper_bound(ALL(b), 2 * T - a[i] - 1);

            auto l2 = lower_bound(ALL(b), 3 * T - a[i]);
            auto u2 = upper_bound(ALL(b), 4 * T - a[i] - 1);

            flag = (flag + (u1 - l1) + (u2 - l2)) % 2;
        }
        res |= flag;
    }

    cout << res << endl;

    return 0;
}

