void solve() {
    const int d = 3;
    ll n;
    cin >> n;
    vll a(n), b(n);
    for(ll i = 0; i < n; i++) cin >> a[i];
    for(ll i = 0; i < n; i++) cin >> b[i];
    vvll v(d, vll(n));
    for(ll i = 0; i < d; i++) {
        ll mask = (1 << (i + 1)) - 1;
        for(ll j = 0; j < n; j++) v[i][j] = a[j] & mask;
        sort(v[i].begin(), v[i].end());
    }
    vll cnt(d + 1);
    for(ll i = 0; i < d; i++) {
        ll mask = (1 << (i + 1)) - 1;
        for(ll j = 0; j < n; j++) {
            ll _b = b[j] & mask;
            ll l = lower_bound(v[i].begin(), v[i].end(), (1 << i) - _b) - v[i].begin();
            ll r = upper_bound(v[i].begin(), v[i].end(), mask - _b) - v[i].begin();
            ll k = lower_bound(v[i].begin(), v[i].end(), (1 << i) + mask + 1 - _b) - v[i].begin();
            cnt[i] += r - l + n - k;
        }
    }
    for(ll j = 0; j < n; j++) {
        ll l = lower_bound(v[d-1].begin(), v[d-1].end(), (1 << d) - b[j]) - v[d-1].begin();
        cnt[d] += n - l;
    }
    ll ans = 0;
    for(ll i = 0; i <= d; i++) {
        if(cnt[i] % 2) ans += 1 << i;
    }
    cout << ans << endl;
    return;
}

