long long binary_search(vector<long long> &n, long long x){
    long long ok = (long long)n.size();
    long long ng = - 1;
    while (abs(ok - ng) > 1){
        long long mid = (ok + ng) / 2;
        if (n[mid] >= x) ok = mid;
        else ng = mid;
    }
    return ng;
}

