    // a_i + b_j で、d 桁目の bit が立っている個数を調べる。
    for(int d = 0; d < 30; ++d){
        vector<ll> amod(n), bmod(n);
        int m = 1 << (d + 1);
        // 2^(d+1) で割った余りの数列 (bmod はソートしておく)
        for(int i = 0; i < n; ++i){
            amod[i] = a[i] % m;
            bmod[i] = b[i] % m;
        }
        sort(bmod.begin(), bmod.end());
        ll cnt = 0; // d 桁目の bit が立つ個数
        ll T = 1 << d;
        for(int i = 0; i < n; ++i){
            // amod_i + bmod_j は 4T 未満 (T = 2^d)
            // d 桁目の bit が立つのは、amod_i + bmod_j が [T, 2T) または [3T, 4T) の範囲にあるとき
            cnt += lower_bound(bmod.begin(), bmod.end(), T * 2 - amod[i]) - lower_bound(bmod.begin(), bmod.end(), T - amod[i]);
            cnt += lower_bound(bmod.begin(), bmod.end(), T * 4 - amod[i]) - lower_bound(bmod.begin(), bmod.end(), T * 3 - amod[i]);
        }
        res += (1 << d) * (cnt % 2);
    }
    cout << res << endl;
}

