        for (int i = 0; i < N; i++) {
            c[i] = a[i] % (2 * T);
            d[i] = b[i] % (2 * T);
        }
        sort(d.begin(),d.end());
        ll cnt = 0;
        for (int i = 0; i < N; i++) {
            cnt +=
            (lower_bound(d.begin(),d.end(),4*T-c[i]) -
            lower_bound(d.begin(),d.end(),T-c[i])) -
            (lower_bound(d.begin(),d.end(),3*T-c[i])-
            lower_bound(d.begin(),d.end(),2*T-c[i]));

        }
        if (cnt % 2 == 1) res ^= T;
        //cout << T << " " << cnt << endl;
        T *= 2;
    }
