int bsearch(long long x,vector<int> c){
	int min=0;
	int max=c.size()-1;
	int mid;
	while(true){
		mid=(max+min)/2;
		if(c[mid]>=x) max=mid;
		else min=mid+1;
		if(max<=min) break;
	}
	if(max==c.size()-1 && c[max]<x) max++;
	return max;
}

