                table_0[j].push_back(b[i] % (1 << j));
            } else {
                table_1[j].push_back(b[i] % (1 << j));
            }
        }
    }
    for (int i = 0; i <= 28; i++) {
        sort(table_0[i].begin(), table_0[i].end());
        sort(table_1[i].begin(), table_1[i].end());
    }
    for (int i = 0; i < N; i++) {
        bitset<30> bs(a[i]);
        for (int j = 0; j < bs.size(); j++) {
            int c = (1 << j) - a[i] % (1 << j);
            int noncli_0 = lower_bound(table_0[j].begin(), table_0[j].end(),
                                       c) -
                           table_0[j].begin();

            int noncli_1 = lower_bound(table_1[j].begin(), table_1[j].end(),
                                       c) -
                           table_1[j].begin();
            if (bs[j] == 1) {
                ans[j] += noncli_0;
                ans[j] += table_1[j].size() - noncli_1;
            } else {
                ans[j] += noncli_1;
                ans[j] += table_0[j].size() - noncli_0;
            }
        }
    }
    int abc = 0;
    for (int i = 0; i <= 28; i++) {
        if (ans[i] % 2 == 1) {
            abc += 1 << i;
        }
    }
    cout << abc << endl;
}

