int_t p[30];
int_t t[30][size];

int count(int k, int_t ai) {
  int res = 0;
  auto tk = t[k];
  int c1 = lower_bound(tk, tk+n, p[k] - ai) - lower_bound(tk, tk+n, p[k-1] - ai);
  int c2 = lower_bound(tk, tk+n, p[k+1] - ai) - lower_bound(tk, tk+n, p[k] + p[k-1] - ai);
  return c1 + c2;
}

void solve() {
  p[0] = 1;
  rep (k, 29) {
    p[k+1] = p[k] * 2LL;
  }

  int_t mask = 1;
  rep (k, 28) if (k > 0) {
    rep (i, n) t[k][i] = b[i] & mask;
    sort(t[k], t[k]+n);
    mask = (mask << 1LL) | 1LL;
  }

  int cnt[30];
  fill(cnt, cnt+30, 0);
  int_t mask2 = 1;
  rep (k, 28) if (k > 0) {
    rep (i, n) {
      cnt[k] += count(k, a[i] & mask2);
    }
    mask2 = (mask2 << 1LL) | 1LL;
  }

  int_t res = 0;
  rep (k, 30) if (k > 0) {
    if (cnt[k] % 2) {
      res += 1LL << (k-1);
    }
  }
  cout << res << endl;
}

