          itrr--;
          sum = Bsum - (*itrr).second;
        }
        else
        {
          itrl--;
          itrr--;
          sum = Bsum - ((*itrr).second - (*itrl).second);
        }
      }
      else
      {
        auto itrl = SmodB.lower_bound(target / 2 - p.first);
        auto itrr = SmodB.lower_bound(target - p.first);
        if (itrl == begin(SmodB))
        {
          itrr--;
          sum = (*itrr).second;
        }
        else
        {
          itrl--;
          itrr--;
          sum = ((*itrr).second - (*itrl).second);
        }
      }
      //OUT2(itrl->first, itrr->first);
      OUT2("sum:", sum);
      OUT2("p.first:", p.first);
      OUT2("p.second:", p.second);
      cnt += sum * p.second;
    }

    OUT2("cnt:", cnt);
    if (cnt % 2 != 0)
      ans += BIT(k);
  }
  cout << ans << endl;
  return 0;
