    REP(i, 30)
    {
        ll m = 0;
        D[i] = 0;
        REP(j, i + 1)
        {
            m |= (1 << j);
        }
        ll u = pow((ll)2, i);
        ll t = pow((ll)2, (i + 1));
        REP(j, N)
        {
            C[j] = (B[j] & m) % u;
        }
