        REP(j, N)
        {
            ll a = (A[j] & m) % u;
            {
                int ui = getUnder(u - a);
                int ti = getTop(t - a);
                if (ui <= ti)
                {
                    D[i] += (ti - ui + 1);
                }
            }
        }
    }

    ll ans = 0;
    REP(i, 30)
    {
        ans |= ((D[i] % 2) << i);
    }
