#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// digit は0始まり.
bool isBitOn(int target, int digit);
// digit 以下のビットを取得する
int getUnderBits(int target, int digit);
// digit だけ bit が立ったマスクを取得する
int getOnMask(int digit);
int main(){
	int n;
	cin >> n;
	vector<int> a(n);
	vector<int> b(n);
	for(int i = 0; i < n; i++){
		cin >> a[i];
	}
	for(int i = 0; i < n; i++){
		cin >> b[i];
	}
	// ソート
	sort(a.begin(), a.end());
	sort(b.begin(), b.end());
	// 回答編
	int ans = 0;

	// 余裕をもって、c を n の4倍の大きさで用意する
	// 使用するのは 0 ~ 3n-1
	vector<int> c(4*n);
	// 0 <= (a, b) < pow(2, 28)
	for(int i = 0; i < 29; i++){
		// c のn-1番目までを更新してソート
		for(int j = 0; j < n; j++){
			c[j] = getUnderBits(b[j], i);
		}
		sort(c.begin(), c.begin() + n);
		// c の n番目から　2n-1 番目までを更新
		for(int j = 0; j < 2*n; j++){
			c[n+j] = c[j] + getOnMask(i + 1);
		}
		// total の用意
		long long total = 0;
		for(int j = 0; j < n; j++){
			// a の i 桁以下を用意
			int y = getUnderBits(a[j], i);
			// 和が範囲内に収まる要素の数を数える
			total += lower_bound(c.begin(), c.begin() + 3 * n, (4<<i)-y)
					- lower_bound(c.begin(), c.begin() + 3 * n, (3<<i)-y);
		}
		// total が奇数であれば ans のこの桁を立てる
		// 1 を奇数個 xor すると 1
		// , 1 を偶数個 xor すると 0
		if(total%2) ans += getOnMask(i);
	}

	cout << ans << endl;
	return 0;
}
// digit は0始まり.
bool isBitOn(int target, int digit){
	return target & (1 << digit);
}
// digit 以下のビットを取得する
int getUnderBits(int target, int digit){
	// i.e.
	// getUnderBits(0b11111111, 3)
	// returns     0b00001111
	return target & ((1 << (digit + 1)) - 1);
}
// digit だけ bit が立ったマスクを取得する
int getOnMask(int digit){
	return 1 << digit;
}

