// target is k-th bit (0<=k<=28)
//  if a_i>=2^k (carry_up)
//   2^k+2^(k+1)-a_i <= b_j < 2^(k+1)
//   0 <= b_j < 2^(k+1)-a_i
//  else
//   2^k-a_i <= b_j < 2^(k+1)-a_i

int main(){
    int i,j,k,ans,m,cnt;
    int bekihigh,bekilow;

    cin >> N;
    a.resize(N);
    b.resize(N);

    for(i=0;i<N;i++){
        cin >> a[i];
    }
    for(i=0;i<N;i++){
        cin >> b[i];
    }
    cnt=0;
    ans=0;

    for(k=28;k>=0;k--){
        bekihigh=1<<(k+1);
        bekilow=1<<k;

        for(i=0;i<N;i++){
            a[i]%=bekihigh;
            b[i]%=bekihigh;
        }

        sort(b.begin(),b.end());
        cnt=0;

        for(i=0;i<N;i++){
            if(a[i]<=bekilow){
                cnt+=lower_bound(b.begin(),b.end(),bekihigh-a[i])-lower_bound(b.begin(),b.end(),bekilow-a[i]);
            }
            else{
                cnt+=lower_bound(b.begin(),b.end(),bekihigh-a[i])-b.begin();
                cnt+=lower_bound(b.begin(),b.end(),bekihigh)-lower_bound(b.begin(),b.end(),bekihigh+bekilow-a[i]);
            }

        }
        if(cnt%2){
            ans|=1<<k;
        }
    }
    printf("%d\n",ans);

    return 0;
}

