using namespace std;

typedef long long int;

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);
  int N; cin >> N;
  int a[N], b[N];
  for(int i=0;i<N;i++) cin >> a[i];
  for(int i=0;i<N;i++) cin >> b[i];
  int ans = 0;
  for(int i=0;i<30;i++){
    int bitb[N];
    for(int x=0;x<N;x++){
      // b[x] mod 2^(b+1)
      bitb[x] = b[x] %(1 << (i+1));
    }
    sort(bitb, bitb+N);
    int tot = 0;
    for(int x=0;x<N;x++){
      int bita = a[x] %(1 << (i+1));
      // count [2^i - a_i, 2*2^i - a_i)
      tot += lower_bound(bitb, bitb+N, 2*(1 << i) - bita) - lower_bound(bitb, bitb+N, (1 << i) - bita);
      // count [3*2^i - a_i, 4*2^i - a_i)
      tot += lower_bound(bitb, bitb+N, 4*(1 << i) - bita) - lower_bound(bitb, bitb+N, 3*(1 << i) - bita);
    }
    // cout << tot << endl;
    if(tot %2 == 1) ans = ans + (1 << i);
  }
  cout << ans << endl;
}

