    for(int j=0; j<31; j++){
        pow2[j+1] = pow2[j] * 2;
    }

    vector<vector<int>> a(30, vector<int>(n)), b(30, vector<int>(n));
    for(int i=0; i<n; i++){
        cin >> a[29][i];
        for(int j=28; j>=0; j--){
            a[j][i] = a[j+1][i] % pow2[j+1];
        }
    }
    for(int i=0; i<n; i++){
        cin >> b[29][i];
        for(int j=28; j>=0; j--){
            b[j][i] = b[j+1][i] % pow2[j+1];
        }
    }
    for(int j=29; j>=0; j--){
        sort(b[j].begin(), b[j].end());
    }

    int ans = 0;// total XOR
    for(int j=0; j<30; j++){// each bit
        int bit = 0;
        for(int i=0; i<n; i++){
            bit += lower_bound(b[j].begin(), b[j].end(), pow2[j+1] - a[j][i]) // 0 11...1 ~
                 - lower_bound(b[j].begin(), b[j].end(), pow2[j]   - a[j][i]);// 0 10...0
            if(j+2 < 31){
            bit += lower_bound(b[j].begin(), b[j].end(), pow2[j+2]           - a[j][i]) // 1 11...1 ~
                 - lower_bound(b[j].begin(), b[j].end(), pow2[j+1] + pow2[j] - a[j][i]);// 1 10...0   
            }         
        }
        ans += (bit % 2) * pow2[j];
    }
    cout << ans << endl;
