#define mygc(c) (c)=getchar_unlocked()
#define mypc(c) putchar_unlocked(c)
void reader(int *x) { int k, m = 0; *x = 0; for (;;) { mygc(k); if (k == '-') { m = 1; break; }if ('0' <= k&&k <= '9') { *x = k - '0'; break; } }for (;;) { mygc(k); if (k<'0' || k>'9')break; *x = (*x) * 10 + k - '0'; }if (m)(*x) = -(*x); }
void writer(int x, char c) { int s = 0, m = 0; char f[10]; if (x<0)m = 1, x = -x; while (x)f[s++] = x % 10, x /= 10; if (!s)f[s++] = 0; if (m)mypc('-'); while (s--)mypc(f[s] + '0'); mypc(c); }


constexpr int MAX_N = 200000;
int n, a[MAX_N], b[MAX_N];

int main() {
    // Input
    reader(&n);
    for (int i = 0; i < n; ++i) reader(&a[i]);
    for (int i = 0; i < n; ++i) reader(&b[i]);

    // Solve
    constexpr int block_a = 4, block_b = 8192;
    int ans = 0;
    for (int i = 0; i + (block_a - 1) < n; i += block_a) {
        const int a0 = a[i], a1 = a[i + 1], a2 = a[i + 2], a3 = a[i + 3];

        for (int j = 0; j + (block_b - 1) < n; j += block_b)
            for (int k = j; k < j + block_b; ++k)
                ans ^= (a0 + b[k]) ^ (a1 + b[k]) ^ (a2 + b[k]) ^ (a3 + b[k]);

        for (int j = n & ~(block_b - 1); j < n; ++j)
            ans ^= (a0 + b[j]) ^ (a1 + b[j]) ^ (a2 + b[j]) ^ (a3 + b[j]);
    }

    // rest of iterations
    for (int i = n & ~(block_a - 1); i < n; ++i) {
        const int a0 = a[i];

        for (int j = 0; j + (block_b - 1) < n; j += block_b)
            for (int k = j; k < j + block_b; ++k)
                ans ^= a0 + b[k];

        for (int j = n & ~(block_b - 1); j < n; ++j)
            ans ^= a0 + b[j];
    }

    // Output
    writer(ans, '\n');

    return 0;
}

