const unsigned int nmax = 204800, block = 8192, unrl = 8;
unsigned int a[nmax], b[nmax];

int main() {

	unsigned int N;
	scanf("%d", &N);
	for (unsigned int i = 0; i < N; i++) scanf("%d", &a[i]);
	for (unsigned int i = 0; i < N; i++) scanf("%d", &b[i]);

	unsigned int ans = 0;
	for (unsigned int i = 0; i + unrl <= N; i += unrl) {
		for (unsigned int j = 0; j + block <= N; j += block) {
			for (unsigned int k = j; k < block + j; k++) {

				ans ^= (a[i + 0] + b[k]) ^ (a[i + 1] + b[k]);
				ans ^= (a[i + 2] + b[k]) ^ (a[i + 3] + b[k]);
				ans ^= (a[i + 4] + b[k]) ^ (a[i + 5] + b[k]);
				ans ^= (a[i + 6] + b[k]) ^ (a[i + 7] + b[k]);

			}
		}
	}

	for (unsigned int i = 0; i < N / unrl * unrl; i++) {
		for (unsigned int j = N / block * block; j < N; j++) {
			ans ^= a[i] + b[j];
		}
	}	
	for (unsigned int i = N / unrl * unrl; i < N; i++) {
		for (unsigned int j = 0; j < N; j++) {
			ans ^= a[i] + b[j];
		}
	}

	printf("%d\n", ans);

	return 0;
}

