int N;
int A[200000],B[200000],b[200000];
int ans=0;

int main(){
  std::ios::sync_with_stdio(false);
  std::cin.tie(0);

  // ifstream in("input.txt");
  // cin.rdbuf(in.rdbuf());

  cin>>N;
  REP(i,N) cin>>A[i];
  REP(i,N) cin>>B[i];

  REP(k,29){
    ll T = 1<<k;
    REP(i,N) b[i]=B[i]%(2*T);
    sort(b, b+N);
    ll t_sum=0;

    REP(i,N){
      // a固定
      ll fix_a = A[i]%(2*T);
      int T01 = lower_bound(b,b+N,T-fix_a) - b;
      int T12 = lower_bound(b,b+N,2*T-fix_a) - b;
      int T23 = lower_bound(b,b+N,3*T-fix_a) - b;
      t_sum += (T12 - T01) + (N - T23);
    }
    if(t_sum%2 == 1) ans += T;
  }
  P(ans);
