            //x1<= b < x2 or x3 <= b < x4
            int x1 = (1 << k) - a2;
            int x2 = (1 << (k + 1)) - a2;
            int x3 = x1 + (1 << (k + 1));
            int x4 = x2 + (1 << (k + 1));

            vector<int>::iterator i1 = lower_bound(b2.begin(), b2.end(), x1);
            vector<int>::iterator i2 = lower_bound(b2.begin(), b2.end(), x2);
            vector<int>::iterator i3 = lower_bound(b2.begin(), b2.end(), x3);
            vector<int>::iterator i4 = lower_bound(b2.begin(), b2.end(), x4);

            xorv[k] = (xorv[k] + distance(i1, i2) + distance(i3, i4)) % 2;

        }
    }

    int ans = 0;
    REP(i, d){
        ans += xorv[i] * (1 << i);
    }

    cout << ans;

    return 0;
}








