const ll MOD = 1e9 + 7;

class DTwoSequences {
public:
    void solve(std::istream& in, std::ostream& out) {
        ll N;
        in >> N;
        vector<ll> a(N), b(N);
        REP(i,0,N) in >> a[i];
        REP(i,0,N) in >> b[i];

        ll answer = 0;
        REP(i,0,29) {
            const ll T = 1LL << i;
            vector<ll> modB(N);
            REP(j,0,N) modB[j] = b[j] % (2 * T);
            sort(all(modB));
            ll cnt = 0;
            REP(j,0,N) { // fix a = a[j]
                const ll modA = a[j] % (2 * T);
                // [T, 2T)
                cnt += distance(lower_bound(all(modB), T-modA), lower_bound(all(modB), 2*T-modA));
                // [3T, 4T)
                cnt += distance(lower_bound(all(modB), 3*T-modA), lower_bound(all(modB), 4*T-modA));
            }
            if (cnt % 2 == 1) {
                answer += T;
            }
        }
        out << answer << "\n";
    }
};


signed main() {
    DTwoSequences solver;
    std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

