int_t processSubSeq(vector<int_t>& Ais, vector<int_t>& Bis, int aBegin, int aEnd, int bBegin, int bEnd) {
    if (aBegin == aEnd || bBegin == bEnd) {
        return 0;
    }
    if (aEnd - aBegin == 1 && bEnd - bBegin == 1) {
        return Ais[aBegin] + Bis[bBegin];
    }
    int aLenHalf = (aEnd - aBegin) / 2;
    int bLenHalf = (bEnd - bBegin) / 2;
    int_t x1 = processSubSeq(Ais, Bis, aBegin, aBegin + aLenHalf, bBegin, bBegin + bLenHalf);
    int_t x2 = processSubSeq(Ais, Bis, aBegin, aBegin + aLenHalf, bBegin + bLenHalf, bEnd);
    int_t x3 = processSubSeq(Ais, Bis, aBegin + aLenHalf, aEnd,   bBegin, bBegin + bLenHalf);
    int_t x4 = processSubSeq(Ais, Bis, aBegin + aLenHalf, aEnd,   bBegin + bLenHalf, bEnd);
    return x1 ^ x2 ^ x3 ^ x4;
}

