ll pow(ll n, ll k) {
    if (k == 0) return 1;
    if (k == 1) return n;
    return pow(n, k/2) * pow(n, k/2) * pow(n, k%2);
}

ll N;
int main(){
    ios::sync_with_stdio(false);
    cin >> N;
    vector<int> a(N);
    vector<int> b(N);
    vector<int> atmp(N);
    vector<int> btmp(N);
