            btmp[i] = b[i] % mod_num;
            atmp[i] = a[i] % mod_num;
        }
        sort(btmp.begin(), btmp.end());

        int one_num = 0;
        REP (i, N) {
            // [T, 2*T)
            int s = (int) (lower_bound(btmp.begin(), btmp.end(), T - atmp[i]) - btmp.begin());
            int e = (int) (lower_bound(btmp.begin(), btmp.end(), 2 * T - atmp[i]) - btmp.begin());
            one_num += e - s;

            // [3*T, 4*T)
            s = (int) (lower_bound(btmp.begin(), btmp.end(), 3 * T - atmp[i]) - btmp.begin());
            e = (int) (lower_bound(btmp.begin(), btmp.end(), 4 * T - atmp[i]) - btmp.begin());
            one_num += e - s;
        }
        ans += pow(2, k) * (one_num % 2);
    }
    cout << ans << endl;
    return 0;
}

