typedef long long ll;

const int INF = 1000000000;

int main()
{
  int n;
  scanf("%d", &n);
  vector<ll> a(n), b(n);
  for (int i = 0; i < n; ++i) { scanf("%lld", &a[i]); }
  for (int i = 0; i < n; ++i) { scanf("%lld", &b[i]); }

  ll ans = 0;
  for (int bit = 0; bit < 30; ++bit) {
    ll T = (1 << bit);
    vector<ll> aa(n), bb(n);
    for (int i = 0; i < n; ++i) {
      aa[i] = a[i] % (2 * T);
      bb[i] = b[i] % (2 * T);
    }
    sort(aa.begin(), aa.end());
    sort(bb.begin(), bb.end());
    int cnt = 0;
    for (int i = 0; i < n; ++i) {
      cnt += upper_bound(bb.begin(), bb.end(), 2 * T - aa[i] - 1) -
        lower_bound(bb.begin(), bb.end(), T - aa[i]);
      cnt += upper_bound(bb.begin(), bb.end(), 4 * T - aa[i] - 1) -
        lower_bound(bb.begin(), bb.end(), 3 * T - aa[i]);
    }
    ans |= (1 << bit) * (cnt % 2);
  }

  printf("%lld\n", ans);
  return 0;
}

