void solve(int biti) {
	int t = (1 << (biti + 1));
	for (int i = 0; i < n; i++) {
		a_bit[i] = a[i] % t;
//		cout << a_bit[i] << " * * ";
	}
//	cout << endl;
	for (int i = 0; i < n; i++) {
		b_bit[i] = b[i] % t;
//		cout << b_bit[i] << "  &  ";
	}
//	cout << endl << endl;
//	sort(a_bit, a_bit + n);
	sort(b_bit, b_bit + n);
	int t2 = t / 2;
//	cout << t2 << " *** \n";
//	for (int i = 0; i < n; i++)
//		cout << a_bit[i] << "   ";
//	cout << endl;
//	for (int i = 0; i < n; i++)
//		cout << b_bit[i] << "  /  ";
//	cout << endl;
	for (int i = 0; i < n; i++) {
		int dif = t2 - a_bit[i],
			dif2 = t - a_bit[i];
		auto k = lower_bound(b_bit, b_bit + n, dif) - b_bit,
			 k2 = lower_bound(b_bit, b_bit + n, dif2) - b_bit;
//		cout << dif << "  **  " << dif2 << "  ^& ";
//		cout << k2 - k << " --- \n";
		num_bit[biti] += k2 - k;
	}
	for (int i = 0; i < n; i++) {
		int dif = t2 - a_bit[i] + t,
			dif2 = t - a_bit[i] + t;
		auto k = lower_bound(b_bit, b_bit + n, dif) - b_bit,
			 k2 = lower_bound(b_bit, b_bit + n, dif2) - b_bit;
		num_bit[biti] += k2 - k;
	}
