long long POW(long long a, long long n) {
	long long x = 1LL;
	for (; n > 0; n >>= 1, a *= a)
		x *= (n & 1 == 1) ? a : 1;
	return x;
}

int main()
{
	int N;
	cin >> N;
	vi a(N), b(N);
	cin >> a >> b;

	int ans = 0;

	int mod = POW(2, 29);
	for (int bit = 28; bit >= 0; bit--) {
		for (int idx = 0; idx < N; idx++) {
			a[idx] %= mod;
			b[idx] %= mod;
		}

		sortall(b);

		int tmp = 0;
		for (int aidx = 0; aidx < N; aidx++) {
			int T1 = (mod >> 1) - a[aidx];
			int T2 = mod - a[aidx];
			int T3 = (mod >> 1) * 3 - a[aidx];
			int T4 = (mod << 1) - a[aidx];
			int bottomidx = lower_bound(all(b), T1) - b.begin();
			int topidx = lower_bound(all(b), T2) - b.begin();
			tmp += topidx - bottomidx;
			bottomidx = lower_bound(all(b), T3) - b.begin();
			topidx = lower_bound(all(b), T4) - b.begin();
			tmp += topidx - bottomidx;
		}

		if (tmp % 2 == 1) {
			ans += POW(2, bit);
		}

		mod >>= 1;
	}

	cout << ans << endl;

	return 0;
}

