        ll t = 1LL << i;

        ll now = 0;
        for (ll a  : mod_as) {
            ll t1 = t - a;
            ll t2 = 2 * t - a;
            ll t3 = 3 * t - a;
            ll t4 = 4 * t - a;

            auto l1 = lower_bound(mod_bs.begin(), mod_bs.end(), t1);
            auto r1 = lower_bound(mod_bs.begin(), mod_bs.end(), t2);
            auto l2 = lower_bound(mod_bs.begin(), mod_bs.end(), t3);
            auto r2 = lower_bound(mod_bs.begin(), mod_bs.end(), t4);
            now += (r1 - l1) + (r2 - l2);

        }

        ll bit = now % 2;
        ll i_ans = bit << i;
        ans += i_ans;
    }

    cout << ans << endl;

}

