int main() {
	using uint32 = unsigned int;
	uint32 n;
	scanf("%u", &n);
	std::vector<uint32> a(n), b(n), c(n);
	for (auto& e : a)
		scanf("%u", &e);
	for (auto& e : b)
		scanf("%u", &e);
	uint32 ans = 0;
	if (n & 1) {
		for (const auto e : a)
			ans ^= e;
		for (const auto e : b)
			ans ^= e;
	}
	for (uint32 i = 1;i <= 28;++i) {
		const auto pbit = static_cast<uint32>(1) << i;
		for (uint32 j = 0;j < n;++j)
			c[j] = b[j] & (pbit - 1);
		WaveletMatrix<uint32, 28> W(c);
		for (const auto e : a)
			if (W.more_than(0, n, ~e&(pbit - 1)) & 1)
				ans ^= pbit;
	}
	printf("%u\n", ans);
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
int p0,p1,q0,q1,v,pos;
long long ans=0;
int a[200000],b[200000],arr[28][200000],t[200000];
int main()
{
	int i,j,n;
	scanf("%d",&n);
	for(i=0;i<n;i++)
		scanf("%d",&a[i]);
	for(i=0;i<n;i++)
		scanf("%d",&b[i]);	
	for(i=0;i<28;i++)
	{
		p0=p1=q0=q1=0;
		for(j=0;j<n;j++)
		{
			((a[j]>>i)&0x01)?p0++:p1++;
		}
		for(j=0;j<n;j++)
		{
			((b[j]>>i)&0x01)?q0++:q1++;	
		}
		ans^=((p0*q1)%2+(p1*q0)%2)%2;
	}
	//生成第一排arr[28][n]的
	for(i=0;i<28;i++)
	{
		for(j=0;j<n;j++)
		{
			if(i==0)
				arr[i][j]=0x01&a[j];
			else
				arr[i][j]=arr[i-1][j]|((1<<i)&a[j]);
		}
	} 
	for(i=0;i<28;i++)
		sort(arr[i],arr[i]+n);
	for(i=0;i<28;i++)
	{
		for(j=0;j<n;j++)
		{
			t[j]|=(1<<i)&b[j];
			v=(1<<(i+1))-t[j];	
			pos=lower_bound(arr[i],arr[i]+n,v)-arr[i];
           	if(n-pos==1)
			    ans^=1<<(i+1); 
			else 
				ans^=((n-pos)%2)<<(i+1);
		}
	}	
	printf("%lld",ans);	 
	return 0;
}

