#include <iostream>
#include <emmintrin.h>
int a[200000], b[200000];
int i, j, k, lim;
constexpr int block = 8192;
int n_blo;
signed main() {
	int n;
	scanf("%d", &n);
	n_blo = n - block;
	int r = n & 3;
	int l = n - r;
	for (i = 0; i < n; ++i)
		scanf("%d", &a[i]);
	for (i = 0; i < n; ++i)
		scanf("%d", &b[i]);
	__m128i temp = _mm_set1_epi32(0);
	__m128i val0;
	__m128i val1;
	for (i = 0; i < l; i += 4) {
		val0 = _mm_load_si128((__m128i*) &a[i]);
		for (j = 0; j <= n_blo; j += block) {
				lim = j + block;
				for (k = j; k < lim; ++k) {
					val1 = _mm_set1_epi32(b[k]);
					temp = _mm_xor_si128(_mm_add_epi32(val0, val1), temp);
				}
		}
		lim = n & ~(block - 1);
		for (j = lim; j < n; ++j) {
				val1 = _mm_set1_epi32(b[j]);
				temp = _mm_xor_si128(_mm_add_epi32(val0, val1), temp);
		}
	}
	int re[4];
	_mm_store_si128((__m128i*)re, temp);
	int ans = re[0] ^ re[1] ^ re[2] ^ re[3];
	for (i = l; i < n; ++i) {
		for (j = 0; j <= n_blo; j += block) {
			lim = j + block;
			for (k = j; k < lim; ++k) {
				ans ^= a[i] + b[k];
			}
			lim = n & ~(block - 1);
			for (j = lim; j < n; ++j) {
				ans ^= a[i] + b[j];
			}
		}
	}
	printf("%d", ans);
	return 0;
}

