int N;
llint a[200010], b[200010];
llint modB[30][200010];


void makeModAB(){
	rep(i, 0, 28){
		rep(j, 0, N) modB[i][j] = b[j]%(1LL<<(i+1));
		sort(RNG(modB[i], N));
	}
}


llint solve(){
	llint ans = 0;
	rep(i, 0, 4){
		int cnt = 0;
		rep(j, 0, N){
			llint modA = a[j]%(1LL<<(i+1));
			llint T = 1LL<<i;
			int l = lb(RNG(modB[i], N), T-modA)-&modB[i][0];
			int r = lb(RNG(modB[i], N), 2*T-modA)-&modB[i][0];
			cnt += r-l;
			l = lb(RNG(modB[i], N), 3*T-modA)-&modB[i][0];
			r = lb(RNG(modB[i], N), 4*T-modA)-&modB[i][0];
			cnt += r-l;
		}
		if(cnt%2 == 1) ans += (1LL<<i);
	}
	return ans;
}


signed main(){
	cin >> N;
	rep(i, 0, N) cin >> a[i];
	rep(i, 0, N) cin >> b[i];

	makeModAB();

	cout << solve() << endl;

	return 0;
}

#include<bits/stdc++.h>
#define ll long long
#define N 200010
using namespace std;

int n, a[N], b[N], ans;
int rev[35];
vector<int> va, vb;

int main()
{
    //freopen("in.txt", "r", stdin);
    //freopen("out.txt","w",stdout);
    scanf("%d", &n);
    for(int i = 1; i <= n; i ++) scanf("%d", &a[i]);
    for(int i = 1; i <= n; i ++) scanf("%d", &b[i]);
    rev[0] = 1;
    for(int i = 1; i <= 30; i ++) rev[i] = rev[i - 1] << 1;
    for(int k = 0; k <= 29; k ++)
    {
        int tans = 0;
        va.clear(), vb.clear();
        for(int j = 1; j <= n; j ++) va.push_back(a[j] % rev[k + 1]);
        for(int j = 1; j <= n; j ++) vb.push_back(b[j] % rev[k + 1]);
        sort(va.begin(), va.end());
        sort(vb.begin(), vb.end());
        for(int i = va.size() - 1; i >= 0; i --)
        {
            int l = lower_bound(vb.begin(), vb.end(), rev[k] - va[i]) - vb.begin();
            int r = lower_bound(vb.begin(), vb.end(), rev[k + 1] - va[i]) - vb.begin();
            tans = (tans + r - l) % 2;
            l = lower_bound(vb.begin(), vb.end(), rev[k] + rev[k + 1] - va[i]) - vb.begin();
            tans = (tans + vb.size() - l) % 2;
        }
        if(tans & 1) ans += rev[k];
    }
    printf("%d\n", ans);
    return 0;
}

