const int N_2 = 28;



int main(void){
  SPEEDUP
  cout << setprecision(15);
  int N;cin >> N;
  ++N;

  //入力
  int a[N],b[N];
  //c[j],d[j];a[j],b[j]のi桁以下の数字
  int c[N],d[N];
  rep(i,N) cin >> a[i+1];
  rep(i,N) cin >> b[i+1];
  a[0] = b[0] = 0;

  int ans = 0;
  rep(i,N_2){
    //i桁目の1の個数
    int na_digit=0,nb_digit=0;
    //i桁目の和のXOR
    int digit_sum=0;
    rep(j,N){
      na_digit^=(a[j]>>i)&1;
      nb_digit^=(b[j]>>i)&1;
    }
    //桁上げを考慮しないi桁目のXOR
    digit_sum = (na_digit+nb_digit)*N&1;
    if(i==0){
      ans+=digit_sum;
      continue;
    }

    rep(j,N){
      c[j] = a[j]&((1<<i)-1);
      d[j] = b[j]&((1<<i)-1);
    }
    sort(c,c+N);
    sort(d,d+N);

    int r = N-1;
    rep(j,N){
      while(d[r]+c[j] >= (1<<i))r--;
      digit_sum ^= (N-1-r)&1;
    }
    ans += digit_sum<<i;
  }
  cout << ans << endl;

  return 0;
}

