			if (not(t1 == mb.end() and t2 == mb.end()))
				cnt += ll(t2 - t1) - 1;
			auto t3 = lower_bound(all(mb), k2 * 3 - ma);
			auto t4 = lower_bound(all(mb), k2 * 4 - ma);
			if (not(t1 == mb.end() and t2 == mb.end()))
				cnt += ll(t4 - t3) - 1;
		}
		if (odd(cnt))
			ans += k2;
	}
	out(ans);

