    for (auto i = 0; i < n; i++)
        cin >> a[i];
    for (auto i = 0; i < n; i++)
        cin >> b[i];
    ll ans = 0;
    for (auto i = 0; i < 22; i++) {
        vector<int> c(n), d(n);
        auto t = (1 << i);
        for (auto j = 0; j < n; j++) {
            c[j] = a[j] % (t * 2);
            d[j] = b[j] % (t * 2);
        }
        sort(d.begin(), d.end());
        ll num = 0;
        for (auto j = 0; j < n; j++) {
            if ((c[j] & t) == 0) {
                num += lower_bound(d.begin(), d.end(), (t * 2) - c[j]) - lower_bound(d.begin(), d.end(), t - c[j]);
            } else {
                num += n - (lower_bound(d.begin(), d.end(), (t * 2) - c[j]) - lower_bound(d.begin(), d.end(), (t * 3) - c[j]));
            }
        }
        ans += (num % 2) << i;
        cerr << ans << endl;
    }
    cout << ans;
}

