	for (uint_fast32_t i = 0; i < N; i++) cin.scan(a[i]);
	for (uint_fast32_t i = 0; i < N; i++) cin.scan(b[i]);

	uint_fast32_t ans = 0;
	for (uint_fast32_t i = 0; i + unrl <= N; i += unrl) {
		for (uint_fast32_t j = 0; j + block <= N; j += block) {
			for (uint_fast32_t k = j; k < block + j; k++) {

				ans ^= (a[i + 0] + b[k]) ^ (a[i + 1] + b[k]);
				ans ^= (a[i + 2] + b[k]) ^ (a[i + 3] + b[k]);
