void refrain(vector<int> v[2], int a[], int n, int m)
{
	int mask = (1 << m) - 1;
	v[0].clear();
	v[1].clear();
	for (int i = 1; i <= n; i++)
	{
		v[a[i] >> m & 1].push_back(a[i] & mask);
	}
	sort(v[0].begin(), v[0].end());
	sort(v[1].begin(), v[1].end());
}
LL solve(vector<int>& v1, vector<int>& v2, int maxv)
{
	int ptr = v2.size() - 1;
	LL sum = 0;
	for (int i = 0; i < v1.size(); i++)
	{
		while (ptr >= 0 && v2[ptr] + v1[i] >= maxv) ptr--;
		sum += ptr + 1;
	}
	return sum;
}
int main()
{
	//freopen("input.txt", "r", stdin);
	//freopen("output.txt", "w", stdout);
