	{
		scanf("%d", &a[i]);
	}
	for (int i = 1; i <= n; i++)
	{
		scanf("%d", &b[i]);
	}
	int ans = 0;
	for (int o = 28; o >= 0; o--)
	{
		refrain(v1, a, n, o);
		refrain(v2, b, n, o);
		for (int i = 0; i < 2; i++)
		{
			for (int j = 0; j < 2; j++)
			{
				LL low = solve(v1[i], v2[j], 1 << o);
				LL up = 1LL * v1[i].size() * v2[j].size() - low;
				int t = (low & (i + j)) ^ (up & (i + j + 1));
				t &= 1;
				ans ^= t << o;
			}
		}
	}
	cout << ans << endl;
	return 0;
}

