ll modpow(ll a, ll n, ll mod) {
  ll res = 1;
  while (n > 0) {
    if (n & 1) res = res * a % mod;
    a = a * a % mod;
    n >>= 1;
  }
  return res;
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int N;
  cin >> N;
  vector<ll> a(N), b(N);

  for(int i = 0; i < N; i++) cin >> a[i];
  for(int i = 0; i < N; i++) cin >> b[i];

  ll m = 1;

  ll ans = 0;

  for(int j = 0; j < 29; j++){

    vector<ll> c(N);
    for(int i = 0; i < N; i++){
      c[i] = b[i] % (2*m);
    }

    sort(c.begin(), c.end());

    ll t = 0;
    for(int i = 0; i < N; i++){

      ll minval = m - (a[i] % (2*m));
      ll maxval = 2*m - (a[i] % (2*m));

      if(minval >= 0){

        auto itr_min = lower_bound(c.begin(), c.end(), minval);
        auto itr_max = lower_bound(c.begin(), c.end(), maxval);

        t += itr_max - itr_min;

      }else{

        auto itr_min = lower_bound(c.begin(), c.end(), minval + 2*m);
        auto itr_max = lower_bound(c.begin(), c.end(), maxval);

        t += c.end() - itr_max;
        t += itr_min - c.begin();
      }

    }

    if(t % 2 == 1){
      ans += m;
    }

    m *= 2;
  }

  cout << ans << endl;

  return 0;
}

