long long binary_search(vector<long long> &n, long long x){
    long long ok = (long long)n.size();
    long long ng = - 1;
    while (abs(ok - ng) > 1){
        long long mid = (ok + ng) / 2;
        if (n[mid] >= x) ok = mid;
        else ng = mid;
    }
    return ng;
}

int main(){
    int n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<long long> b(n);
    for (int i = 0; i < n; i++) cin >> b[i];
    long long ans = 0;
    for (int i = 0; i < 28; i++){
        vector<long long> mod_a(n);
        vector<long long> mod_b(n);
        long long tmp = 0;
        for (int j = 0; j < n; j++){
            mod_a[j] = a[j] % (1<<(i+1));
            mod_b[j] = b[j] % (1<<(i+1));
        }
        sort(mod_b.begin(), mod_b.end());
        for (int j = 0; j < n; j++){
            tmp += binary_search(mod_b, 2*(1<<i) - mod_a[j]) - binary_search(mod_b, (1<<i) - mod_a[j]);
            tmp %= 2;
            tmp += binary_search(mod_b,  4*(1<<i) - mod_a[j]) - binary_search(mod_b, 3*(1<<i) - mod_a[j]);
            tmp %= 2;
        }
        ans += (1<<i) * (tmp % 2);
    }
    cout << ans << endl;
}

