int a[200000], b[200000];
int i, j, k;
constexpr int block = 16384;
signed main() {
	int n;
	scanf("%d", &n);
	int r = n & 3;
	for (i = 0; i < n; ++i)
		scanf("%d", &a[i]);
	for (i = 0; i < n; ++i)
		scanf("%d", &b[i]);
	__m128i temp = _mm_set1_epi32(0);
	__m128i val0;
	__m128i val1;
	for (i = 0; i < n; i += 4) {
		val0 = _mm_load_si128((__m128i*) &a[i]);
		for (j = 0; j + block - 1 < n; j += block) {
				for (k = j; k < j + block; ++k) {
					val1 = _mm_set1_epi32(b[k]);
					temp = _mm_xor_si128(_mm_add_epi32(val0, val1), temp);
				}
		}
		int u = n & ~(block - 1);
		for (j = u; j < n; ++j) {
				val1 = _mm_set1_epi32(b[j]);
				temp = _mm_xor_si128(_mm_add_epi32(val0, val1), temp);
		}
	}
	int re[4];
	_mm_store_si128((__m128i*)re, temp);
	int ans = re[0] ^ re[1] ^ re[2] ^ re[3];
	if (r & 1)
		for (i = 0; i < n; ++i)
			ans ^= b[i];
	printf("%d", ans);
	return 0;
}

