			//cout << "moto " << moto << endl;


			int upper = (1 << (k+1)) - moto;
			int lower = 0;
			if ( ! (moto & (1 << k)) ) {
				lower = (1 << k) - moto;
			}

			//cout << "finding [" << lower << ", " << upper << ")" << endl;
			int *lp = std::lower_bound(M, M+N, lower);
			int *up = std::lower_bound(M, M+N, upper);
			//cout << "found " << (up-lp) << endl;

			cnt += max(up-lp, 0L);

			if ( moto & (1 << k) ) {
				int lower2 = ((1 << k) | (1 << k+1)) - moto;
				//cout << "refindg [" << lower2 << "... " << endl;
				int *l2 = std::lower_bound(M, M+N, lower2);
				//cout << "found " << (M+N-l2) << endl;

				cnt += M+N-l2;
			}
		}

		//cout << k << " cnt " << cnt << endl;
		ret = (ret) | ( (cnt % 2L) << k);
	}

