    a.push_back(k);
  }
  for (int i = 0; i < n; i++){
    scanf("%d", &k);
    b.push_back(k);
  }
  int ans = 0;
  int t2 = 1;
  for (int bit = 0; bit < 29; bit++){
    t2 *= 2;
    vector<int> d;
    for (int j = 0; j < n; j++){
      d.push_back(b[j] % t2);
    }
    sort(d.begin(), d.end());
    int count = 0;
    for (int i = 0; i < n; i++){
      int c = a[i] % t2;
      if (t2 / 2 >= c) count += search(d, t2-c, n) - search(d, t2/2-c, n);
      else count += n - search(d, t2-c, n) + search(d, t2*3/2-c, n);
      count %= 2;
    }
    ans += (count % 2) * t2/2;
  }

  printf("%d\n", ans);

  return 0;
}

