typedef long long llint;

int n;
int a[210000], b[210000];
int bb[210000];

//二分探索
//・条件を満たす *最小* の値のindexをかえす。
//・求める値は区間 (left, right] に絶対に含まれる。
bool judge(long long x, int border) {
    if (x == -1) {
        return false;
    }
    if (x == n) {
        return true;
    }
    return border <= bb[x];
}

long long nibutan(long long left, long long right, int border) {
    while (right - left > 1) {
        long long mid = (left + right) / 2;
        if (judge(mid, border)) {
            right = mid;
        } else {
            left = mid;
        }
    }
    return right;
}

int solve() {
    int ans = 0;
    int t = 1;
    for (int i = 0; i <= 29; i++) {
        for (int j = 0; j < n; j++) {
            bb[j] = b[j] % (t * 2);
        }
        sort(bb, bb + n);

        int cnt = 0;
        for (int j = 0; j < n; j++) {
            int l, r;
            l = nibutan(-1, n, t - a[j]);
            r = nibutan(-1, n, t * 2 - a[j]);
            cnt += r - l;
            l = nibutan(-1, n, t * 3 - a[j]);
            r = nibutan(-1, n, t * 4 - a[j]);
            cnt += r - l;
        }

        if (cnt % 2 == 1) {
            ans += t;
        }

        t *= 2;
    }
    return ans;
}

