ll pow(ll x, ll y){
    if (y == 0) return 1;
    if (y % 2) {
        return x * pow(x, y - 1);
    } else {
        ll z = pow(x, y / 2);
        return z * z;
    }
}

ll lower(ll x, ll y){
    ll lb = -1, ub = n;
    while(lb + 1 < ub){
        ll mid = (lb + ub) / 2;
        if (bvec[y][mid] >= x) ub = mid;
        else lb = mid;
    }
    return ub;
}


