constexpr int MAX_N = 200000;
size_t n;
unsigned a[MAX_N], b[MAX_N];

int main() {
    // Input
    // reader(&n);
    scanf("%lu", &n);
    // for (size_t i = 0; i < n; ++i) reader(&a[i]);
    // for (size_t i = 0; i < n; ++i) reader(&b[i]);
    for (size_t i = 0; i < n; ++i) scanf("%u", &a[i]);
    for (size_t i = 0; i < n; ++i) scanf("%u", &b[i]);


    // Solve
    constexpr size_t block_a = 4, block_b = 8192;
    unsigned ans = 0;
    for (size_t i = 0; i + (block_a - 1) < n; i += block_a) {
        for (size_t j = 0; j + (block_b - 1) < n; j += block_b)
            for (size_t k = j; k < j + block_b; ++k) {
                ans ^= (a[i] + b[k]) ^ (a[i + 1] + b[k]);
                ans ^= (a[i + 2] + b[k]) ^ (a[i + 3] + b[k]);
            }

        for (size_t j = n & ~(block_b - 1); j < n; ++j) {
            ans ^= (a[i] + b[j]) ^ (a[i + 1] + b[j]);
            ans ^= (a[i + 2] + b[j]) ^ (a[i + 3] + b[j]);
        }
    }

    // rest of iterations
    for (size_t i = n & ~(block_a - 1); i < n; ++i) {
        for (size_t j = 0; j + (block_b - 1) < n; j += block_b)
            for (size_t k = j; k < j + block_b; ++k)
                ans ^= a[i] + b[k];

        for (size_t j = n & ~(block_b - 1); j < n; ++j)
            ans ^= a[i] + b[j];
    }

    // Output
    printf("%u\n", ans);
    // writer(ans, '\n');

    return 0;
}

#include"bits/stdc++.h"
using namespace std;

int main() {
    long long N;
    cin >> N;
    vector<long long> a(N), b(N);
    for (int i = 0; i < N; i++) {
        cin >> a[i];
    }
    for (int i = 0; i < N; i++) {
        cin >> b[i];
    }

    long long ans = 0;
    for (int i = 0; i < 28; i++) {
        //i桁目に1が立つ数を数える
        long long num_1 = 0;

        //i桁より大きい部分は影響しないのでマスクする
        vector<long long> aa = a, bb = b;
        for (int j = 0; j < N; j++) {
            aa[j] &= (1 << (i + 1)) - 1;
            bb[j] &= (1 << (i + 1)) - 1;
        }

        //aa[j] + bb[k] が 2^i ~ 2^(i + 1) - 1, 2^(i + 1) + (2^i ~ 2^(i + 1) - 1)の範囲にあれば1がi桁目に立つ
        //つまりaa[j]を決めるとbb[k]が取れる範囲が定まる
        sort(bb.begin(), bb.end());

        for (int j = 0; j < N; j++) {
            auto left1 = lower_bound(bb.begin(), bb.end(), (1 << i) - aa[j]);
            auto right1 = upper_bound(bb.begin(), bb.end(), (1 << (i + 1)) - 1 - aa[j]);

            auto left2 = lower_bound(bb.begin(), bb.end(), (3 << i) - aa[j]);
            auto right2 = upper_bound(bb.begin(), bb.end(), (3 << (i + 1)) - 1 - aa[j]);

            num_1 += right1 - left1;
            num_1 += right2 - left2;
        }

        ans |= ((num_1 % 2) << i);
    }

    cout << ans << endl;
}

