typedef long long ll;

using namespace std;

int main() {
    int n;
    ll ans = 0;
    cin >> n;
    vector<ll> a(n), b(n);
    for (int i = 0; i < n; ++i) cin >> a.at(i);
    for (int i = 0; i < n; ++i) cin >> b.at(i);
    for (int i = 0; i < 30; ++i) {
        ll digit = 1ll << i;
        vector<ll> m(b);
        for (vector<ll>::size_type j = 0; j < m.size(); ++j) m.at(j) %= digit * 2;
        sort(m.begin(), m.end());
        int cnt = 0;
        for (vector<ll>::size_type j = 0; j < m.size(); ++j) {
            ll da = a.at(j) % (digit * 2);
            cnt += bound_range(m, digit - da, digit * 2 - da) + bound_range(m, digit * 3 - da, digit * 4 - da);
        }
        if (cnt % 2) ans += digit;
    }

    cout << ans << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int p0,p1,q0,q1,v,pos;
long long ans=0;
int a[200000],b[200000],arr[28][200000],t[200000];
int main()
{
	int i,j,n;
	scanf("%d",&n);
	for(i=0;i<n;i++)
		scanf("%d",&a[i]);
	for(i=0;i<n;i++)
		scanf("%d",&b[i]);	
	for(i=0;i<28;i++)
	{
		p0=p1=q0=q1=0;
		for(j=0;j<n;j++)
		{
			((a[j]>>i)&0x01)?p0++:p1++;
		}
		for(j=0;j<n;j++)
		{
			((b[j]>>i)&0x01)?q0++:q1++;	
		}
		ans^=((p0*q1)%2+(p1*q0)%2)%2;
	}
	//生成第一排arr[28][n]的
	for(i=0;i<28;i++)
	{
		for(j=0;j<n;j++)
		{
			if(i==0)
				arr[i][j]=0x01&a[j];
			else
				arr[i][j]=arr[i-1][j]|((1<<i)&a[j]);
		}
	} 
	for(i=0;i<28;i++)
		sort(arr[i],arr[i]+n);
	for(i=0;i<28;i++)
	{
		for(j=0;j<n;j++)
		{
			t[j]|=(1<<i)&b[j];
			v=(1<<(i+1))-t[j];	
			pos=lower_bound(arr[i],arr[i]+n,v)-arr[i];
			ans^=((n-pos)/2%2)<<(i+1);
		}
	}	
	printf("%lld",ans);	 
	return 0;
}

