bool check (ll p)
{
    vector < ll > amod(N);
    vector < ll > bmod(N);
    REP(i,N) {
        amod[i] = a[i] % (1LL << (p + 1));
        bmod[i] = b[i] % (1LL << (p + 1));
    }
    sort(amod.begin(), amod.end());
    sort(bmod.begin(), bmod.end());

    ll sum = 0;
    REP(i,N) {
        sum += ( lower_bound(bmod.begin(), bmod.end(), (1LL << (p + 1)) - amod[i])
               - lower_bound(bmod.begin(), bmod.end(), (1LL << (p)) - amod[i]));
        sum += ( bmod.end() - lower_bound(bmod.begin(), bmod.end(), (1LL << (p)) + (1LL << (p + 1)) - amod[i]));
    }

    if (sum % 2) return true;
    return false;
}


