int main() {
    cin >> N;
    for (auto i = 0; i < N; i++) cin >> a[i];
    for (auto i = 0; i < N; i++) cin >> b[i];

    ll ret = 0;
    ll c = 1 << 29;
    for (auto i = 29; i >= 0; i--) {
        for (auto j = 0; j < N; j++) {
            a[j] &= ~(1 << (i + 1));
            b[j] &= ~(1 << (i + 1));
        }
        sort(b, b + N);

        ll now = 0;
        for (auto j = 0; j < N; j++) {
            now += lower_bound(b, b + N, 2 * c - a[j]) - lower_bound(b, b + N, 1 * c - a[j]);
            now += lower_bound(b, b + N, 4 * c - a[j]) - lower_bound(b, b + N, 3 * c - a[j]);
        }
        ret *= 2;
        ret += now % 2;
        c >>= 1;
    }
    cout << ret;   
}

