typedef long long ll;
typedef vector<int> VI;
typedef vector<ll> VL;

int search_b_cnt(const ll min, const ll max, const VL& b) {
    if(b.back() < min) return 0;
    if(b.front() >= max) return 0;
    // min探索
    int left_index = -1;
    int right_index = b.size();
    while(right_index - left_index > 1) {
        int mid = (right_index + left_index) / 2;
        if(b[mid] < min) left_index = mid;
        else right_index = mid;
    }
    int b_min_index = right_index;
    // max探索
    left_index = -1;
    right_index = b.size();
    while(right_index - left_index > 1) {
        int mid = (right_index + left_index) / 2;
        if(b[mid] < max) left_index = mid;
        else right_index = mid;
    }
    int b_max_index = left_index;
    return b_max_index - b_min_index + 1;
}

