    vector<int> have;
    for (auto &x : a) {
        cin >> x;
        int msk = 0;
        for (int l = 0; l < LOGN; ++l) {
            msk |= 1 << l;
            have.push_back(x & msk);
        }
    }
    for (auto &x : b) {
        cin >> x;
        int msk = 0;
        for (int l = 0; l < LOGN; ++l) {
            msk |= 1 << l;
            have.push_back(x & msk);
        }
    }
    sort(have.begin(), have.end());
    have.erase(unique(have.begin(), have.end()), have.end());
    auto get = [&](int x) {
        return lower_bound(have.begin(), have.end(), x) - have.begin();
    };
    int ans = 0;
    Fenv f(have.size());
    int lsh = 1;
    int msk = 1, ost = 0;
    for (int l = 0; l < LOGN; ++l, lsh <<= 1) {
        msk |= lsh;
        f.clear();
        for (int i = 0; i < n; ++i) {
            f.inc(get(b[i] & msk), 1);
        }
        int res = 0;
        for (int i = 0; i < n; ++i) {
