//	for (int i = 0; i < n; i++)
//		cout << b_bit[i] << "  /  ";
//	cout << endl;
	for (int i = 0; i < n; i++) {
		int dif = t2 - a_bit[i],
			dif2 = t - a_bit[i];
		auto k = lower_bound(b_bit, b_bit + n, dif) - b_bit,
			 k2 = lower_bound(b_bit, b_bit + n, dif2) - b_bit;
