int main() {
  using niu::fin;
  using niu::fout;
  i64 n;
  fin >> n;
  vector<i64> a(n), b(n);
  rep(i,0,n) fin >> a[i];
  rep(i,0,n) fin >> b[i];

  i64 ans = 0;

  if(n & 1) {
    for(auto aa: a) ans ^= aa;
    for(auto aa: b) ans ^= aa;
  }

  vector<i64> c(n);

  for(int i = 0; i < 28; i++) {
    i64 bit = 1 << (i + 1);
    rep(j,0,n) c[j] = b[j] & (bit - 1);
    wavelet_matrix wm(c, i + 1);
    for(auto aa: a) {
      if(wm.rangefreq(0, n, (~aa&(bit - 1)), (1 << bit) - 1) & 1) {
        ans ^= bit;
      }
    }
  }
  fout << ans << '\n';
}

