ll ika_count(V &v, ll x){
    if(v[0] > x)return 0;
    if(v[v.size() - 1] <= x)return v.size();
    ll ok = 0, ng = v.size();
    while(ok + 1 < ng){
        ll mid = (ok + ng) / 2;
        if(v[mid] <= x)ok = mid;
        else ng = mid;
    }
    return ok + 1;
}
ll ijo_count(V &v, ll x){
    if(v[v.size() - 1] < x)return 0;
    if(v[0] >= x)return v.size();
    ll ng = 0, ok = v.size() -1;
    while(ng + 1 < ok){
        ll mid = (ng + ok) / 2;
        if(v[mid] >= x)ok = mid;
        else ng = mid;
    }
    return v.size() - ng - 1;
}
