    for (int i = 0; i <= 28; ++i)
    {
        int T = (1 << i);
#ifdef DEBUG
    cout << "=== i = " << i << ", T = " << T << endl;
#endif

        for (int i = 0; i < N; ++i)
            ra[i] = as[i] % (2*T);

