        cout << a << ' ';
    cout << endl;
    cout << "    rb = ";
    for (auto b : rb)
        cout << b << ' ';
    cout << endl;
#endif

        // ai + bj tem o i-ésimo bit ligado se
        //
        //  1. T <= ai + bj < 2T
        //  2. 3T <= ai + bj < 4T
        ll count = 0;

        for (auto a : ra)
        {
            auto it = lower_bound(rb.begin(), rb.end(), T - a);
            auto jt = lower_bound(rb.begin(), rb.end(), 2*T - a);

            if (jt - it > 0)
                count += (jt - it);
#ifdef DEBUG
    cout << "-- a = " << a << ", size for [T, 2T) = " << jt - it << ", count = " << count << endl;
#endif

            it = lower_bound(rb.begin(), rb.end(), 3*T - a);
            jt = lower_bound(rb.begin(), rb.end(), 4*T - a);

            if (jt - it > 0)
                count += (jt - it);

#ifdef DEBUG
