      } else {
        int lb = 0;
        int ub = lower_bound(ALL(b), (1 << (j + 1)) - a) - b.begin();
        cnt += ub - lb;
        lb = lower_bound(ALL(b), (1 << (j + 1)) + (1 << j) - a) - b.begin();
        ub = n;
        cnt += ub - lb;
      }
    }
    if (cnt & 1) ans += 1 << j;
  }
  cout << ans << '\n';
  return 0;
}

