int calc(int shift)
{
	// 2T
	int n = (1 << shift);
	//cout << n << endl;
	vector<int> aa(N), bb(N);
	for(int i=0; i<N; i++){
		aa[i] = a[i] % n;
		bb[i] = b[i] % n;
	}

	sort(bb.begin(), bb.end());
	//cout << "aa : ";
	//for(int i=0; i<N; i++)
	//	cout << aa[i] << " ";
	//cout << endl;
	//cout << "bb : ";
	//for(int i=0; i<N; i++)
	//	cout << bb[i] << " ";
	//cout << endl;

	long long cnt = 0;
	for(int i=0; i<N; i++){
		// [T, 2T)
		auto src = lower_bound(bb.begin(), bb.end(), n/2-aa[i]);
		auto dst = lower_bound(bb.begin(), bb.end(), n-aa[i]);
		//cout << aa[i] << " : [" << n/2 <<", " << n <<") : " << n/2-aa[i] << " " << n-aa[i] << " : " << dst - src << endl;;
		cnt += dst - src;

		// [3T, 4T)
		src = lower_bound(bb.begin(), bb.end(), n+n/2-aa[i]);
		dst = lower_bound(bb.begin(), bb.end(), 2*n-aa[i]);
		///cout << aa[i] << " : [" << n+n/2 <<", " << 2*n <<") : " << n+n/2-aa[i] << " " << 2*n-aa[i] << " : " << dst - src << endl;;
		cnt += dst - src;
	}

	return cnt % 2;
}

