    int A[202020], B[202020];
    for(int i=0;i<N;++i) cin >> A[i];
    for(int i=0;i<N;++i) cin >> B[i];

    int ans = 0;
    for(int i = 29; i >= 0; --i) {
        // check whether i th bit is 1
        int low  = (1<<i);
        int high = (1<<i+1);
        for(int j=0; j < N; ++j) A[j] %= high, B[j] %= high;
        sort(B, B + N);

        int cnt = 0;
        // 2^i <= A[a] + B[x] < 2^(i+1)
        // これを満たすB[x]の数を数える。
        // ソートした後に二分探索*2で上端　－　下端すればOK？
        for(int a = 0; a < N; ++a) {
            if(low - A[a] >= 0) cnt += lower_bound(B, B+N, high - A[a]) - lower_bound(B, B+N, low - A[a]);
            else {
                cnt += lower_bound(B, B+N, high - A[a]) - lower_bound(B, B+N, 0);
                cnt += lower_bound(B, B+N, high) - lower_bound(B, B+N, high + low - A[a]);
            }
        }
        if(cnt&1) ans |= (1<<i);
    }

    cout << ans << '\n';
    return 0;
}

