        }

        // ソートは b だけ
        sort(tb.begin(), tb.end());

        ll a = 0;
        ll suma = 0;
        for (ll i = 0; i < N; i++)
        {
            ll t1 = 1 << (x - 1);
            ll t2 = 2 * t1;

            ll l = t1 - ta[i];
            ll h = t2 - ta[i];

            // [T - ai, 2T - ai) 区間 1
            ll l1 = lower_bound(tb.begin(), tb.end(), l) - tb.begin();
            ll u1 = lower_bound(tb.begin(), tb.end(), h) - tb.begin() - 1;

            ll t3 = 3 * t1;
            ll t4 = 4 * t1;

            l = t3 - ta[i];
            h = t4 - ta[i];

            // [3T - ai, 4T - ai) 区間 2
            ll l2 = lower_bound(tb.begin(), tb.end(), l) - tb.begin();
            ll u2 = lower_bound(tb.begin(), tb.end(), h) - tb.begin() - 1;

            a = 0;
            if (l1 == N)
            {
                // 区間 1 無し
                if (l2 == N)
                {
                    // 区間 2 無し
                    a = 0;
                }
                else
                {
                    // 区間 2 有り
                    a = u2 - l2 + 1;
                }
            }
            else if (l2 == N)
            {
                // 区間 2 無し
                a = u1 - l1 + 1;
            }
            else if (l2 <= u1 && l1 <= u2)
            {
                // 区間が交差する
                a = max(u1, u2) -min(l1, l2) + 1;
            }
            else
            {
                // 区間が交差しない
                a = u1 - l1 + u2 -l2 + 2;
            }
            suma += a;
        }

        if (suma % 2 == 0) suma = 0;
        else suma = 1;

        ans += suma * (1 << (x - 1));

        x++;
        d <<= 1;
    }

    printf("%" p64 "\n", ans);
    return 0;
}

