typedef long long LL;
typedef vector<int> VI;
typedef pair<int, int> PII;

const double PI = acos(-1.0);
const int INF = 1000 * 1000 * 1000 + 7;
const LL LINF = INF * (LL) INF;

const int MAX = 200200;

int A[MAX];
int B[MAX];

VI X[2];
VI Y[2];

void add(int* a, VI* x, int n, int st)
{
	FOR (i, 0, n)
	{
		int v = a[i];
		int m = v % st;
		int d = v / st;

		x[d & 1].PB(m);
	}
}

LL get_less(VI& a, VI& b, int val)
{
	int ind = SZ(b) - 1;

	LL res = 0;

	FOR (i, 0, SZ(a))
	{
		while(ind >= 0 && a[i] + b[ind] >= val) ind--;

		res += ind + 1;
	}

	return res;
}

LL get_more(VI& a, VI& b, int val)
{
	LL res = get_less(a, b, val);
	res = SZ(a) * (LL)SZ(b) - res;
	return res;
}

