		add(A, X, n, st);
		add(B, Y, n, st);

		sort(ALL(X[0]));
		sort(ALL(X[1]));
		sort(ALL(Y[0]));
		sort(ALL(Y[1]));

		LL cur = 0;

		cur += get_more(X[0], Y[0], st);
		cur += get_less(X[0], Y[1], st);
		cur += get_less(X[1], Y[0], st);
		cur += get_more(X[1], Y[1], st);

		cur %= 2;
		res += cur * st;
		st *= 2;
	}

	cout<<res<<endl;

}

