			ll modA = As[i] % (1LL << (curr_bit + 1));
			bit_count += lower_bound(modBs.begin(), modBs.end(), (1LL << (curr_bit + 1)) - modA)
				- lower_bound(modBs.begin(), modBs.end(), (1LL << (curr_bit)) - modA);
			bit_count += lower_bound(modBs.begin(), modBs.end(), (1LL << (curr_bit + 2)) - modA)
				- lower_bound(modBs.begin(), modBs.end(), (1LL << (curr_bit)) * 3 - modA);
		}
		if (bit_count % 2 != 0)
		{
			res += (1LL << curr_bit);
		}
	}

	cout << res;

	return 0;
}

