                    upper_l = mid;
                } else {
                    upper_r = mid;
                }
            }
            bool flag = false;
            REP(j,N) {
                if (b[j] >= (1LL << p) - a[j] && b[j] < (1LL << (p + 1)) - a[j]) {
                    flag = true;
                }
            }
            if (flag) {
                sum += (upper_l - lower_r + 1LL);
            }

            // 2^p + 2^(p+1) ~ 2^(p+2)
            lower_l = -1, lower_r = N - 1;
            while (lower_r - lower_l > 1) {
                ll mid = (lower_l + lower_r) / 2;
                if (b[i] >= (1LL << p) + (1LL << (p + 1)) - a[i]) {
