                if (b[j] >= (1LL << p) + (1LL << (p + 1)) - a[j] && b[j] < (1LL << (p + 2)) - a[j]) {
                    flag = true;
                }
            }
            if (flag) {
                sum += (upper_l - lower_r + 1LL);
            }
        }
        ans |= ((sum % 2) << p);
    }

    cout << ans << endl;

