		int A; SCD(A);
		a.PB(A);
	}
	REP(i,N){
		int B; SCD(B);
		b.PB(B);
	}

	sort(b.begin(),b.end());

	for (int p = 1;p <= 268435456;p = 2*p){
		vector<int> pa,pb;
		REP(i,N){
			pa.PB(a[i] % (2*p));
			pb.PB(b[i] % (2*p));
		}

		sort(pb.begin(),pb.end());
		int count = 0;

		REP(i,N){
			auto it1 = lower_bound(pb.begin(),pb.end(),2*p-pa[i]);
			auto it2 = lower_bound(pb.begin(),pb.end(),p-pa[i]);
			auto it3 = lower_bound(pb.begin(),pb.end(),4*p-pa[i]);
			auto it4 = lower_bound(pb.begin(),pb.end(),3*p-pa[i]);

			count += (int)((it1 - pb.begin()) - (int)(it2 - pb.begin()));
			count += (int)((it3 - pb.begin()) - (int)(it4 - pb.begin()));
		}
		//printf("count = %d\n",count);
		if (count % 2 == 1) ans += p;
	}

	PRINTD(ans);
	return 0;
}

