        cin >> B[i];
    }
    REP(i, 31)
    {
        ll m = 0;
        REP(j, i)
        {
            m |= (1 << j);
        }
        vector<ll> c;
        REP(j, N)
        {
            c.push_back(B[j] & m);
        }
        sort(c.begin(), c.end());

        ll u = pow(2, i);
        ll t = pow(2, (i + 1));
        REP(j, N)
        {
            ll a = A[j] & m;
            {
                int ui = getUnder(c, u - a);
                int ti = getTop(c, t - a);
                if (ui <= ti)
                {
                    D[i] += (ti - ui + 1);
                }
            }
            {
                int ui = getUnder(c, u + t - a);
                int ti = getTop(c, 2 * t - a);
                if (ui <= ti)
                {
                    D[i] += (ti - ui + 1);
                }
            }
        }
    }

    ll ans = 0;
    REP(i, 31)
    {
        ans |= ((D[i] % 2) << i);
    }
    cout << ans << endl;
    return 0;
}

