const int MAXN = (int) 5e5 + 7;

struct Fenv {
    int n;
    int t[MAXN];

    Fenv(int n) : n(n) { }

    int sum(int r) {
        int res = 0;
        for (; r >= 0; r = (r & (r + 1)) - 1) res += t[r];
        return res;
    }

    void inc(int i, int d) {
        for (; i < n; i = (i | (i + 1))) t[i] += d;
    }

    int sum(int l, int r) {
        return sum(r - 1) - sum(l - 1);
    }

    void clear() {
        fill_n(t, n, 0);
    }
};

