  int sz = log2(*max_element(a.begin(), a.end())+*max_element(b.begin(), b.end()));
  int ans = 0;
  rep(i, sz+1) {
    int mod = pow(2, i+1);
    auto v = b;
    rep(j, n) v[j] %= mod;
    sort(v.begin(), v.end());
    int cnt = 0;
    rep(j, n) {
      int A = a[j]%mod, T = mod/2;
      cnt += distance(lower_bound(v.begin(), v.end(), T-A), lower_bound(v.begin(), v.end(), T*2-A));
      cnt += distance(lower_bound(v.begin(), v.end(), T*3-A), lower_bound(v.begin(), v.end(), T*4-A));
    }
    if (cnt%2)
      ans |= 1<<i;
  }
  cout << ans << endl;
  return 0;
}

