int64_t a[29][200'000], b[29][200'000];

int main()
{
    int n;
    cin >> n;

    rep(i, n)
    {
        int aa;
        cin >> aa;

        rep(j, 29)
        {
            int mask = 1 << (j + 1);

            a[j][i] = aa % mask;
        }
    }

    rep(i, n)
    {
        int bb;
        cin >> bb;
        rep(j, 29)
        {
            int mask = 1 << (j + 1);

            b[j][i] = bb % mask;
        }
    }

    int64_t result = 0;
    rep(i, 29)
    {
        sort(a[i], a[i] + n);
        sort(b[i], b[i] + n);

        int64_t lb1 = 1 << i;
        int64_t ub1 = lb1 << 1;
        int64_t lb2 = (lb1 << 1) + lb1;
        int64_t ub2 = ub1 << 1;

        int64_t ones = 0;
        rep(j, n)
        {
            ones += lower_bound(b[i], b[i] + n, ub1 - a[i][j]) - lower_bound(b[i], b[i] + n, lb1 - a[i][j]);
            ones += lower_bound(b[i], b[i] + n, ub2 - a[i][j]) - lower_bound(b[i], b[i] + n, lb2 - a[i][j]);
        }
        ones %= 2;
        int flag = ones << i;

        result |= flag;
    }
