int main()
{
    int N;
    cin >> N;

    vector<int> A(N);

    REP (i, N) cin >> A[i];

    vector<int> B(N);

    REP (i, N) cin >> B[i];

    int amax = *ALL (max_element, A);

    int bmax = *ALL (max_element, B);

    int abmax = amax + bmax;

    int t = 1 << 1;

    int ans = 0;

    vector<int> digit[2];

    while ((t >> 1) <= abmax)
    {
        digit[0].clear();
        digit[1].clear();

        int log2t = (int)log2(t >> 1);

        // 自分のビットが 0 か 1 かで振り分け
        REP (ix, N) digit[(A[ix] >> log2t) & 1].push_back(A[ix]);

        int tix = 0;

        // 自分のビット以下は昇順になる
        REP (ix, (signed)digit[0].size()) A[tix++] = digit[0][ix];
        REP (ix, (signed)digit[1].size()) A[tix++] = digit[1][ix];

        digit[0].clear();
        digit[1].clear();

        REP (ix, N) digit[(B[ix] >> log2t) & 1].push_back(B[ix]);

        tix = 0;

        REP (ix, (signed)digit[0].size()) B[tix++] = digit[0][ix];
        REP (ix, (signed)digit[1].size()) B[tix++] = digit[1][ix];

        int mask = t - 1;

        ll cntsum = 0;

        int K1 = t >> 1;

        int K2 = t;

        int K3 = K1 + K2;

        // 0-indexed
        int N1 = N - 1;

        int x1 = 0;
        int x2 = 0;
        int x3 = 0;

        // A 降順 B 昇順で見ていく
        // A が小さくなるたびに B は前よりも大きくなる

        // 0-indexed
        for (int i = N1; 0 <= i; i--)
        {
            while ((x1 <= N1) && (((A[i] & mask) + (B[x1] & mask)) < K1)) x1++;
            while ((x2 <= N1) && (((A[i] & mask) + (B[x2] & mask)) < K2)) x2++;
            while ((x3 <= N1) && (((A[i] & mask) + (B[x3] & mask)) < K3)) x3++;

            // 区間1 と 区間 2 を足す
            // 区間 1 [K1, K2)  … x2 - x1
            // 区間 2 [K3, K4) … N - x3;
            cntsum += N - x1 + x2 - x3;
        }

        // 排他的論理和
        if (cntsum % 2 == 1) ans += K1;

        t <<= 1;
    }

    cout << ans << endl;
    return 0;
}

