uint32_t mask;

int cmp(const void* x, const void* y) {
	uint32_t a = *(const uint32_t*)x & mask, b = *(const uint32_t*)y & mask;
	return a < b ? -1 : a > b;
}

int32_t N;
uint32_t a[271828], b[271828];

int32_t count_ge(uint32_t target) {
	int32_t less = 0, ge = N - 1;
	if ((b[N - 1] & mask) < target) return 0;
	if ((b[0] & mask) >= target) return N;
	while (less + 1 < ge) {
		int32_t mid = less + (ge - less) / 2;
		if ((b[mid] & mask) >= target) ge = mid; else less = mid;
	}
	return N - ge;
}

int main(void) {
