		int32_t j;
		int64_t count = 0;
		for (j = 0; j < N; j++) {
			countEach[(b[j] >> i) & 1]++;
		}
		mask = (UINT32_C(1) << i) - 1;
		qsort(b, N, sizeof(*b), cmp);
		for (j = 0; j < N; j++) {
			count += countEach[1 - ((a[j] >> i) & 1)] + count_ge((mask + 1) - (a[j] & mask));
		}
		if (count & 1) answer |= UINT32_C(1) << i;
	}
	printf("%" PRIu32 "\n", answer);
	return 0;
}

