#define FOR(to) for (int i = 0; i < to; i++)

void quick(long a[], int left, int right)
{
    int i, j;
    long s, t;

    if (left < right) {
        s = a[left];
        i = left; j = right + 1;

        while (1) {
            while (a[++i] < s)
                ;
            while (a[--j] > s)
                ;
            if (i >= j) break;
            t = a[i]; a[i] = a[j]; a[j] = t;
        }
        a[left] = a[j]; a[j] = s;
        quick(a, left, j - 1); quick(a, j + 1, right);
    }
}

int lower_bound(long val, long list[], int N)
{
    int low = 0;
    int upper = N - 1;
    int mid;
    if (list[N - 1] < val) return N;
    while (upper - low > 1) {
        mid = (low + upper) / 2;
        if (list[mid] < val) low = mid;
        else upper = mid;
    }
    if (list[low] < val) return upper;
    else return low;
}

