void quick(long a[], int left, int right)
{
    int i, j, s, t;

    if (left < right) {
        s = a[left];
        i = left; j = right + 1;

        while (1) {
            while (a[++i] < s)
                ;
            while (a[--j] > s)
                ;
            if (i >= j) break;
            t = a[i]; a[i] = a[j]; a[j] = t;
        }
        a[left] = a[j]; a[j] = s;
        quick(a, left, j - 1); quick(a, j + 1, right);
    }
}

int lower_bound(long val, long list[], int N)
{
    int low = 0;
    int upper = N - 1;
    if (list[N - 1] < val) return N;
    while (upper - low > 1) {
        int mid = (low + upper) / 2;
        if (list[mid] < val) low = mid;
        else upper = mid;
    }
    if (list[low] < val) return upper;
    else return low;
}

void shell(long a[], int left, int right)
{
	int i, j, gap, t, len;

	// a[]より小さい範囲で最大のｇａｐを決める
    len = right - left + 1;
	for (gap = 1; gap<len / 3; gap = 3 * gap + 1)
		;

	while (gap>0) {
		for (i = gap; i<len; i++) {
			for (j = i - gap; j >= 0; j = j - gap) {
                // printf("i:%d j:%d g:%d  ", i, j, gap);
                // for (k = 0; k < len; k++) printf("%d ", a[k]);
                // putchar('\n');
				if (a[j]>a[j + gap]) {
					t = a[j]; a[j] = a[j + gap]; a[j + gap] = t;
				}
				else
					break;
			}
		}
		gap = gap / 3;             // ギャップを１／３にする
	}
}

