	int j, k, bit[31] = {1}, lower[2][31][200002], ans = 0, tmp;
	for (i = 1; i < 31; i++) bit[i] = bit[i-1] << 1;
	for (i = 1; i <= N; i++) {
		for (j = 0; j < 30; j++) {
			if ((a[i] | bit[j]) == a[i]) ans ^= bit[j] * (N % 2);
