#include <stdlib.h>

int asc(const void *a, const void *b) {
  return *(int *)a - *(int *)b;
}

int bitleft(int *p, int x, int len){
  if (p[0] >= x)
    return 0;
  int l = 0;
  int r = len;
  while (r - l > 1){
    int mid = (l+r)/2;
    if (p[mid] < x)
      l = mid;
    else
      r = mid;
  }
  return r;
}

int main(){
  int n;
  int a[200002];
  int b[200002];
  int ans = 0;
  scanf("%d", &n);
  for(int i = 0; i < n; i++){
    scanf("%d", &a[i]);
  }
  for(int i = 0; i < n; i++){
    scanf("%d", &b[i]);
  }
  for(int k = 0; k < 29; k++){
    int ar[200002];
    int br[200002];
    for(int i = 0; i < n; i++){
      ar[i] = a[i] & ((1 << (k+1)) - 1);
      br[i] = b[i] & ((1 << (k+1)) - 1);
    }
    qsort(br, n, sizeof(int), asc);
    int one = 0;
    for(int i = 0; i < n; i++){
      int l[4];
      for(int j = 1; j < 5; j++){
        l[j-1] = bitleft(br, (j << k) - ar[i], n);
      }
      one += l[3] + l[1] - l[2] - l[0];
    }
    ans += (one & 1) << k;
  }
  printf("%d\n", ans);
  return 0;
}

