    var sum=0
    for(k in 0..28){//2^28の位まで
        val a=IntArray(n,{i: Int -> aa[i]%(1 shl k+1)  })
        val b=IntArray(n,{i: Int -> bb[i]%(1 shl k+1)  })
        b.sort()
