        val kk = (1 shl k)
        for (i in 0 until n){
            var s1 = b.binarySearch(kk-a[i])
            if(s1<0){
                s1=-s1-1
            }else{
                while(s1>0&&b[s1-1]==kk-a[i])s1-=1
            }
            var s2 = b.binarySearch(2*kk-a[i])
            if(s2<0){
                s2=-s2-1
            }else{
                while(s2>0&&b[s2-1]==2*kk-a[i])s2-=1
            }
            count+=s2-s1
            s1 = b.binarySearch(3*kk-a[i])
            if(s1<0){
                s1=-s1-1
            }else{
                while(s1>0&&b[s1-1]==3*kk-a[i])s1-=1
            }
            s2 = b.binarySearch(4*kk-a[i])
            if(s2<0){
                s2=-s2-1
            }else{
                while(s2>0&&b[s2-1]==4*kk-a[i])s2-=1
            }
            count+=s2-s1
        }

        if(count%2==1){
            sum+=kk
        }
    }
