class Program {
    fun solve() {
        val sc = MyScanner()
        val n = sc.nextInt()
        val a = sc.intList()
        val b = sc.intList()

        var ans = 0
        for (i in 0..28) {
            // i桁が1になるか0になるか
            // 1になるペアの個数
            val p = 1 shl i
            val tB = b.map { it % (2 * p) }.sorted()
            var cnt = 0
            a.forEach {
                val m = it % (2 * p)
                // 足して 3p以上になる
                var ok = n
                var ng = -1
                while (ok - ng > 1) {
                    val mid = (ok + ng) / 2
                    if (m + tB[mid] >= 3 * p) ok = mid
                    else ng = mid
                }
                cnt += n - ok

                // 足して 1p以上 2p未満になるペア
                ok = n
                ng = -1
                while (ok - ng > 1) {
                    val mid = (ok + ng) / 2
                    if (m + tB[mid] >= 2 * p) ok = mid
                    else ng = mid
                }
                cnt -= n - ok

                ok = n
                ng = -1
                while (ok - ng > 1) {
                    val mid = (ok + ng) / 2
                    if (m + tB[mid] >= p) ok = mid
                    else ng = mid
                }
                cnt += n - ok
            }

            if (cnt % 2 == 1) ans = ans or (1 shl i)
        }

        println(ans)
    }
}

