fun LowerBound(arr: IntArray, v: Int): Int {
    var left = 0
    var right = arr.size - 1
    while (left <= right) {
        val center = (left + right) ushr 1
        if (v > arr[center]) left = center + 1
        else right = center - 1
    }
    return left
}

