            while (r3 < n && (ai + b[r3] < 3 * powk)) r3 += 1
            count += r2 - r1 + n - r3
        }
        /* end */

        for (index in 0 until n) {
            a[index] %= powk
            b[index] %= powk
        }
        a.sort()
        b.sort()

        ans += (count % 2).toInt().shl(k)
    }
    println(ans)
}

fun Array<Int>.lowerbound(key: Int): Int {
    return this.binarySearch(key, Comparator { o1: Int, o2: Int -> if (o1 >= o2) 1 else -1 }).inv()
}

