import java.util.Arrays;

public class Main {
  private static void solve() {
    int n = ni();
    int[] a = na(n);
    int[] b = na(n);

    int ret = 0;
    for (int k = 0; k < 30; k ++) {
      int[] na = Arrays.copyOf(a, n);
      int[] nb = Arrays.copyOf(b, n);

      for (int i = 0; i < n; i ++) {
        na[i] &= (1 << (k + 1)) - 1;
        nb[i] &= (1 << (k + 1)) - 1;
      }
      Arrays.sort(na);
      Arrays.sort(nb);

      int now = 0;
      for (int i = 0; i < n; i ++) {

        int v1 = lowerBound(nb, (1<<k) - na[i]);
        int v2 = lowerBound(nb, (1<<(k + 1)) - na[i]);
        now += v2 - v1;
        if (k >= 1) {
          int v3 = lowerBound(nb, (3<<k) - na[i]);
          now += n - v3;
        }
        now %= 2;
      }
      if (now % 2 == 1) {
        ret |= 1 << k;
      }
    }
    System.out.println(ret);
  }

  public static int lowerBound(int[] a, int v)
  {
      int low = -1, high = a.length;
      while(high-low > 1){
          int h = high+low>>>1;
          if(a[h] >= v){
              high = h;
          }else{
              low = h;
          }
      }
      return high;
  }


