					b[i] %= t;
				}

				Arrays.sort(b);

				for (int j = 0; j < n; j++) {
					long T = 1 << k;
					count += lowerBound(b, 2*T - a[j]) - lowerBound(b, 1*T - a[j]);
					count += lowerBound(b, 4*T - a[j]) - lowerBound(b, 3*T - a[j]);
				}

				if (count % 2 == 1) {
					ans |= 1 << k;
				}

			}
			out.println(ans);

		}
	}
	public static int lowerBound(long[] a, long obj) {
		int l = 0, r = a.length - 1;
		while (r - l >= 0) {
			int c = (l + r) / 2;
			if (obj <= a[c]) {
				r = c - 1;
			} else {
				l = c + 1;
			}
		}
		return l;
	}

