import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Main {
    public static void main(String args[]) {
        FastReader sc = new FastReader();
        int n = sc.nextInt();
        int[] as = new int[n];
        int[] bs = new int[n];
        for (int i = 0; i < n; i++) {
            as[i] = sc.nextInt();
        }
        for (int i = 0; i < n; i++) {
            bs[i] = sc.nextInt();
        }
        int max = 0;
        for (int i = 0; i < n; i++) {
            if (as[i] > max) {
                max = as[i];
            }
            if (bs[i] > max) {
                max = bs[i];
            }
        }
        int maxBits = Integer.toBinaryString(max).length();
        //System.out.println(maxBits);
        int ans = 0;
        for (int b = 0; b <= maxBits; b++) {
            int[] maskedAs = new int[n];
            int[] maskedBs = new int[n];
            int mask = (1 << (b + 1)) - 1;
            for (int i = 0; i < n; i++) {
                maskedAs[i] = as[i] & mask;
                maskedBs[i] = bs[i] & mask;
            }
            Arrays.sort(maskedBs);
            int T = 1 << b;
            int count = 0;
            for (int i = 0; i < n; i++) {
                int index1 = Arrays.binarySearch(maskedBs, T - maskedAs[i]);
                int index2 = Arrays.binarySearch(maskedBs, 2 * T - maskedAs[i]);
                int index3 = Arrays.binarySearch(maskedBs, 3 * T - maskedAs[i]);
                if (index1 < 0) {
                    index1 = ~index1;
                }
                if (index2 < 0) {
                    index2 = ~index2;
                }
                if (index3 < 0) {
                    index3 = ~index3;
                }
                count += index2 - index1 + n - index3;
                //System.out.printf("%d %d %d\n", index1, index2, index3);
            }
            System.out.println(count);
            if (count % 2 == 1) {
                ans |= 1 << b;
            }
        }
        System.out.println(ans);
    }

    static class FastReader
    {
        BufferedReader br;
        StringTokenizer st;

        public FastReader()
        {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next()
        {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine()
        {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		long[] a = new long[n];
		long[] b = new long[n];
		for(int i=0;i<n;i++) {
			a[i] = in.nextLong();
		}
		for(int i=0;i<n;i++) {
			b[i] = in.nextLong();
		}
		in.close();
		long[] pow2 = new long[29];
		pow2[0] = 1;
		for(int i=1;i<=28;i++) {
			pow2[i] = pow2[i-1]*2;
		}
		int ans = 0;
		for(int k=0;k<28;k++) {
			long[] tmpa = new long[n];
			long[] tmpb = new long[n];
			for(int i=0;i<n;i++) {
				tmpa[i] = a[i] % pow2[k+1];
				tmpb[i] = (b[i] % pow2[k+1])*2;
			}
			Arrays.sort(tmpb);
			int count = 0;
			for(int i=0;i<n;i++) {
				int start1 = Arrays.binarySearch(tmpb, (pow2[k]-tmpa[i])*2-1);
				start1 = start1<0 ? -(start1+1):start1+1;
				int end1 = Arrays.binarySearch(tmpb, (pow2[k]*2-tmpa[i])*2-1);
				end1 = end1<0 ? -(end1+1):end1+1;
				int start2 = Arrays.binarySearch(tmpb, (pow2[k]*3-tmpa[i])*2-1);
				start2 = start2<0 ? -(start2+1):start2+1;
				int end2 = Arrays.binarySearch(tmpb, (pow2[k]*4-tmpa[i])*2-1);
				end2 = end2<0 ? -(end2+1):end2+1;
				count += (end1 - start1)%2 + (end2 - start2)%2;
				count %= 2;
			}
			if(count%2==1) ans += pow2[k];
		}
		System.out.println(ans);

	}

}

import java.util.*;
