			a2[i] = a[i] & (bitFlag(bit + 1) - 1);
			b2[i] = b[i] & (bitFlag(bit + 1) - 1);
		}
		Arrays.sort(b2);
		long cnt = 0;
		for(int i = 0; i < num; i ++) {
			if(isFlagged(a2[i], bit)) {
				int l = lowerBound(b2, bitFlag(bit + 1) - a2[i]);
				int r = upperBound(b2, bitFlag(bit + 1) + bitFlag(bit) - 1 - a2[i]);
				cnt += num - (r - l);
			}else {
				int l = lowerBound(b2, bitFlag(bit) - a2[i]);
				int r = upperBound(b2, bitFlag(bit + 1) - 1 - a2[i]);
				cnt += r - l;
			}
		}
		ans += (cnt % 2) * pow(2, bit);
	}
