      for (int i = 0; i < N; i++) br[b[i] % m]++;

      int sumbr = 0;
      for (int i = m / 2; i < m; i++) sumbr += br[i];

      int c = 0;
      int q = m / 2;
      int r = m - 1;
      for (int p = 0; p < m; p++) {
        c += (ar[p] % 2) * (sumbr % 2);
        c %= 2;
        sumbr -= br[r];
        q--;
        r--;
        if (q < 0) q += m;
        sumbr += br[q];
