import java.util.Scanner;  

public class Q2_异或 {  
    public static void main(String[] args) {  
        trieNode root = new trieNode(-1);  
        Scanner sc = new Scanner(System.in);  
        int n = sc.nextInt();  
        int m = sc.nextInt();  
        int[] items = new int[n];  
        for(int i=0; i<n; i++){  
            items[i] = sc.nextInt();  
            insert(root, items[i]);  
        }  
        long result = 0;  
        for(int num : items){  
            result  += query(root, num, m, 31);
        }  
        System.out.println(result/2);  
    }  

    public static void insert(trieNode root, int number){  
        trieNode current = root;  
        for(int i=31; i>=0; i--){
            int digit = (number>>i)&1;  
            if(current.next[digit]==null){  
                current.next[digit] = new trieNode(digit);  
            }  
            current = current.next[digit];  
            current.count++;  
        }  
    }  

    public static int query(trieNode root, int a, int m, int k){  
        if(root == null){  
            return 0;  
        }  
        trieNode current = root;  
        for(int i=k; i>=0; i--){  
            int aDigit = (a>>i)&1;  
            int mDigit = (m>>i)&1;  
            if(aDigit == 1 && mDigit == 1){  
                if(current.next[0] == null){  
                    return 0;  
                }else{  
                    current = current.next[0];
                }  
            }else if(aDigit == 0 && mDigit ==1){  
                if(current.next[1] == null){  
                    return 0;  
                }else {  
                    current = current.next[1];  
                }  
            }else if(aDigit == 0 && mDigit == 0){  
                int p = query(current.next[0], a, m, i-1);  
                int q = (current.next[1]==null?0:current.next[1].count);  
                return p+q;  
            }else if(aDigit == 1 && mDigit == 0){  
                int p = query(current.next[1], a, m, i-1);  
                int q = (current.next[0]==null?0:current.next[0].count);  
                return p+q;  
            }  
        }         
        return 0;  
    }     
}  

class trieNode{  
    trieNode[] next = new trieNode[2];
    int count = 0; 
    int digit = 0;  
    public trieNode(int digit) {  
        this.digit = digit;  
    }  
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n = Integer.parseInt(br.readLine());
		String[] sa = br.readLine().split(" ");
		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = Integer.parseInt(sa[i]);
		}
		sa = br.readLine().split(" ");
		int[] b = new int[n];
		for (int i = 0; i < n; i++) {
			b[i] = Integer.parseInt(sa[i]);
		}
		br.close();

		int ans = 0;
		for (int k = 0; k < 29; k++) {
			int m = 1 << (k + 1);
			int[] c = new int[n];
			for (int i = 0; i < n; i++) {
				c[i] = b[i] % m;
			}
			Arrays.sort(c);

			int min = m / 2;
			int max = m - 1;
			long cnt = 0;
			for (int i = 0; i < n; i++) {
				int ai = a[i] % m;
				int mina = min - ai;
				int maxa = max - ai;
				if (mina < 0) {
					mina += m;
					int idxc = ceiling(c, mina);
					cnt += n - idxc;
					int idxf = floor(c, maxa);
					cnt += idxf + 1;
				} else {
					int idxc = ceiling(c, mina);
					int idxf = floor(c, maxa);
					cnt += idxf - idxc + 1;
				}
			}
			if (cnt % 2 == 1) {
				ans += 1 << k;
			}
		}
		System.out.println(ans);
	}

	static int floor(int[] array, int val) {
		int ok = -1;
		int ng = array.length;
		while (Math.abs(ok - ng) > 1) {
			int mid = (ok + ng) / 2;
			if (array[mid] <= val) {
				ok = mid;
			} else {
				ng = mid;
			}
		}
		return ok;
	}

	static int ceiling(int[] array, int val) {
		int ok = array.length;
		int ng = -1;
		while (Math.abs(ok - ng) > 1) {
			int mid = (ok + ng) / 2;
			if (array[mid] >= val) {
				ok = mid;
			} else {
				ng = mid;
			}
		}
		return ok;
	}
}

