import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final int[] as, bs;

  Solver(int n, int[] as, int[] bs) {
    this.n = n;
    this.as = as;
    this.bs = bs;
  }

  private int getCount1(int[] vs, int rightShift) {
    int count = 0;
    for (int v : vs) {
      count += ((v >> rightShift) & 1);
    }
    return count;
  }

  public int solve() {
    int answer = 0;
    // 0 bit
    if (n % 2 == 1 && (getCount1(as, 0) + getCount1(bs, 0)) % 2 == 1) {
      answer |= 1;
    }

    // 1 bit 以上
    for (int i = 1; i <= 29; i++) {
      int aCount = getCount1(as, i);
      int bCount = getCount1(bs, i);

      int mask = (1 << i) - 1;
      /*
      TreeMap<Integer, Integer> counter = new TreeMap<Integer, Integer>();
      for (int b : bs) {
        int bMask = b & mask;
        counter.put(bMask, counter.getOrDefault(bMask, 0) + 1);
      }
      */
      Map<Integer, Integer> counter = new HashMap<Integer, Integer>();
      for (int b : bs) {
        int bMask = b & mask;
        counter.put(bMask, counter.getOrDefault(bMask, 0) + 1);
      }
      List<Integer> sortedBMaskList = new ArrayList<>();
      for (int bMask : counter.keySet()) {
        sortedBMaskList.add(bMask);
      }
      Collections.sort(sortedBMaskList);

      TreeMap<Integer, Integer> map = new TreeMap<Integer, Integer>();
      int total = 0;
      map.put(1 << i, total);
      for (int j = sortedBMaskList.size() - 1; j >= 0; j--) {
        int bMask = sortedBMaskList.get(j);
        total += counter.get(bMask);
        map.put(bMask, total);
      }

      int carryCount = 0;
      for (int a : as) {
        int aMask = a & mask;
        int required = (1 << i) - aMask;
        carryCount += map.ceilingEntry(required).getValue();
      }

//      System.out.printf("%d %d %d %d\n", i, aCount, bCount, carryCount);
      if ((n % 2 == 1 && (aCount + bCount) % 2 == 1) != ((carryCount % 2) == 1)) {
        answer |= (1 << i);
      }
    }
    return answer;
  }
}

