import java.util.*;
public class Main {
    static int lowerBound(int a[], int v) {
        int l = 0, r = a.length - 1;
        while (r - l >= 0) {
            int c = (l + r) / 2;
            if (v <= a[c]) {
                r = c - 1;
            } else {
                l = c + 1;
            }
        }
        return l;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int A[] = new int[N], B[] = new int[N];
        for (int n = 0; n < N; n++) {
            A[n] = sc.nextInt();
        }
        for (int n = 0; n < N; n++) {
            B[n] = sc.nextInt();
        }
        int ans = 0;
        for (int k = 0; k < 30; k++) {
            int[] a = Arrays.copyOf(A, N);
            int[] b = Arrays.copyOf(B, N);
            for (int i = 0; i < N; i++) {
                a[i] &= (1 << (k + 1)) - 1;
                b[i] &= (1 << (k + 1)) - 1;
            }
            int count = 0;
            Arrays.sort(b);
            for (int i = 0; i < N; i++) {
                int k1 = lowerBound(b, (1 << k) - a[i]);
                int k2 = lowerBound(b, (1 << (k + 1)) - a[i]);
                count += k2 - k1;
                if (k >= 1) {
                    int k3 = lowerBound(b, (3 << k) - a[i]);
                    count += N - k3;
                }
                count %= 2;
            }
            if (count % 2 == 1) {
                ans |= 1 << k;
            }
        }
        System.out.println(ans);
        sc.close();
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int[] a = new int[N];
    int[] b = new int[N];

    for (int i = 0; i < N; i++) a[i] = scanner.nextInt();
    for (int i = 0; i < N; i++) b[i] = scanner.nextInt();
    Arrays.sort(b);

    int res = 0;

    for (int k = 0; k < 28; k++) {
      int count = 0;
      for (int i = 0; i < N; i++) {
        final int t = 1 << k;
        for (int tt = t; tt <= 400_000; tt += t * 2) {
          int left = find(b, tt - a[i]);
          int right = find(b, tt + t - a[i]);
          count += right - left;
        }
      }
      if (count % 2 == 1) res += 1 << k;
    }

    System.out.println(res);
  }

  private static int find(int[] b, int t) {
    int left = -1;
    int right = b.length;
    while (right - left > 1) {
      int mid = (left + right) / 2;
      if (b[mid] < t) {
        left = mid;
      } else {
        right = mid;
      }
    }
    return left;
  }
}

import java.util.Arrays;
import java.util.Scanner;
import java.util.stream.IntStream;

/**
 * 解説どおりに作成したソースコード
 * 
 * https://atcoder.jp/contests/abc091/submissions/5275478 にも参考
 */
public class Main {

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt();
			int[] a = new int[n], b = new int[n];
			int[] na = new int[n], nb = new int[n];
			IntStream.range(0, n).forEach(i -> a[i] = scanner.nextInt());
			IntStream.range(0, n).forEach(i -> b[i] = scanner.nextInt());
			int answer = 0;
			for (int k = 0; k < 30; k++) {
				int mask = (1 << (k + 1)) - 1;
				for (int i = 0; i < n; i++) {
					na[i] = a[i] & mask;
					nb[i] = b[i] & mask;
				}
				Arrays.sort(nb);
				int count = 0;
				for (int i = 0; i < n; i++) {
					count += lowerBound(nb, (2 << k) - na[i]) - lowerBound(nb, (1 << k) - na[i]);
					count += n - lowerBound(nb, (3 << k) - na[i]);
					count &= 1;
				}
				if (1 == (count & 1)) {
					answer |= 1 << k;
				}
			}
			System.out.println(answer);
		}
	}

	/**
	 * 配列aにおける値vのlowerBoundを計算する
	 * 
	 * @param a
	 * @param v
	 * @return 配列aにおける値vのlowerBound
	 */
	private static int lowerBound(int a[], int v) {
		int l = 0, r = a.length - 1;
		while (r - l >= 0) {
			int c = (l + r) / 2;
			if (v <= a[c]) {
				r = c - 1;
			} else {
				l = c + 1;
			}
		}
		return l;
	}
}

