public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static final long mod = (long) 1e9 + 7;
	static final int dx[] = { -1, 0, 1, 0 }, dy[] = { 0, -1, 0, 1 };
	static final int[] dx8 = { -1, -1, -1, 0, 0, 1, 1, 1 }, dy8 = { -1, 0, 1, -1, 1, -1, 0, 1 };
	static final int inf = Integer.MAX_VALUE / 3;
	static final long linf = Long.MAX_VALUE / 3;
	static final double dinf = Double.MAX_VALUE / 3;

	static void solve() {
		int n = ni();
		int a[] = na(n);
		int b[] = na(n);
		long ans = 0;
		for(int i=0;i<32;i++) {//ibit目の1の数を調べる
			int t = 1<<i;//2^i
			long cnt = 0;
			Integer c[] = new Integer[n], d[] = new Integer[n];
			for(int j=0;j<n;j++) {
				c[j] = a[j] % t;
				d[j] = b[j] % t;
			}
			Arrays.sort(c);
			Arrays.sort(d);
			for(int j=0;j<n;j++) {
				//t = 2^iとする
				int r1 = t - c[j];
				int r2 = 2*t - c[j];
				int r3 = 3*t - c[j];
				int r4 = 4*t - c[j];

				//a + b が[0,T)にある数
				int s1 = lowerBound(d, r1);
				//a + b が[T,2T)にある数
				int s2 = lowerBound(d, r2) - s1;				
				//a + b が[2T,3T)にある数
				int s3 = lowerBound(d, r3) - s2 - s1;
				//a + b が[3T,4T)にある数
				int s4 = lowerBound(d, r4) - s3 - s2 - s1;

				cnt += s2 + s4;
			}
			if(cnt % 2==1) ans |= 1<<i;
		}
		out.println(ans);

	}

	//libraries	
	/**	
	*	upperBound
	*	@param List<T> 探索対象のList
	*   @param T 探索値
	*	@return xよりも大きい要素のうち、indexが最小の物のindex
	*/
	static <T> int upperBound(List<T> ls, T x) throws RuntimeException {
		if (ls.size() == 0)
			return -1;
		if (ls.get(0) instanceof Integer) {
			return ~Collections.binarySearch(ls, x, (t1, t2) -> ((Integer) t1).compareTo((Integer) t2) > 0 ? 1 : -1);
		} else if (ls.get(0) instanceof Long) {
			return ~Collections.binarySearch(ls, x, (t1, t2) -> ((Long) t1).compareTo((Long) t2) > 0 ? 1 : -1);
		} else if (ls.get(0) instanceof Double) {
			return ~Collections.binarySearch(ls, x, (t1, t2) -> ((Double) t1).compareTo((Double) t2) > 0 ? 1 : -1);
		} else {
			System.err.println(
					String.format("%s:数値でないリストを二分探索しています。", Thread.currentThread().getStackTrace()[1].getMethodName()));
			throw new RuntimeException();
		}
	}

	/**	
	*	lowerBound
	*	@param List<T> 探索対象のList
	*   @param T 探索値
	*	@return x以上の要素のうち、indexが最小の物のindex
	*/
	static <T> int lowerBound(List<T> ls, T x) {
		if (ls.size() == 0)
			return -1;
		if (ls.get(0) instanceof Integer) {
