    void solve() {
        int n = in.nextInt();
        int[] a = in.nextIntArray(n);
        int[] b = in.nextIntArray(n);
        long ans = 0;
        for (int bit = 0; bit <= 30; bit++) {
            long m = 1l << bit;
            long[] c = Arrays.stream(a).mapToLong(i -> i % (m << 1)).toArray();
            long[] d = Arrays.stream(b).mapToLong(i -> i % (m << 1)).toArray();
            Arrays.sort(d);
            long set = 0;
            for (long x : c) {
                // i + j ~ [m, 2m) + [3m, 4m)
                // + [m, 4m)
                set += ArrayUtils.inRange(d, m - x, m * 4 - x);
                // - [2m, 3m)
                set -= ArrayUtils.inRange(d, m * 2 - x, m * 3 - x);
            }
            if (set % 2 == 1) ans |= m;
        }
        printf(ans);
    }

    static class ArrayUtils {
        public static int lowerBound(long[] a, int l, int r, long k) {
            int m = 0, ans = r;
            while (l < r) if (a[m = l + r >> 1] >= k) ans = r = m; else l = m + 1;
            return ans;
        }

        public static int upperBound(long[] a, int l, int r, long k) {
            int m = 0, ans = r;
            while (l < r) if (a[m = l + r >> 1] > k) ans = r = m; else l = m + 1;
            return ans;
        }

        public static int lowerBound(long[] a, long k) {
            return lowerBound(a, 0, a.length, k);
        }

        public static int upperBound(long[] a, long k) {
            return upperBound(a, 0, a.length, k);
        }

        public static int inRange(long[] a, long l, long r) {
            return lowerBound(a, r) - lowerBound(a, l);
        }
    }

