			int t = 1 << k;
			for (int i = 0; i < n; i++) {
				tmp += lowerBound(b, 2*t - a[i]) - lowerBound(b, 1*t - a[i]);
				tmp += lowerBound(b, 4*t - a[i]) - lowerBound(b, 3*t - a[i]);
			}

			if (tmp % 2 == 1) {
				ans |= 1 << k;
			}
		}

		System.out.println(ans);
		in.close();
	}

	public static int lowerBound(long[] a, long obj) {
		int l = 0, r = a.length - 1;
		while (r - l >= 0) {
			int c = (l + r) / 2;
			if (obj <= a[c]) {
				r = c - 1;
			} else {
				l = c + 1;
			}
		}
		return l;
	}

}

