    int N = scanner.nextInt();
    int[] a = new int[N];
    int[] b = new int[N];

    for (int i = 0; i < N; i++) a[i] = scanner.nextInt();
    for (int i = 0; i < N; i++) b[i] = scanner.nextInt();

    int res = 0;

    for (int k = 0; k < 30; k++) {
      int m = 1 << (k + 1);

      int[] br = new int[N];
      for (int i = 0; i < N; i++) br[i] = b[i] % m;
      Arrays.sort(br);

      int[] br2 = new int[N * 2];
      System.arraycopy(br, 0, br2, 0, N);
      for (int i = 0; i < N; i++) br2[i + N] = br[i] + m;

      int t = 1 << k;
      long count = 0;
      for (int i = 0; i < N; i++) {
        int ar = a[i] % m;
        int left = find(br2, t * 3 - ar);
        int right = find(br2, t * 4 - ar);
        count += right - left;
      }
      if (count % 2 == 1) res += 1 << k;
    }

    System.out.println(res);
  }

  private static int find(int[] b, int t) {
    int left = -1;
    int right = b.length;
    while (right - left > 1) {
      int mid = (left + right) / 2;
      if (b[mid] < t) {
        left = mid;
      } else {
        right = mid;
      }
    }
    return left;
  }
}

