import java.util.*;

class Main{
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int a[] = new int[n];
        int b[] = new int[n];
        int c[] = new int[n];
        int d[] = new int[n];
        for(int i=0;i<n;i++) a[i]=sc.nextInt();
        for(int i=0;i<n;i++) b[i]=sc.nextInt();
        int maxdigit = 28;
        int answer = 0;
        for(int k=0;k<=maxdigit;k++){
            int number = 0;
            int mod = 1<<k+1;
            for(int i=0;i<n;i++) c[i]=a[i]%mod;
            for(int i=0;i<n;i++) d[i]=b[i]%mod;
            Arrays.sort(d);
            int t = 1<<k;
            //BinarySearch for every a[i]
            for(int i=0;i<n;i++){
                //BinarySearch and add to number;
                int t1 = bsearch(t-c[i], d, n);
                int t2 = bsearch(2*t-c[i], d, n);
                int t3 = bsearch(3*t-c[i], d, n);
                int t4 = bsearch(4*t-c[i], d, n);
                number += t1-t2+t3-t4;
            }
            if (number%2==1) answer += (1<<k);
        }
        System.out.println(answer);
    }
    public static int bsearch(int lbound,int[] array,int length){
        if(array[0]>=lbound) return(length);
        if(array[length-1]<lbound) return(0);
        int ok = length-1;
        int ng = 0;
        while(ok>ng+1){
            int mid = (ok+ng)/2;
            if(array[mid]>=lbound){
                ok = mid;
            } else {
                ng = mid;
            }
        }
        return(length-ok);
    }
}

import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final int[] as, bs;

  Solver(int n, int[] as, int[] bs) {
    this.n = n;
    this.as = as;
    this.bs = bs;
  }

  private int getCount1(int[] vs, int rightShift) {
    int count = 0;
    for (int v : vs) {
      count += ((v >> rightShift) & 1);
    }
    return count;
  }

  public int solve() {
    int answer = 0;
    // 0 bit
    if (n % 2 == 1 && (getCount1(as, 0) + getCount1(bs, 0)) % 2 == 1) {
      answer |= 1;
    }

    // 1 bit 以上
    for (int i = 1; i <= 28; i++) {
      int aCount = getCount1(as, i);
      int bCount = getCount1(bs, i);

      int mask = (1 << i) - 1;
      TreeMap<Integer, Integer> counter = new TreeMap<Integer, Integer>();
      for (int b : bs) {
        int bMask = b & mask;
        counter.put(bMask, counter.getOrDefault(bMask, 0) + 1);
      }

      TreeMap<Integer, Integer> map = new TreeMap<Integer, Integer>();
      int total = 0;
      map.put(1 << i, total);
      for (Map.Entry<Integer, Integer> entry : counter.descendingMap().entrySet()) {
        total += entry.getValue();
        map.put(entry.getKey(), total);
      }

      int carryCount = 0;
      for (int a : as) {
        int aMask = a & mask;
        int required = (1 << i) - aMask;
        carryCount += map.ceilingEntry(required).getValue();
      }

//      System.out.printf("%d %d %d %d\n", i, aCount, bCount, carryCount);
      if ((n % 2 == 1 && (aCount + bCount) % 2 == 1) != ((carryCount % 2) == 1)) {
        answer |= (1 << i);
      }
    }
    return answer;
  }
}

