	private static long[][] matrix_pow(long[][] mat, int e) {
		long[][] ans = new long[2][2];
		for (int i = 0; i < mat.length; i++)
			ans[i][i] = 1;
		while (e > 0) {
			if ((e & 1) == 1)
				ans = mult(ans, mat);
			mat = mult(mat, mat);
			e >>= 1;
		}

		return ans;
	}

	private static long[][] mult(long[][] a, long[][] b) {
		int n = a.length;
		int m = a[0].length;
		int k = b[0].length;
		long[][] res = new long[n][k];
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < k; j++) {
				for (int p = 0; p < m; p++) {
					res[i][j] = (res[i][j] + (a[i][p] * b[p][j]) % mod) % mod;
				}
			}
		}
		return res;
	}

