			long min=1,max=0,ans=0;;
			for(int i=0;i<n;i++){
				arr[i]=sc.nextInt();
				max+=arr[i];
			}
			while(min<=max){
				long mid=(min+max)>>1;
			if(func(mid,arr,h)){
				ans=mid;
				max=mid-1;
			} else
				min=mid+1;
			}
			System.out.println(ans);
		}
	}

	private static boolean func(long mid, int[] arr, int h) {
		long ans=0;
		for(int i=0;i<arr.length;i++)ans+=(arr[i]+mid-1)/mid;
		return ans<=h;
	}

