using INTEGER = System.Int32;
class ABC091_d {
    static INTEGER LowerBound(INTEGER[] a, INTEGER v) {
        INTEGER l = 0, r = a.Length - 1;
        while (r - l >= 0) {
            INTEGER c = (l + r) / 2;
            if (v <= a[c]) {
                r = c - 1;
            } else {
                l = c + 1;
            }
        }
        return l;
    }
    static void Main(string[] args) {
        int N = int.Parse(Console.ReadLine());
        INTEGER[] A = Array.ConvertAll(Console.ReadLine().Split(' '), INTEGER.Parse);
        INTEGER[] B = Array.ConvertAll(Console.ReadLine().Split(' '), INTEGER.Parse);
        INTEGER[] a = new INTEGER[N], b = new INTEGER[N];
        INTEGER ans = 0;
        for (int k = 0; k < 30; k++) {
            A.CopyTo(a, 0);
            B.CopyTo(b, 0);
          //INTEGER mask = (1 << (k + 1)) - 1;
            for (int i = 0; i < N; i++) {
                a[i] &= (1 << (k + 1)) - 1;
                b[i] &= (1 << (k + 1)) - 1;
            }
            INTEGER count = 0;
            Array.Sort(b);
            for (int i = 0; i < N; i++) {
                INTEGER k1 = LowerBound(b, (1 << k) - a[i]);
                INTEGER k2 = LowerBound(b, (1 << (k + 1)) - a[i]);
                count += k2 - k1;
                if (k >= 1) {
                    INTEGER k3 = LowerBound(b, (3 << k) - a[i]);
                    count += N - k3;
                }
                count %= 2;
            }
            if (count % 2 == 1) {
                ans |= 1 << k;
            }
        }
        Console.WriteLine(ans);
    } //Main
}

