				// Aごとに +B との和が
				//   T以上、2T以上、3T以上
				// となる Bの範囲 をしゃくとり的に調べる
				var t = 1 << k;
				int dnum = 0;
				//int b1 = 0, b2 = 0, b3 = 0;
				for (int i = N - 1; i >= 0; i--) {
					var a = As[i];
					//b1 = Incr(Bs, b1, t - a);
