class ABC091_d {
    static int LowerBound(int[] a, int v) {
        int l = 0, r = a.Length - 1;
        while (r - l >= 0) {
            int c = (l + r) / 2;
            if (v <= a[c]) {
                r = c - 1;
            } else {
                l = c + 1;
            }
        }
        return l;
    }
    static void Main(string[] args) {
        int N = int.Parse(Console.ReadLine());
        int[] A = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
        int[] B = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
        int ans = 0;
        for (int k = 0; k < 28; k++) {
            int mask = (1 << (k + 1)) - 1;
            int[] a = new int[N], b = new int[N];
            for (int i = 0; i < N; i++) {
                a[i] = A[i] & mask;
                b[i] = B[i] & mask;
            }
            int count = 0;
            Array.Sort(b);
            for (int i = 0; i < N; i++) {
                var t = 1 << i;
                int k1 = LowerBound(b, t - a[i]);
                int k2 = LowerBound(b, 2 * t - a[i]);
                count += k2 - k1;
                if (k >= 1) {
                    int k3 = LowerBound(b, 3 * t - a[i]);
                    count += N - k3;
                }
                count %= 2;
            }
            if (count % 2 == 1) ans |= 1 << k;
        }
        Console.WriteLine(ans);
    } //Main
}

using System;

class MainClass
{
  static readonly int BIT_NUM = 28;

  public static void Main()
  {
    var N = int.Parse(Console.ReadLine());
    var a = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
    var b = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
    Array.Sort(b);

    long ans = 0;
    for (var i = 0; i <= BIT_NUM; i++)
    {
      var mask = (1 << i + 1) - 1;
      var maskedA = new int[N];
      var maskedB = new int[N];
      for (var j = 0; j < N; j++)
      {
        maskedA[j] = a[j] & mask;
        maskedB[j] = b[j] & mask;
      }
      Array.Sort(maskedB);

      var T = 1 << i;
      long parity = 0;
      for (var j = 0; j < N; j++)
      {
        var num1 = LowerBound(maskedB, T - maskedA[j]);
        var num2 = LowerBound(maskedB, 2 * T - maskedA[j]);
        var num3 = LowerBound(maskedB, 3 * T - maskedA[j]);
        // var num4 = LowerBound(maskedB, 4 * T - maskedA[j]);
        parity += (num2 - num1) + (N - num3);
      }
      ans |= (parity & 1) << i; // Check if parity is Even or Odd
    }
    Console.WriteLine($"{ans}");
  }

  private static int LowerBound(int[] arr, int val)
  {
    int first = 0, last = arr.Length - 1, mid;
    while (first <= last)
    {
      mid = (first + last) >> 1;
      if (val > arr[mid]) first = mid + 1;
      else last = mid - 1;
    }
    return first;
  }
}

