using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ConsoleApp3
{
    class Program
    {

        public static List<T> ReadList<T>(Func<string, T> f)
        {
            return Console.ReadLine().Split(' ').Select(f).ToList();
        }

        public static int ReadInt()
        {
            return Convert.ToInt32(Console.ReadLine());
        }

        static void Main(string[] args)
        {
            var N = ReadInt();
            var A = ReadList(s => int.Parse(s) << 1);
            var B = ReadList(s => int.Parse(s) << 1);
            var res = 0;

            for (int i = 29; i > 0; i--)
            {
                var n = 1 << i;
                var m = n << 1;
                var mask = m - 1;

                //n-bit以下にカットして並び替える
                for (int k = 0; k < B.Count; k++)
                    B[k] &= mask;
                B.Sort();

                for (int k = 0; k < A.Count; k++)
                {
                    var val = A[k] & mask;

                    //繰り上がりしてnbit目が1になる位置
                    var noUpCnt = B.BinarySearch(n - val -1 );
                    if (noUpCnt < 0)
                        noUpCnt = ~noUpCnt;

                    //繰り上がりしてnbit目が0になる位置
                    var upCnt = B.BinarySearch(m - val - 1);
                    if (upCnt < 0)
                        upCnt = ~upCnt;

                    //繰り上がりしてもnbit目に1が残る位置
                    var remCnt = B.BinarySearch(n + m - val - 1);
                    if (remCnt < 0)
                        remCnt = ~remCnt;

                    //nbit目が「1」の数
                    var cnt1 = upCnt - noUpCnt;
                    cnt1 += (B.Count - remCnt);

                    res ^= (cnt1 & 1) << i;
                }
            }

            res >>= 1;
            Console.WriteLine(res);
        }

    }
}

