        var b = Console.ReadLine().Split().Select(int.Parse).ToArray();
        long res = 0;
        for (int i = 0; i < 29; i++)
        {
            long totalCount = 0;
            int lessInd1 = -1;
            int moreInd1 = -1;
            int lessInd2 = -1;
            int moreInd2 = -1;
            var orderedAUntil = a.Select(x => x & ((1 << i + 1) - 1)).OrderByDescending(x => x).ToArray();
            foreach (var bElem in b.Select(x => x & ((1 << i + 1) - 1)).OrderBy(x => x))
