                    if ((1 << (i + 1)) <= orderedAUntil[lessInd1 + 1] + bElem) lessInd1++;
                    else break;
                }
                while (moreInd1 + 1 < orderedAUntil.Length)
                {
                    if ((1 << i) <= orderedAUntil[moreInd1 + 1] + bElem) moreInd1++;
                    else break;
                }
                while (lessInd2 + 1 < orderedAUntil.Length)
                {
                    if ((1 << (i + 1)) + (1 << (i + 1)) <= orderedAUntil[lessInd2 + 1] + bElem) lessInd2++;
                    else break;
                }
                while (moreInd2 + 1 < orderedAUntil.Length)
                {
                    if ((1 << (i + 1)) + (1 << i) <= orderedAUntil[moreInd2 + 1] + bElem) moreInd2++;
                    else break;
                }
                totalCount += moreInd1 - lessInd1 + (moreInd2 - lessInd2);
            }
            res |= ((totalCount & 1) << i);
        }
