namespace Competitive
{
    internal class Solution
    {
        public int N;
        public int[] A, B;
        public bool[] Used;

        public void Run()
        {
            {
                N = Input.ReadInt();
                A = Input.ReadIntArray();
                B = Input.ReadIntArray();
            }

            long ret = 0;
            int mask = 1 << 29;
            while (mask > 0)
            {
                var A0 = new List<int>();
                var A1 = new List<int>();
                var B0 = new List<int>();
                var B1 = new List<int>();

                for (int i = 0; i < N; i++)
                {
                    if ((A[i] & mask) == mask)
                    {
                        A0.Add(A[i] & (mask - 1));
                    }
                    else
                    {
                        A1.Add(A[i] & (mask - 1));
                    }

                    if ((B[i] & mask) == mask)
                    {
                        B0.Add(B[i] & (mask - 1));
                    }
                    else
                    {
                        B1.Add(B[i] & (mask - 1));
                    }

                }


                A0.Sort();
                A1.Sort();
                B0.Sort();
                B1.Sort();

                long count = 0;

                for (int i = 0; i < A0.Count; i++)
                {
                    for (int j = 0; j < B0.Count; j++)
                    {
                        if (A0[i] + B0[j] >= mask) count++;
                    }
                    for (int j = 0; j < B1.Count; j++)
                    {
                        if (A0[i] + B1[j] < mask) count++;
                    }
                }

                for (int i = 0; i < A1.Count; i++)
                {
                    for (int j = 0; j < B0.Count; j++)
                    {
                        if (A1[i] + B0[j] < mask) count++;
                    }
                    for (int j = 0; j < B1.Count; j++)
                    {
                        if (A1[i] + B1[j] >= mask) count++;
                    }
                }

                if (count % 2 == 1) ret += mask;

                mask /= 2;
            }

            Console.WriteLine(ret);
        }
    }

