namespace ABC091.D
{
	using static Util;

	public class Solver : SolverBase
	{
		public void Run() {
			var N = ReadInt();

			var As = ReadIntArray();
			var Bs = ReadIntArray();

			uint ans = 0;

			// 最上位ビットから調べる
			for (int k = 28; k >= 0; k--) {
				var mask = (1 << k + 1) - 1;
				for (int i = 0; i < N; i++) {
					As[i] &= mask;
					Bs[i] &= mask;
				}
				Array.Sort(As);
				//Array.Reverse(As);
				Array.Sort(Bs);
				//Dump(As);
				//Dump(Bs);

				// Aごとに +B との和が
				//   T以上、2T以上、3T以上
				// となる Bの範囲 をしゃくとり的に調べる
				var t = 1 << k;
				int dnum = 0;
				int b1 = 0, b2 = 0, b3 = 0;
				for (int i = N - 1; i >= 0; i--) {
					var a = As[i];
					b1 = Incr(Bs, b1, t - a);
					ReplaceIfBigger(ref b2, b1);
					b2 = Incr(Bs, b2, t * 2 - a);
					ReplaceIfBigger(ref b3, b2);
					b3 = Incr(Bs, b3, t * 3 - a);

					//dnum += (N - b3) + (N - b1) - (N - b2);
					dnum += N - b3 - b1 + b2;
				}

				if (dnum % 2 == 1) {
					ans |= (1U << k);
				}
			}
			WriteLine(ans);
		}

		int Incr<T>(IList<T> list, int i, T v) where T : IComparable<T> {
			while (i < list.Count && list[i].CompareTo(v) < 0) ++i;
			return i;
		}
