using System;
class ABC091_d {
    public static void Main() {
        var N = int.Parse(Console.ReadLine());
        var A = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        var B = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        long ans = 0;
        for (var i = 0; i < 29; i++) {
            var mA = new int[N];
            var mB = new int[N];
            var mask = (1 << i + 1) - 1;
            for (var j = 0; j < N; j++) {
                mA[j] = A[j] & mask;
                mB[j] = B[j] & mask;
            }
            Array.Sort(mB);
            long count = 0;
            var T = 1 << i;
            for (var j = 0; j < N; j++) {
                var n1 = LowerBound(mB,     T - mA[j]);
                var n2 = LowerBound(mB, 2 * T - mA[j]);
                var n3 = LowerBound(mB, 3 * T - mA[j]);
                count += (n2 - n1) + (N - n3);
            }
            ans |= (count & 1) << i;
        }
        Console.WriteLine(ans);
    }
    private static int LowerBound(int[] arr, int val) {
        int left = 0, right = arr.Length - 1, center;
        while (left <= right) {
            center = (left + right) >> 1;
            if (val > arr[center]) left = center + 1;
            else right = center - 1;
        }
        return left;
    }
}

