public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        var arr = cr.Repeat(N).Int;
        var brr = cr.Repeat(N).Int;
        int res = 0;
        var crr = new int[N];
        for (int k = 28; k >= 0; k--)
        {
            var t = 1 << k;
            var m = t << 1;
            for (int i = 0; i < brr.Length; i++)
                crr[i] = brr[i] % m;
            crr.Sort();
            var cnt = 0;
            foreach (var ao in arr)
            {
                var a = ao % m;
                var onemin = crr.LowerBound(t - a);
                var onemax = crr.LowerBound(2 * t - a);
                var threemin = crr.LowerBound(3 * t - a);
                var threemax = crr.LowerBound(4 * t - a);
                cnt += onemax - onemin + threemax - threemin;
            }
            res |= (cnt & 1) << k;
        }
        return res;
    }
}
static class 二分探索
{
    public static int BinarySearch(int ok, int ng, Predicate<int> isOK)
    {
        while (Math.Abs(ok - ng) > 1)
        {
            var m = (ok + ng) / 2;
            if (isOK(m)) ok = m;
            else ng = m;
        }
        return ok;
    }

    static int BinarySearch<T>(IList<T> a, T v, IComparer<T> cmp, bool isLowerBound)
        => BinarySearch(a.Count, -1, m => { var c = cmp.Compare(a[m], v); return c > 0 || (c == 0 && isLowerBound); });


    /// <summary>
    /// 与えられた比較関数に従って，<paramref name="a"/> の要素のうち，<paramref name="v"/> 以上の要素であるような最小のインデックスを取得します．
    /// </summary>
    /// <typeparam name="T"><see cref="IList{T}"/> の要素の型を指定します．</typeparam>
    /// <param name="a">対象となるコレクション</param>
    /// <param name="v">対象となる要素</param>
    /// <param name="f"></param>
    /// <returns><paramref name="v"/> 以上の要素であるような最小の o-indexed でのインデックス．</returns>
    /// <remarks> <paramref name="a"/> は比較関数に対して昇順であることを仮定しています．この関数は O(log N) で実行されます．</remarks>
    public static int LowerBound<T>(this IList<T> a, T v, Comparison<T> f) => BinarySearch(a, v, Comparer<T>.Create(f), true);

    /// <summary>
    ///　デフォルトの比較関数に従って，<paramref name="a"/> の要素のうち，<paramref name="v"/> 以上の要素であるような最小のインデックスを取得します．
