namespace AtCoder
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = int.Parse(Console.ReadLine());
            var A = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();
            var B = Console.ReadLine().Split(' ').Select(x => int.Parse(x)).ToArray();


            int bits = 0;
            var cts = new int[29];
            for (int k = 0; k < 29; k++)
            {
                var T = 1 << k;
                var bmods = B.Select(x => x % (2 * T)).OrderBy(x => x).ToArray();
                var ct = 0;
                foreach (var a in A)
                {
                    var am = a % (2 * T);
                    {
                        var left = binsearch(bmods, T - am);
                        if (left >= 0)
                        {
                            var right = binsearch(bmods, 2*T - am);
                            ct += right > 0 ? right - left : B.Length - left;
                        }
                    }
                    {
                        var left = binsearch(bmods, 3*T - am);
                        if (left >= 0)
                        {
                            var right = binsearch(bmods, 4*T - am);
                            ct += right > 0 ? right - left : B.Length - left;
                        }
                    }
                }
                cts[k] = ct;
                if (ct%2==1)
                {
                    bits |= 1 << k;
                }
            }
            Console.WriteLine(bits);
        }


        public static int binsearch(int[] list, int value)
        {
            var imin = 0;
            var imax = list.Length - 1;
            if (list[imax] < value)
            {
                return -1;
            }
            int i = 0;
            while (imin < imax)
            {
                i = imin + (imax - imin) / 2;
                if (list[i]>= value)
                {
                    imax = i;
                }
                else
                {
                    imin = i+1;
                }
            }
            return imin;
        }
    }
}

