class D
{
	static void Main()
	{
		var p2 = Enumerable.Range(0, 30).Select(i => (int)Math.Pow(2, i)).ToArray();
		var n = int.Parse(Console.ReadLine());
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var a = read();
		var b = read();

		var r = 0;
		for (int k = 0; k <= 28; k++)
		{
			var mask = p2[k + 1] - 1;
			var a2 = Array.ConvertAll(a, x => x & mask);
			var b2 = Array.ConvertAll(b, x => x & mask);
			Array.Sort(b2);

			var c = 0L;
			for (int i = 0; i < n; i++)
			{
				var v = p2[k] - a2[i];
				var j1 = First(0, n, j => b2[j] >= v);
				v += p2[k];
				var j2 = First(0, n, j => b2[j] >= v);
				v += p2[k];
				var j3 = First(0, n, j => b2[j] >= v);
				c += j2 - j1 + n - j3;
			}
			if (c % 2 == 1) r |= p2[k];
		}
		Console.WriteLine(r);
	}

	static int First(int l, int r, Func<int, bool> f)
	{
		int m;
		while (l < r) if (f(m = l + (r - l - 1) / 2)) r = m; else l = m + 1;
		return r;
	}
