class D
{
	static void Main()
	{
		var p2 = Enumerable.Range(0, 30).Select(i => (int)Math.Pow(2, i)).ToArray();
		var n = int.Parse(Console.ReadLine());
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var a = read();
		var b = read();

		var r = 0;
		for (int k = 0; k <= 28; k++)
		{
			var mask = p2[k + 1] - 1;
			var a2 = Array.ConvertAll(a, x => x & mask);
			var b2 = Array.ConvertAll(b, x => x & mask);
			Array.Sort(b2);

			var c = 0L;
			for (int i = 0; i < n; i++)
			{
				var j1 = SearchGeq(b2, p2[k] - a[i]);
				var j2 = SearchGeq(b2, 2 * p2[k] - a[i]);
				var j3 = SearchGeq(b2, 3 * p2[k] - a[i]);
				c += j2 - j1 + n - j3;
			}
			if (c % 2 == 1) r |= p2[k];
		}
		Console.WriteLine(r);
	}

	static int SearchGeq(int[] a, int v)
	{
		var i = Array.BinarySearch(a, v);
		return i >= 0 ? i : ~i;
	}
}

