	public class Solver : SolverBase
	{
		public void Run() {
			var N = ReadInt();

			var As = ReadLongArray();
			var Bs = ReadLongArray();

			ulong ans = 0;

			// 最上位ビットから調べる
			for (int k = 29; k >= 0; k--) {
				var t = (long)Math.Pow(2, k);
				for (int i = 0; i < N; i++) {
					As[i] %= t * 2;
					Bs[i] %= t * 2;
				}
				Array.Sort(As);
				Array.Sort(Bs);
				//Dump(As);
				//Dump(Bs);

				// Aごとに +B との和が
				//   T以上、2T以上、3T以上
				// となる Bの範囲 を2分探索で調べる
				int dnum = 0;
				for (int i = 0; i < N; i++) {
					var a = As[i];
					var b1 = BinarySearch(Bs, t - a);
					var b2 = BinarySearch(Bs, t * 2 - a);
					var b3 = BinarySearch(Bs, t * 3 - a);
					dnum += (N - b3) + (N - b1) - (N - b2);
				}

				if (dnum % 2 == 1) {
					ans |= (1UL << k);
				}
			}
			WriteLine(ans);
		}

