namespace AtTest.D_Challenge
{
    class ABC_091
    {
        static void Main(string[] args)
        {
            Method(args);
            Console.ReadLine();
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            int[] array = ReadInts();
            int[] bArray = ReadInts();
            var aMods = new int[30][];
            var bMods = new int[30][];
            for (int i = 0; i < 30; i++)
            {
                aMods[i] = new int[n];
                bMods[i] = new int[n];
                int div = 2 << i;
                for(int j = 0; j < n; j++)
                {
                    aMods[i][j] = array[j] % div;
                    bMods[i][j] = bArray[j] % div;
                }
            }
            int[] cntTest = new int[30];
            for(int i = 0; i < n; i++)
            {
                for(int j = 0; j < n; j++)
                {
                    int ab = array[i] + bArray[j];
                    for(int k = 0; k < 30; k++)
                    {
                        if ((ab & (1 << k)) > 0) cntTest[k]++;
                    }
                }
            }
            //for (int i = 0; i < 30; i++) Console.WriteLine(cntTest[i]);

            var cnts = new long[30];
            for(int i = 0; i < 30; i++)
            {
                Array.Sort(aMods[i]);
                Array.Reverse(aMods[i]);
                Array.Sort(bMods[i]);
                int t = 1 << i;
                for(int j = 0; j < n; j++)
                {

                    cnts[i] += BinarySearch(bMods[i], t * 2 - aMods[i][j]);
                    cnts[i] -= BinarySearch(bMods[i], t - aMods[i][j]);
                    cnts[i] += BinarySearch(bMods[i], t * 3 - aMods[i][j]);
                    cnts[i] -= BinarySearch(bMods[i], t * 4 - aMods[i][j]);
                    //Console.Write(cnts[i] + " ");
                }
                //Console.WriteLine();
            }
            long res = 0;
            for (int i = 0; i < 30; i++)
            {
                //Console.WriteLine(cnts[i]);
                if (cnts[i] % 2 > 0) res += 1 << i;
            }
            Console.WriteLine(res);
        }

        static int BinarySearch(int[] array,int val)
        {
            int lower = 0;
            int upper = array.Length;
            while (lower < upper)
            {
                int mid = (lower + upper) / 2;
                if (array[mid] < val)
                {
                    lower = mid + 1;
                }
                else
                {
                    upper=mid;
                }
            }
            return lower;
        }

