public static class BinarySearch
{
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int LowerBound(int[] array, int key)
	{
		int len = array.Length;
		if(array[len - 1] < key)
			return -1;

		int left = 0;
		int right = len - 1;
		while(right > left)
		{
			int mid = (left + right) / 2;
			if(array[mid] >= key)
				right = mid;
			else
				left = mid + 1;
		}

		return left;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int UpperBound(int[] array, int key)
	{
		int len = array.Length;
		if(array[len - 1] <= key)
			return len;

		int left = 0;
		int right = len - 1;
		while(right > left)
		{
			int mid = (left + right) / 2;
			if(array[mid] > key)						
				right = mid;
			else			
				left = mid + 1;	
		}

		return left;
	}
}


