public static class BinarySearch
{
	public static int LowerBound<T>(T[] array, T key, Comparison<T> comp)
	{
		int len = array.Length;
		if(comp(array[len - 1], key) < 0)
			return -1;

		int left = 0;
		int right = len - 1;
		while(right > left)
		{
			int mid = (left + right) / 2;
			if(comp(array[mid], key) >= 0)
				right = mid;
			else
				left = mid + 1;
		}

		return left;
	}

	public static int UpperBound<T>(T[] array, T key, Comparison<T> comp)
	{
		int len = array.Length;
		if(comp(array[len - 1], key) <= 0)
			return len;

		int left = 0;
		int right = len - 1;
		while(right > left)
		{
			int mid = (left + right) / 2;
			if(comp(array[mid], key) > 0)						
				right = mid;
			else			
				left = mid + 1;	
		}

		return left;
	}
}


