			// 最上位ビットから調べる
			for (int k = 28; k >= 0; k--) {
				var mask = (1 << k + 1) - 1;
				for (int i = 0; i < N; i++) {
					As[i] &= mask;
					Bs[i] &= mask;
				}
				Array.Sort(As);
				//Array.Reverse(As);
