				//   T以上、2T以上、3T以上
				// となる Bの範囲 をしゃくとり的に調べる
				var t = 1 << k;
				int dnum = 0;
				int b1 = 0, b2 = 0, b3 = 0;
				for (int i = N - 1; i >= 0; i--) {
					var a = As[i];
					b1 = Incr(Bs, b1, t - a);
					//ReplaceIfBigger(ref b2, b1);
					b2 = Incr(Bs, b2, t * 2 - a);
					//ReplaceIfBigger(ref b3, b2);
					b3 = Incr(Bs, b3, t * 3 - a);

					//dnum += (N - b3) + (N - b1) - (N - b2);
					dnum += N - b3 - b1 + b2;
				}

