using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace ConsoleApp3
{
    class Program
    {

        public static List<int> ReadIntList()
        {
            return Console.ReadLine().Split(' ').Select(int.Parse).ToList<int>();
        }

        public static int ReadInt()
        {
            return Convert.ToInt32(Console.ReadLine());
        }

        static void Main(string[] args)
        {
            var N = ReadInt();
            var A = ReadIntList();
            var B = ReadIntList();
            var res = 0;

            for (int i = 5; i >= 0; i--)
            {
                var n = 1 << i;
                var m = n << 1;
                var mask = m - 1;

                //n-bit以下にカットして並び替える
                for (int k = 0; k < B.Count; k++)
                    B[k] &= mask;
                B.Sort();

                for (int k = 0; k < A.Count; k++)
                {
                    var val = A[k] & mask;

                    //繰り上がりしてnbit目が1になる位置
                    var noUpCnt = B.BinarySearch(n - val);
                    if (noUpCnt < 0)
                        noUpCnt = ~noUpCnt;
                    else
                        while (noUpCnt > 0 && B[noUpCnt - 1] == n - val)
                            noUpCnt--;
                    //繰り上がりしてnbit目が0になる位置
                    var upCnt = B.BinarySearch(m - val);
                    if (upCnt < 0)
                        upCnt = ~upCnt;
                    else
                        while (upCnt > 0 && B[upCnt - 1] == m - val)
                            upCnt--;

                    //繰り上がりしてもnbit目に1が残る位置
                    var remCnt = B.BinarySearch(n + m - val);
                    if (remCnt < 0)
                        remCnt = ~remCnt;
                    else
                        while (remCnt > 0 && B[remCnt - 1] == n + m - val)
                            remCnt--;

                    //nbit目が「1」の数
                    var cnt1 = upCnt - noUpCnt;
                    cnt1 += (B.Count - remCnt);

                    res ^= (cnt1 & 1) << i;
                }
            }

            Console.WriteLine(res);
        }




    }
}

