using System;
using System.Linq;

class D
{
	static void Main()
	{
		var p2 = Enumerable.Range(0, 30).Select(i => (int)Math.Pow(2, i)).ToArray();
		var n = int.Parse(Console.ReadLine());
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var a = read();
		var b = read();

		var r = 0;
		for (int k = 0; k <= 28; k++)
		{
			var mask = p2[k + 1] - 1;
			var a2 = Array.ConvertAll(a, x => x & mask);
			var b2 = Array.ConvertAll(b, x => x & mask);
			Array.Sort(b2);

			var c = 0;
			for (int v, i = 0; i < n; i++)
			{
				var j1 = SearchGeq(b2, v = p2[k] - a2[i]);
				var j2 = SearchGeq(b2, v += p2[k]);
				var j3 = SearchGeq(b2, v += p2[k]);
				c ^= j2 - j1 + n - j3;
			}
			if (c % 2 == 1) r |= p2[k];
		}
		Console.WriteLine(r);
	}

	static int SearchGeq(int[] a, int v)
	{
		int l = 0, r = a.Length, m;
		while (l < r) if (a[m = l + (r - l - 1) / 2] >= v) r = m; else l = m + 1;
		return r;
	}
}

