			for (int k = 28; k >= 0; k--) {
				var mask = (1 << k + 1) - 1;
				for (int i = 0; i < N; i++) {
					As[i] &= mask;
					Bs[i] &= mask;
				}
				Array.Sort(Bs);
				Dump(As);
				Dump(Bs);

				// Aごとに +B との和が
				//   T以上、2T以上、3T以上
				// となる Bの範囲 を2分探索で調べる
				var t = 1 << k;
				int dnum = 0;
				for (int i = 0; i < N; i++) {
					var a = As[i];
					var b1 = BinarySearch(Bs, t - a);
					var b2 = BinarySearch(Bs, b1 - 1, N, t * 2 - a);
					var b3 = BinarySearch(Bs, b2 - 1, N, t * 3 - a);

					//dnum += (N - b3) + (N - b1) - (N - b2);
					dnum += N - b3 - b1 + b2;
				}

				if (dnum % 2 == 1) {
					ans |= (1U << k);
				}
			}
			WriteLine(ans);
		}

