public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		long[] a = Enumerable.Range(0, N).Select(_ => GetLong()).ToArray();
		long[] b = Enumerable.Range(0, N).Select(_ => GetLong()).ToArray();

		int xor = 0;
		Comparison<long> comp = (x, y) => x.CompareTo(y);
		for(int k = 0; k < 28; k++)
		{
			long T = 1L << k;
			long TT = T << 1;
			long TTT = T + TT;
			long TTTT = TT + TT;

			long[] bMod = b.Select(x => x % TT).ToArray();
			Array.Sort(bMod);

			int cnt = 0;
			for(int i = 0; i < N; i++)
			{
				long aMod = a[i] % TT;

				int lb1 = LowerBound(bMod, T - aMod, comp);
				int ub1 = UpperBound(bMod, TT - aMod - 1, comp);
				if(lb1 != -1)
					cnt += ub1 - lb1;

				int lb2 = LowerBound(bMod, TTT - aMod, comp);
				int ub2 = UpperBound(bMod, TTTT - aMod - 1, comp);
				if(lb2 != -1)
					cnt += ub2 - lb2;
			}

			xor |= (cnt % 2) << k;
		}

		Console.WriteLine(xor);
	}
}


public static class BinarySearch
{
	public static int LowerBound<T>(T[] array, T key, Comparison<T> comp)
	{
		int len = array.Length;
		if(comp(array[len - 1], key) < 0)
			return -1;

		int left = 0;
		int right = len - 1;
		while(right > left)
		{
			int mid = (left + right) / 2;
			if(comp(array[mid], key) >= 0)
				right = mid;
			else
				left = mid + 1;
		}

		return left;
	}

	public static int UpperBound<T>(T[] array, T key, Comparison<T> comp)
	{
		int len = array.Length;
		if(comp(array[len - 1], key) <= 0)
			return len;

		int left = 0;
		int right = len - 1;
		while(right > left)
		{
			int mid = (left + right) / 2;
			if(comp(array[mid], key) > 0)						
				right = mid;
			else			
				left = mid + 1;	
		}

		return left;
	}
}


