namespace ConsoleApp3
{
    class Program
    {

        public static List<T> ReadList<T>(Func<string, T> f)
        {
            return Console.ReadLine().Split(' ').Select(f).ToList();
        }

        public static int ReadInt()
        {
            return Convert.ToInt32(Console.ReadLine());
        }

        static void Main(string[] args)
        {
            var N = ReadInt();
            var A = ReadList(s => int.Parse(s) << 1);
            var B = ReadList(s => int.Parse(s) << 1);
            var res = 0;

            A = SortBitReverse(A);
            B.Sort();

            for (int i = 30; i > 0; i--)
            {
                var n = 1 << i;
                var m = n << 1;
                //var mask = m - 1;

                //n-bit以下にカットして並び替える
                B = SortMMD(B, i);
                A = MaskDistinct(A, i);

                for (int k = 0; k < A.Count; k++)
                {
                    var val = A[k];

                    //繰り上がりしてnbit目が1になる位置
                    var noUpCnt = B.BinarySearch(n - val - 1);
                    noUpCnt = ~noUpCnt;

                    //繰り上がりしてnbit目が0になる位置
                    var upCnt = B.BinarySearch(m - val - 1);
                    upCnt = ~upCnt;

                    //繰り上がりしてもnbit目に1が残る位置
                    var remCnt = B.BinarySearch(n + m - val - 1);
                    remCnt = ~remCnt;

                    //nbit目が「1」の数
                    var cnt1 = upCnt - noUpCnt;
                    cnt1 += (B.Count - remCnt);

                    res ^= (cnt1 & 1) << i;
                }
            }

            res >>= 1;
            Console.WriteLine(res);
        }

        static List<int> SortMMD(List<int> lst, int nbit)
        {
            if (lst.Count == 0)
                return lst;

            var mp = (1 << (nbit + 1));
            var flg = 0;
            while (flg < lst.Count && lst[flg] < mp)
                flg++;

            //n-bit以下にカットして並び替える
            var mask = mp - 1;
            for (int k = 0; k < lst.Count; k++)
                lst[k] &= mask;

            var res = new List<int>(lst.Count);

            //マージする。2つ々数が続いた場合は削除
            int n = 0, m = flg;
            while (n < m && m < lst.Count)
            {
                if (lst[n] < lst[m])
                    res.Add(lst[n++]);
                else
                    res.Add(lst[m++]);
            }
            while (n < flg)
                res.Add(lst[n++]);
            while (m < lst.Count)
                res.Add(lst[m++]);
            return res;
        }

        static List<int> MaskDistinct(List<int> lst, int nbit)
        {
            if (lst.Count == 0)
                return lst;

            var mask = (1 << (nbit + 1)) - 1;
            var res = new List<int>(lst.Count);
            res.Add(lst[0] & mask);
            for (int i = 1; i < lst.Count; i++)
            {
                int val = lst[i] & mask;
                if (res.Count == 0 || res[res.Count - 1] != val)
                    res.Add(val);
                else
                    res.RemoveAt(res.Count - 1);
            }

            return res;
        }

        static List<int> SortBitReverse(List<int> lst)
        {
            var revTbl4 = new int[0xF + 1] { 0, 8, 4, 12, 2, 10, 6, 14, 1, 9, 5, 13, 3, 11, 7, 15 };
            var revTbl8 = new int[0xFF + 1];
            for (int i = 0; i <= 0xFF; i++)
                revTbl8[i] = (revTbl4[i & 0xf] << 4) | revTbl4[i >> 4];

            for (int i = 0; i < lst.Count; i++)
            {
                var val = lst[i];
                lst[i] = (revTbl8[val & 0xFF] << 24)
                    | (revTbl8[(val >> 8) & 0xFF] << 16)
                    | (revTbl8[(val >> 16) & 0xFF] << 8)
                    | (revTbl8[val >> 24]);
            }

            lst.Sort();

            for (int i = 0; i < lst.Count; i++)
            {
                var val = lst[i];
                lst[i] = (revTbl8[val & 0xFF] << 24)
                    | (revTbl8[(val >> 8) & 0xFF] << 16)
                    | (revTbl8[(val >> 16) & 0xFF] << 8)
                    | (revTbl8[val >> 24]);
            }

            return lst;
        }

    }
}

