        public bool[] Used;

        public void Run()
        {
            {
                N = Input.ReadInt();
                A = Input.ReadIntArray();
                B = Input.ReadIntArray();
            }

            long ret = 0;
            int mask = 1 << 29;
            while (mask > 0)
            {
                // Console.Error.WriteLine($"mask:{mask}");

                var A0 = new List<int>();
                var A1 = new List<int>();
                var B0 = new List<int>();
                var B1 = new List<int>();

                for (int i = 0; i < N; i++)
                {
                    if ((A[i] & mask) == mask)
                    {
                        A0.Add(A[i] & (mask - 1));
                    }
                    else
                    {
                        A1.Add(A[i] & (mask - 1));
                    }

                    if ((B[i] & mask) == mask)
                    {
                        B0.Add(B[i] & (mask - 1));
                    }
                    else
                    {
                        B1.Add(B[i] & (mask - 1));
                    }

                }

                A0.Sort();
                A1.Sort();
                B0.Sort();
                B1.Sort();

                var b0 = B0.ToArray();
                var b1 = B1.ToArray();

                long count = 0;

                for (int i = 0; i < A0.Count; i++)
                {
                    count += BinarySearch.PassCount(mask - A0[i], b0);
                    count += BinarySearch.DownCount(mask - A0[i], b1);
                }

                for (int i = 0; i < A1.Count; i++)
                {
                    count += BinarySearch.DownCount(mask - A1[i], b0);
                    count += BinarySearch.PassCount(mask - A1[i], b1);
                }

                if (count % 2 == 1) ret += mask;

                mask /= 2;
            }

            Console.WriteLine(ret);
        }
    }

    // libs ----------
    internal class BinarySearch
    {
        public int[] S;
        public int N { get { return S.Length; } }

        public static int PassCount(int x, int[] B)
        {
            if (B.Length == 0) return 0;
            var bs = new BinarySearch(B);
            int idx = bs.Search(x);
            int ret = B.Length - idx;
            // Console.WriteLine($"Pass: {ret} x:{x} B:[{string.Join(",", B)}]");
            return ret;
        }

        public static int DownCount(int x, int[] B)
        {
            if (B.Length == 0) return 0;
            var bs = new BinarySearch(B);
            int idx = bs.Search(x);
            int ret =  idx;
            // Console.WriteLine($"Down: {ret}  x:{x} B:[{string.Join(",", B)}]");
            return ret;
        }

        public BinarySearch(int[] s)
        {
            S = s;
        }

        // 左側がfalse, 右側がtrueである必要がある
        public bool Cond(int i, int x)
        {
            if (S[i] >= x) return true;
            return false;
        }

        // 初めてCondがtrueを返すindexを返す
        // 全て条件を満たさない場合はNを返す
        public int Search(int x)
        {
            int left = 0;
            int right = N;

            if (Cond(0, x)) return 0;
            if (!Cond(N - 1, x)) return N;

            while (left + 1 < right)
            {
                int mid = (left + right) / 2;
                if (!Cond(mid, x))
                {
                    left = mid;
                }
                else
                {
                    right = mid;
                }
            }
            return right;
        }
    }

