            for (int i = 0; i < 30; i++)
            {
                aMods[i] = new int[n];
                bMods[i] = new int[n];
                int div = 2 << i;
                for(int j = 0; j < n; j++)
                {
                    aMods[i][j] = array[j] % div;
                    bMods[i][j] = bArray[j] % div;
                }
            }
            int[] cntTest = new int[30];
            for(int i = 0; i < n; i++)
            {
                for(int j = 0; j < n; j++)
                {
                    int ab = array[i] + bArray[j];
                    for(int k = 0; k < 30; k++)
                    {
                        if ((ab & (1 << k)) > 0) cntTest[k]++;
                    }
                }
            }
            //for (int i = 0; i < 30; i++) Console.WriteLine(cntTest[i]);

            var cnts = new long[30];
            for(int i = 0; i < 30; i++)
            {
                Array.Sort(aMods[i]);
