public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr;

    public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        var N = cr.Int;
        var arr = cr.Repeat(N).Int;
        var brr = cr.Repeat(N).Int;
        int res = 0;
        var crr = new int[N];
        for (int k = 28; k >= 0; k--)
        {
            var t = 1 << k;
            var mask = (t << 1) - 1;
            for (int i = 0; i < brr.Length; i++)
                crr[i] = brr[i] & mask;
            crr.Sort();
            var cnt = 0;
            foreach (var ao in arr)
            {
                var a = ao & mask;
                int ta1 = t - a, ta2 = 2 * t - a, ta3 = 3 * t - a, ta4 = 4 * t - a;
                int t1, t2 = crr.Length, t3, t4;
                int ng = 0;
                if (ta2 <= crr[ng]) t2 = ng;
                while (t2 - ng > 1)
                {
                    var mm = (t2 + ng) >> 1;
                    if (ta2 <= crr[mm]) t2 = mm;
                    else ng = mm;
                }

                t1 = t2;
                ng = 0;
                if (ta1 <= crr[ng]) t1 = ng;
                while (t1 - ng > 1)
                {
                    var mm = (t1 + ng) >> 1;
                    if (ta1 <= crr[mm]) t1 = mm;
                    else ng = mm;
                }

                t3 = crr.Length;
                ng = t2;
                if (ta3 <= crr[ng]) t3 = ng;
                while (t3 - ng > 1)
                {
                    var mm = (t3 + ng) >> 1;
                    if (ta3 <= crr[mm]) t3 = mm;
                    else ng = mm;
                }

                t4 = crr.Length;
                ng = t3;
                if (ta4 <= crr[ng]) t4 = ng;
                while (t4 - ng > 1)
                {
                    var mm = (t4 + ng) >> 1;
                    if (ta4 <= crr[mm]) t4 = mm;
                    else ng = mm;
                }

                cnt += t4 - t3 + t2 - t1;
            }
            res |= (cnt & 1) << k;
        }
        return res;
    }
}

using System;
using System.Linq;

class D
{
	static void Main()
	{
		var p2 = Enumerable.Range(0, 30).Select(i => (int)Math.Pow(2, i)).ToArray();
		var n = int.Parse(Console.ReadLine());
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var a = read();
		var b = read();

		var r = 0;
		for (int k = 0; k <= 28; k++)
		{
			var f = p2[k + 1] - 1;
			var a2 = Mask(a, f);
			var b2 = Mask(b, f);
			Array.Sort(b2);

			var c = 0;
			for (int v, i = 0; i < n; i++)
			{
				var j1 = SearchGeq(b2, v = p2[k] - a2[i]);
				var j2 = SearchGeq(b2, v += p2[k]);
				var j3 = SearchGeq(b2, v += p2[k]);
				c ^= j2 - j1 + n - j3;
			}
			if (c % 2 == 1) r |= p2[k];
		}
		Console.WriteLine(r);
	}

	static int[] Mask(int[] a, int f)
	{
		var r = new int[a.Length];
		for (int i = 0; i < a.Length; i++) r[i] = a[i] & f;
		return r;
	}

	static int SearchGeq(int[] a, int v)
	{
		int l = 0, r = a.Length, m;
		while (l < r) if (a[m = (l + r - 1) / 2] >= v) r = m; else l = m + 1;
		return r;
	}
}

