namespace ABC091D
{
    class Program
    {
        static void Main(string[] args)
        {
            var N = ReadInt;

            var a = ReadInts;
            var b = ReadInts;

            int ans = 0;
            for (int i = 0; i < 28; i++) // 各桁
            {
                int count = 0;
                int mod = 1 << (i + 1);
                int[] amod = a.Select(x => x % mod).ToArray();
                int[] bmod = new int[N];
                for (int k = 0; k < N; k++)
                {
                    bmod[k] = b[k] % mod;
                }
                Array.Sort(bmod);

                for (int j = 0; j < N; j++)
                {
                    int min1 = (1 << (i)) - amod[j];
                    int min2 = (3 * (1 << (i))) - amod[j];
                    int max1 = (1 << (i + 1)) - amod[j];
                    int max2 = (1 << (i + 2)) - amod[j];

                    int c1 = UpperBound(bmod, max1 - 1) - LowerBound(bmod, min1);
                    int c2 = UpperBound(bmod, max2 - 1) - LowerBound(bmod, min2);
                    count += c1 + c2;
                }

                ans += ((count % 2) << (i));
            }

            Console.WriteLine(ans);
        }



        /// <summary>
        /// 二分探索 key以上の最低
        /// </summary>
        /// <typeparam name="T"></typeparam>
        /// <param name="a"></param>
        /// <param name="v"></param>
        /// <returns></returns>
        public static int LowerBound<T>(T[] a, T v)
        {
            return LowerBound(a, v, Comparer<T>.Default);
        }

        public static int LowerBound<T>(T[] a, T v, Comparer<T> cmp)
        {
            var l = 0;
            var r = a.Length - 1;
            while (l <= r)
            {
                var mid = l + (r - l) / 2;
                var res = cmp.Compare(a[mid], v);
                if (res == -1) l = mid + 1;
                else r = mid - 1;
            }
            return l;
        }

        /// <summary>
        /// 二分探索 keyより大きい最低
        /// </summary>
        /// <typeparam name="T"></typeparam>
        /// <param name="a"></param>
        /// <param name="v"></param>
        /// <returns></returns>
        public static int UpperBound<T>(T[] a, T v)
        {
            return UpperBound(a, v, Comparer<T>.Default);
        }

        public static int UpperBound<T>(T[] a, T v, Comparer<T> cmp)
        {
            var l = 0;
            var r = a.Length - 1;
            while (l <= r)
            {
                var mid = l + (r - l) / 2;
                var res = cmp.Compare(a[mid], v);
                if (res <= 0) l = mid + 1;
                else r = mid - 1;
            }
            return l;
        }
    }


