        var a = Console.ReadLine().Split().Select(int.Parse).ToArray();
        var b = Console.ReadLine().Split().Select(int.Parse).ToArray();
        long res = 0;
        for (int i = 0; i < 29; i++)
        {
            long totalCount = 0;
            int lessInd1 = -1;
            int moreInd1 = -1;
            int moreInd2 = -1;
            var mask = ((1 << i + 1) - 1);
            var orderedAUntil = a.Select(x => x & mask).OrderByDescending(x => x).ToArray();
            var orderedBUntil = b.Select(x => x & mask).OrderBy(x => x).ToArray();
            for (int j = 0; j < orderedBUntil.Length; j++)
            {
