namespace Competitive
{
    internal class Solution
    {
        public int N;
        public int[] A, B;
        public bool[] Used;

        public void Run()
        {
            {
                N = Input.ReadInt();
                A = Input.ReadIntArray();
                B = Input.ReadIntArray();
            }

            long ret = 0;
            int mask = 1 << 29;

            var A0 = new int[N];
            var A1 = new int[N];
            var B0 = new int[N];
            var B1 = new int[N];

            while (mask > 0)
            {
                int a0 = 0;
                int a1 = 0;
                int b0 = 0;
                int b1 = 0;

                // Console.Error.WriteLine($"mask:{mask}");

                for (int i = 0; i < N; i++)
                {
                    if ((A[i] & mask) == mask)
                    {
                        A0[a0] = A[i] & (mask - 1);
                        a0++;
                    }
                    else
                    {
                        A1[a1] = A[i] & (mask - 1);
                        a1++;
                    }

                    if ((B[i] & mask) == mask)
                    {
                        B0[b0] = B[i] & (mask - 1);
                        b0++;
                    }
                    else
                    {
                        B1[b1] = B[i] & (mask - 1);
                        b1++;
                    }

                }

                Array.Sort(A0, 0, a0);
                Array.Sort(A1, 0, a1);
                Array.Sort(B0, 0, b0);
                Array.Sort(B1, 0, b1);

                long count = 0;

                for (int i = 0; i < a0; i++)
                {
                    count += BinarySearch.PassCount(mask - A0[i], B0, b0);
                    count += BinarySearch.DownCount(mask - A0[i], B1, b1);
                }

                for (int i = 0; i < a1; i++)
                {
                    count += BinarySearch.DownCount(mask - A1[i], B0, b0);
                    count += BinarySearch.PassCount(mask - A1[i], B1, b1);
                }

                if (count % 2 == 1) ret += mask;

                mask /= 2;
            }

            Console.WriteLine(ret);
        }
    }

    // libs ----------
    internal class BinarySearch
    {
        public int[] S;
        public int N;

        public static int PassCount(int x, int[] B, int N)
        {
            if (N == 0) return 0;
            var bs = new BinarySearch(B);
            bs.N = N;
            int idx = bs.Search(x);
            int ret = B.Length - idx;
            // Console.WriteLine($"Pass: {ret} x:{x} B:[{string.Join(",", B)}]");
            return ret;
        }

        public static int DownCount(int x, int[] B, int N)
        {
            if (N == 0) return 0;
            var bs = new BinarySearch(B);
            bs.N = N;
            int idx = bs.Search(x);
            int ret =  idx;
            // Console.WriteLine($"Down: {ret}  x:{x} B:[{string.Join(",", B)}]");
            return ret;
        }

        public BinarySearch(int[] s)
        {
            S = s;
        }

        // 左側がfalse, 右側がtrueである必要がある
        public bool Cond(int i, int x)
        {
            if (S[i] >= x) return true;
            return false;
        }

        // 初めてCondがtrueを返すindexを返す
        // 全て条件を満たさない場合はNを返す
        public int Search(int x)
        {
            int left = 0;
            int right = N;

            if (Cond(0, x)) return 0;
            if (!Cond(N - 1, x)) return N;

            while (left + 1 < right)
            {
                int mid = (left + right) / 2;
                if (!Cond(mid, x))
                {
                    left = mid;
                }
                else
                {
                    right = mid;
                }
            }
            return right;
        }
    }

