class D
{
	static void Main()
	{
		var p2 = Pow2_32(29);
		var n = int.Parse(Console.ReadLine());
		Func<int[]> read = () => Console.ReadLine().Split().Select(int.Parse).ToArray();
		var a = read();
		var b = read();

		var r = 0;
		for (int k = 0; k <= 28; k++)
		{
			var f = p2[k + 1] - 1;
			var a2 = Mask(a, f);
			var b2 = Mask(b, f);
			HeapSort(b2);

			int c = 0, v;
			for (int i = 0; i < n; i++)
			{
				var j1 = SearchGeq(b2, v = p2[k] - a2[i]);
				var j2 = SearchGeq(b2, v += p2[k]);
				var j3 = SearchGeq(b2, v += p2[k]);
				c ^= j2 - j1 + n - j3;
			}
			if (c % 2 == 1) r |= p2[k];
		}
		Console.WriteLine(r);
	}

	static int[] Mask(int[] a, int f)
	{
		var r = new int[a.Length];
		for (int i = 0; i < a.Length; i++) r[i] = a[i] & f;
		return r;
	}

	static int[] Pow2_32(int n)
	{
		var p = new int[n + 1];
		p[0] = 1;
		for (int i = 0; i < n; i++) p[i + 1] = p[i] * 2;
		return p;
	}

	static int SearchGeq(int[] a, int v)
	{
		int l = 0, r = a.Length, m;
		while (l < r) if (a[m = (l + r - 1) / 2] >= v) r = m; else l = m + 1;
		return r;
	}

	static void HeapSort(int[] a)
	{
		var heap = new BinaryHeap<int>(a, (x, y) => y - x);
		for (int i = 1; i < a.Length; i++)
		{
			heap.UpHeap(i);
		}
		for (int i = a.Length - 1; i > 0; i--)
		{
			heap.Swap(0, i);
			heap.DownHeap(0, i);
		}
	}
}

struct BinaryHeap<T>
{
	T[] a;
	Comparison<T> c;
	public T First => a[0];

	public BinaryHeap(T[] _a, Comparison<T> _c = null)
	{
		a = _a;
		c = _c ?? Comparer<T>.Default.Compare;
	}

	public void Swap(int i, int j) { var o = a[i]; a[i] = a[j]; a[j] = o; }
	public void UpHeap(int i) { for (int j; i > 0 && c(a[j = (i - 1) / 2], a[i]) > 0; Swap(i, j), i = j) ; }
	public void DownHeap(int i, int count)
	{
		for (int j; (j = 2 * i + 1) < count; i = j)
		{
			if (j + 1 < count && c(a[j], a[j + 1]) > 0) j++;
			if (c(a[i], a[j]) > 0) Swap(i, j); else break;
		}
	}
}

