	var res int
	for bit, t := 1, 2; bit < 28; bit, t = bit+1, t*2 {
		a, b := make([]int, n), make([]int, n)
		for i := range a {
			a[i], b[i] = tmpa[i]%(2*t), tmpb[i]%(2*t)
		}
		sort.Ints(b)

		c := 0
		for _, aa := range a {
			c1 := sort.SearchInts(b, t-aa)
			c2 := sort.SearchInts(b, 2*t-aa)
			c3 := sort.SearchInts(b, 3*t-aa)
			c4 := sort.SearchInts(b, 4*t-aa)
			cc := 0
			if c1 < len(b) && c2 <= len(b) {
				c += len(b[c1:c2]) % 2
			}
			if c3 < len(b) && c4 <= len(b) {
				c += len(b[c3:c4]) % 2
			}
			c += cc % 2
		}

		res += (c % 2) * t
	}

	fmt.Println(res)
}

