	s := &Scanner{bufio.NewScanner(r)}
	s.sc.Split(bufio.ScanWords)
	return s
}

func (s *Scanner) ScanInt() int {
	s.sc.Scan()
	i, e := strconv.Atoi(s.sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

func (s *Scanner) ScanInts(len int) []int {
	a := make([]int, len)
	for i := 0; i < len; i++ {
		a[i] = s.ScanInt()
	}
	return a
}

