	return i
}

func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)

	aa := make([]int, n)
	bb := make([]int, n)
	ma := make([]int, n)
	mb := make([]int, n)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
	}
	for i := 0; i < n; i++ {
		bb[i] = getNextInt(scanner)
	}

	ans := 0

	for i := 0; i < 30; i++ {
		mapmod(i, n, aa, ma)
		mapmod(i, n, bb, mb)

		sort.Ints(mb)
		t := 1 << uint(i)

		c := 0
		for ii := 0; ii < n; ii++ {
			t1 := search(ma[ii], 0, n, t, mb)
			t2 := search(ma[ii], t1, n, t*2, mb)
			t3 := search(ma[ii], t2, n, t*3, mb)
			c += n - t3 + t2 - t1
		}
		c %= 2
		ans |= c << uint(i)
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

func mapmod(k, n int, aa, mm []int) {
	for i := 0; i < n; i++ {
		mm[i] = aa[i] % (2 << uint(k))
	}
}

func search(a, l, r, t int, mb []int) int {
	for l < r {
		m := (l + r) >> 1
		if a+mb[m] >= t {
			r = m
			continue
		}
		l = m + 1
	}
	return l
}

