	ans := 0
	// 全ビットについて求める
	for i := 0; i <= 29; i++ {
		T := PowInt(2, i)
		// A, Bの2*Tのあまりの別スライスを作る
		AA := make([]int, n)
		BB := make([]int, n)
		for j := 0; j < n; j++ {
			AA[j] = A[j] % (2 * T)
			BB[j] = B[j] % (2 * T)
		}
		sort.Sort(sort.IntSlice(BB))

		// aiを固定
		onBitNum := 0
		for j := 0; j < n; j++ {
			a := AA[j]
			lb := LowerBound(BB, T-a)
			ub := UpperBound(BB, 2*T-a-1)
			onBitNum += ub - lb + 1
			lb = LowerBound(BB, 3*T-a)
			ub = UpperBound(BB, 4*T-a-1)
			onBitNum += ub - lb + 1
		}
		if onBitNum%2 == 1 {
