func mapmod(k, n int, aa, mm []int) {
	for i := 0; i < n; i++ {
		mm[i] = aa[i] % (2 << uint(k))
	}
}

func bsearch(a, n, t int, mb []int) int {
	l := 0
	r := n
	for l < r {
		m := (l + r) >> 1
		if a+mb[m] >= t {
			r = m
			continue
		}
		l = m + 1
	}
	return l
}

