var sc = NewScanner(os.Stdin)

func main() {
	n := sc.ScanInt()
	tmpa := sc.ScanBigInts(n)
	tmpb := sc.ScanBigInts(n)

	var res, t int64
	var bit int
	for bit, t = 1, 2; bit < 28; bit, t = bit+1, t*2 {
		a, b := make(BigInts, n), make(BigInts, n)
		for i := range a {
			a[i], b[i] = tmpa[i]%(int64(2)*t), tmpb[i]%(2*t)
		}
		sort.Sort(b)

		c := 0
		for _, aa := range a {
			c1 := SearchBigInts(b, t-aa)
			c2 := SearchBigInts(b, 2*t-aa)
			c3 := SearchBigInts(b, 3*t-aa)
			c4 := SearchBigInts(b, 4*t-aa)
			cc := 0
			if c1 < len(b) && c2 <= len(b) {
				c += len(b[c1:c2]) % 2
			}
			if c3 < len(b) && c4 <= len(b) {
				c += len(b[c3:c4]) % 2
			}
			c += cc % 2
		}

		res += int64(c%2) * t
	}

	fmt.Println(res)
}

func SearchBigInts(a []int64, x int64) int {
	return sort.Search(len(a), func(i int) bool { return a[i] >= x })
}

