	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(os.Stdout)

	n := getNextInt(scanner)

	chokudai := Chokudai{}

	chokudai.aa = make([]int, n)
	chokudai.bb = make([]int, n)
	chokudai.ma = make([]int, n)
	chokudai.mb = make([]int, n)
	for i := 0; i < n; i++ {
