	}
	for i := 0; i < n; i++ {
		chokudai.bb[i] = getNextInt(scanner)
	}

	ans := 0

	for i := 0; i < 30; i++ {
		chokudai.mapmod(i, n)

		sort.Ints(chokudai.mb)
		t := 1 << uint(i)

		c := 0
		for ii := 0; ii < n; ii++ {
			t1 := chokudai.search(chokudai.ma[ii], 0, n, t)
			t2 := chokudai.search(chokudai.ma[ii], t1, n, t*2)
			t3 := chokudai.search(chokudai.ma[ii], t2, n, t*3)
			c += n - t3 + t2 - t1
		}
		c %= 2
		ans |= c << uint(i)
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
}

type Chokudai struct {
	aa, bb, ma, mb []int
}

func (chokudai *Chokudai) mapmod(k, n int) {
	for i := 0; i < n; i++ {
		chokudai.ma[i] = chokudai.aa[i] % (2 << uint(k))
		chokudai.mb[i] = chokudai.bb[i] % (2 << uint(k))
	}
}

func (chokudai *Chokudai) search(a, l, r, t int) int {
	for l < r {
		m := (l + r) >> 1
		if a+chokudai.mb[m] >= t {
			r = m
			continue
		}
		l = m + 1
	}
	return l
}

