var AB []int

func main() {

	fmt.Scanf("%d", &N)

	A = make([]int, N)
	B = make([]int, N)

	for i := 0; i < N; i++ {
		fmt.Scanf("%d", &A[i])
	}

	for i := 0; i < N; i++ {
		fmt.Scanf("%d", &B[i])
	}

	AB = make([]int, N*N)

	for i := 0; i < N; i++ {
		for j := 0; j < N; j++ {
			AB[N*i+j] = A[i] + B[j]
		}
	}

	ans := 0
	index := 0
	for i := 0; i < N*N; i++ {
		if ans < AB[i] {
			index = i
		}
		ans = Max(ans, AB[i])
	}

	for i := 0; i < N*N; i++ {
		if i == index {
			continue
		}
		ans ^= AB[i]
	}

	fmt.Println(ans)
}

func Max(x, y int) int {
	if x > y {
		return x
	}
	return y
}

