	}

	ans := 0

	ms := MergeSort{}
	ms.init(n)

	for i := 0; i < 30; i++ {
		t := 1 << uint(i)
		for ii := 0; ii < n; ii++ {
			mb[ii] = bb[ii] % (t << 1)
		}
		ms.sort(0, n, mb)

		c := 0
		for ii := 0; ii < n; ii++ {
			c += n
			l := 0
			ma := aa[ii] % (t << 1)
			for iii := 1; iii <= 3; iii++ {
				r := n
				v := t*iii - ma
				for l < r {
					m := (l + r) >> 1
					if mb[m] >= v {
						r = m
						continue
					}
					l = m + 1
				}
				if iii%2 == 1 {
					c -= l
					continue
				}
				c += l
			}
		}
		c %= 2
		ans |= c << uint(i)
	}

	fmt.Fprintln(writer, ans)

	writer.Flush()
}

func bsearch(a, n, t int, mb []int) int {
	l := 0
	r := n
	for l < r {
		m := (l + r) >> 1
		if a+mb[m] >= t {
			r = m
			continue
		}
		l = m + 1
	}
	return l
}

type MergeSort struct {
	n      int
	ll, rr []int
}

func (ms *MergeSort) init(n int) {
	ms.n = n
	ms.ll = make([]int, n/2+2)
	ms.rr = make([]int, n/2+2)
}

func (ms *MergeSort) sort(l, r int, aa []int) {
	if l+1 < r {
		m := (l + r) >> 1
		ms.sort(l, m, aa)
		ms.sort(m, r, aa)
	}
	ms.merge(l, r, aa)
}

func (ms *MergeSort) merge(l, r int, aa []int) {
	ll := ms.ll
	rr := ms.rr
	m := (l + r) >> 1
	for i := l; i < m; i++ {
		ll[i-l] = aa[i]
	}
	for i := m; i < r; i++ {
		rr[i-m] = aa[i]
	}

	ll[m-l] = 1 << 30
	rr[r-m] = 1 << 30
	lpos := 0
	rpos := 0
	for i := l; i < r; i++ {
		if ll[lpos] <= rr[rpos] {
			aa[i] = ll[lpos]
			lpos++
			continue
		}
		aa[i] = rr[rpos]
		rpos++
	}
}

