// LowerBound returns an index of a slice whose value is EQUAL TO AND LARGER THAN A KEY VALUE.
func LowerBound(s []int, key int) int {
	isLarger := func(index, key int) bool {
		if s[index] >= key {
			return true
		} else {
			return false
		}
	}

	left, right := -1, len(s)

	for right-left > 1 {
		mid := left + (right-left)/2
		if isLarger(mid, key) {
			right = mid
		} else {
			left = mid
		}
	}

	return right
}

// UpperBound returns an index of a slice whose value is EQUAL TO AND SMALLER THAN A KEY VALUE.
func UpperBound(s []int, key int) int {
	isSmaller := func(index, key int) bool {
		if s[index] <= key {
			return true
		} else {
			return false
		}
	}

	left, right := -1, len(s)

	for right-left > 1 {
		mid := left + (right-left)/2
		if isSmaller(mid, key) {
			left = mid
		} else {
			right = mid
		}
	}

	return left
}

var n int
var A, B []int

func main() {
	n = ReadInt()
	A, B = ReadIntSlice(n), ReadIntSlice(n)

	ans := 0
	// A, Bの2*Tのあまりの別スライスを作る
	AA := make([]int, n)
	BB := make([]int, n)
	// 全ビットについて求める
	for i := 0; i <= 29; i++ {
		T := PowInt(2, i)
		for j := 0; j < n; j++ {
			// AA[j] = A[j] % (2 * T)
			// BB[j] = B[j] % (2 * T)
			AA[j] = A[j] & (2*T - 1)
			BB[j] = B[j] & (2*T - 1)
		}
		sort.Sort(sort.IntSlice(BB))

		// aiを固定
		onBitNum := 0
		for j := 0; j < n; j++ {
			a := AA[j]
			lb := LowerBound(BB, T-a)
			ub := UpperBound(BB, 2*T-a-1)
			onBitNum += ub - lb + 1
			lb = LowerBound(BB, 3*T-a)
			ub = UpperBound(BB, 4*T-a-1)
			onBitNum += ub - lb + 1
		}
		if onBitNum%2 == 1 {
			//ans += PowInt(2, i)
			ans += T
		}
	}
	fmt.Println(ans)
}

// PowInt is integer version of math.Pow
// PowInt calculate a power by Binary Power (二分累乗法(O(log e))).
func PowInt(a, e int) int {
	if a < 0 || e < 0 {
		panic(errors.New("[argument error]: PowInt does not accept negative integers"))
	}

	if e == 0 {
		return 1
	}

	if e%2 == 0 {
		halfE := e / 2
		half := PowInt(a, halfE)
		return half * half
	}

	return a * PowInt(a, e-1)
}

