	for i := range as {
		as[i] = nextInt(sc)
	}

	sc = bufio.NewScanner(strings.NewReader(readLine()))
	sc.Split(bufio.ScanWords)
	bs := make([]int, N)
	for i := range bs {
		bs[i] = nextInt(sc)
	}

	ans := 0
	tmp := make([]int, len(bs))
	for i := uint8(0); i < 31; i++ {
		for j, b := range bs {
			tmp[j] = b % (1 << (i + 1))
		}
		sort.Ints(tmp)

