		for _, a := range as {
			n := a % (1 << (i + 1))

			x := sort.Search(len(bs), func(j int) bool {
				m := tmp[j]
				return (1<<i)-n <= m
			})
			y := sort.Search(len(bs), func(j int) bool {
				m := tmp[j]
				return 2*(1<<i)-n <= m
			})

			z := sort.Search(len(bs), func(j int) bool {
				m := tmp[j]
				return 3*(1<<i)-n <= m
			})
			w := sort.Search(len(bs), func(j int) bool {
				m := tmp[j]
				return 4*(1<<i)-n <= m
			})

			count += y - x + w - z
		}

		if count%2 == 1 {
			ans += 1 << i
		}
	}

	fmt.Println(ans)
}

