	for k := 0; k < 32; k++ {
		T := pow(k)
		count := 0
		tmp := make([]int, N)
		for i := range tmp {
			tmp[i] = bs[i] % (2 * T)
		}
		sort.Ints(tmp)

		for i := range as {
			a := as[i] % (2 * T)
			count += sort.Search(len(bs), func(i int) bool { return 2*T-a <= tmp[i] }) - sort.Search(len(bs), func(i int) bool { return tmp[i] >= T-a })
			count += sort.Search(len(bs), func(i int) bool { return 4*T-a <= tmp[i] }) - sort.Search(len(bs), func(i int) bool { return tmp[i] >= 3*T-a })
