def bisect(t: int, b: "List[int]"):
    lb = -1
    rb = len(b)
    while lb + 1 < rb:
        m = (lb + rb) // 2
        if b[m] < t:
            lb = m
        else:
            rb = m
    return lb + 1


def solve(N: int, a: "List[int]", b: "List[int]"):
    ans = 0
    for k in reversed(range(29 + 1)):
        m = 1 << (k + 1)
        a = sorted(ai % m for ai in a)
        b = sorted(bi % m for bi in b)
        v = 1 << k
        cnt = sum(
            bisect(2 * v - ai, b) - bisect(v - ai, b) +
            bisect(4 * v - ai, b) - bisect(3 * v - ai, b)
            for ai in a
        )
        if cnt % 2 == 1:
            ans = ans | (1 << k)
    print(ans)


def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    a = [int(next(tokens)) for _ in range(N)]  # type: "List[int]"
    b = [int(next(tokens)) for _ in range(N)]  # type: "List[int]"
    solve(N, a, b)


