def binarySearch(target, val) :
    left = -1
    right = len(target)
    def prop(index) :
        if target[index] >= val :
            return True
        else :
            return False

    while right - left > 1 :
        middle = left + (right - left) // 2
        if prop(middle) :
            right = middle
        else :
            left = middle

    return (left, right)

