pub trait BinarySearch<T> {
    fn lower_bound_by_key<B: Ord, F: FnMut(&T) -> B>(&self, x: &B, mut f: F) -> usize;
    fn lower_bound(&self, x: &T) -> usize;
}


impl<T: Ord + Clone> BinarySearch<T> for Vec<T> {
    fn lower_bound(&self, x: &T) -> usize {
        self.lower_bound_by_key(x, |y| y.clone())
    }

    fn lower_bound_by_key<B: Ord, F: FnMut(&T) -> B>(&self, x: &B, mut f: F) -> usize {
        let mut high = self.len();
        let mut low = 0;
        while low < high {
            let mid = (low + high) / 2;
            if  f(&self[mid]).lt(&x) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        low
    }
}

fn _solve(k: u32, a: u32, bb: &mut Vec<u32>) -> u32 {
    let mask = (1 << (k+1)) - 1;
    let a = a & mask;
    let t = 1 << k;
    bb.sort_by_key(|x| x & mask);

    let p1 = bb.lower_bound_by_key(&t, |b| (a & mask) + (b & mask));
    let p2 = bb.lower_bound_by_key(&(2*t), |b| (a & mask) + (b & mask));
    let p3 = bb.lower_bound_by_key(&(3*t), |b| (a & mask) + (b & mask));

    if ((bb.len() - p3) + (p2 - p1)) % 2 == 1 {
        t
    } else {
        0
    }
}

fn solve(aa: Vec<u32>, mut bb: Vec<u32>) -> u32 {
    let mut ans = 0;
    let mut mask = 0;
    for i in 0..28 {
        for a in aa.iter() {
            ans = ans ^ _solve(i, *a, &mut bb);
        }
    }
    ans
}

