use std::cmp::Ordering;

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}

pub trait BinarySearch<T> {
    fn lower_bound(&self, &T) -> usize;
    fn upper_bound(&self, &T) -> usize;
}

impl<T: Ord> BinarySearch<T> for [T] {
    fn lower_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less => {
                    low = mid + 1;
                }
                Ordering::Equal | Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
    fn upper_bound(&self, x: &T) -> usize {
        let mut low = 0;
        let mut high = self.len();

        while low != high {
            let mid = (low + high) / 2;
            match self[mid].cmp(x) {
                Ordering::Less | Ordering::Equal => {
                    low = mid + 1;
                }
                Ordering::Greater => {
                    high = mid;
                }
            }
        }
        low
    }
}

fn main() {
    let _: usize = read();
    let a: Vec<u64> = read_vec();
    let b: Vec<u64> = read_vec();

    let mut ans = 0;
    for c in 1..29 {
        let c = 2u64.pow(c);
        let half_c = c / 2;
        let temp_a = a.iter().map(|x| x % c).collect::<Vec<_>>();
        let mut temp_b = b.iter().map(|x| x % c).collect::<Vec<_>>();
        temp_b.sort();
        let mut counts = 0;
        for a_num in temp_a {
            if a_num < half_c {
                let lb = temp_b.lower_bound(&(half_c - a_num));
                let ub = temp_b.lower_bound(&(c - a_num));
                counts += ub - lb;
            } else if a_num == half_c {
                let lb = temp_b.lower_bound(&half_c);
                counts += lb;
            } else {
                let lb = temp_b.lower_bound(&(c - a_num));
                let ub = temp_b.lower_bound(&(c + half_c - a_num));
                counts += temp_b.len() - ub + lb;
            }
        }
        if counts % 2 == 1 {
            ans += half_c;
        }
    }
    println!("{:?}", ans);
}

