macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

// return first index, where v[i] > k
fn ubound(v:& Vec<i64>, k:i64) -> usize {
    let mut l = 0;
    let mut r = v.len();

    while l < r {
        let m = (l+r-1) >> 1;
        if v[m] <= k {
            l = m+1;
        } else {
            r = m;
        }
    }
    l
}

fn main() {
    input! {
        n: usize,
        a: [i64; n],        // v::Vec<i64>
        b: [i64; n],        // v::Vec<i64>
    };

    let ans:i64 = (0..29).map(|k| {
        let km = (1 << (k+1))-1;
        let mut bk:Vec<i64> = b.iter().map(|bi| {
            bi & km
        }).collect();
        bk.sort();

        let t = 1 << k;
        let sa = a.iter().map(|ai| {
            let aa = ai & km;
            let b1 = ubound(&bk, t-aa-1);
            let b2 = ubound(&bk, (t<<1)-aa-1);
            let b3 = ubound(&bk, t*3-aa-1);
            ((b2-b1) + (n-b3)) as i64
        }).sum::<i64>();
        if (sa & 1) == 1 { t } else {0}
    }).sum();
    println!("{}", ans);
}

