fn lower_bownd(v: &Vec<usize>, k: usize) -> isize {
    let mut ok = v.len() as isize;
    let mut err = -1;
    while ok - err > 1 {
        let mid = err + (ok - err) / 2;
        if v[mid as usize] >= k {
            ok = mid;
        } else {
            err = mid;
        }
    }
    ok
}

fn main() -> std::io::Result<()> {
    input! {n, a: [usize; n], b: [usize; n]};
    outbuf! {out};
    let mut ans = 0;
    let mut k = 1;
    for _i in 0..28 {
        let mask = 2 * k - 1;
        let mut c = b.iter().map(|x| *x & mask).collect::<Vec<_>>();
        c.sort();
        let mut s = 0isize;
        for aa in &a {
            let am = aa & mask;
            s -= lower_bownd(&c, k-am);
            s += lower_bownd(&c, 2*k-am);
            s -= lower_bownd(&c, 3*k-am);
            s += lower_bownd(&c, 4*k-am);
        }
        ans += (s&1) as usize *k;
        k <<= 1;
    }
    writeln!(out, "{}", ans)
}

