fn binary_search(i: u64, v: &Vec<u64>) -> usize {
    match v.binary_search(&(i)) {
        Ok(mut p) => {
            loop {
                if p == 0 { break; }
                if v[p] == v[p-1] {
                    p -= 1;
                } else { break; }
            }
            p
        },
        Err(p) => p,
    }
}

fn _solve(k: u8, a: u64, bb: &Vec<u64>) -> u64 {
    let cut = 1 << (k+1);
    let t = 1 << k;
    let a = a % cut;
    let mut bb = bb.iter().map(|b| b % cut).collect::<Vec<_>>();
    bb.sort_unstable();

    let p1 = binary_search(if t<a { 0 } else {t - a}, &bb);

    let p2 = binary_search(2*t - a, &bb);

    let p3 = binary_search(3*t - a, &bb);

    let p4 = binary_search(4*t - a, &bb);

    if ((p2 - p1) + (p4 - p3)) % 2 == 1 {
        1 << k
    } else {
        0
    }
}

fn solve(aa: Vec<u64>, bb: Vec<u64>) -> u64 {
    let mut ans = 0;
    for i in 0..29 {
        for a in aa.iter() {
            ans = ans ^ _solve(i, *a, &bb);
        }
    }
    ans
}

