fn lower_bownd(v: &Vec<isize>, k: isize) -> isize {
    let mut ok = v.len() as isize;
    let mut err = -1;
    while ok - err > 1 {
        let mid = err + (ok - err) / 2;
        if v[mid as usize] as isize >= k {
            ok = mid;
        } else {
            err = mid;
        }
    }
    ok
}

