        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn remove_same_values(vs: &mut Vec<i32>) {
    vs.sort();
    for i in 0..vs.len()-1 {
        if vs[i] == vs[i + 1] {
            vs[i] = 0;
            vs[i + 1] = 0;
        }
    }
}

fn main() {
    let n: usize = read();
    let mut aseq = vec![0; n];
    let mut bseq = vec![0; n];
    for i in 0..n {
        aseq[i] = read();
    }
    aseq.sort();
    for i in 0..n {
        bseq[i] = read();
    }
    remove_same_values(&mut bseq);
    bseq.sort();
    // remove same values
    for i in 0..n-1 {
        if bseq[i] == bseq[i + 1] {
            bseq[i] = 0;
            bseq[i + 1] = 0;
        }
    }
    bseq.sort();
    let mut ans = 0;
    for i in 0..30 {
        let target = 1 << (29 - i);
        for a in aseq.clone() {
            if a < target {
                let minv = target - a; // inclusive
                let maxv = 2 * target - a; // exclusive
                let left = match bseq.binary_search(&minv) {
                    Ok(v) => v,
                    Err(v) => v,
                };
                let right = match bseq.binary_search(&maxv) {
                    Ok(v) => v,
                    Err(v) => v,
                };
                ans ^= target * ((right - left) as i32 % 2);
            } else {
                let minv = 2 * target - a; // exclusive
                let maxv = 3 * target - a; // inclusive
                let left = match bseq.binary_search(&minv) {
                    Ok(v) => v,
                    Err(v) => v,
                };
                ans ^= target * (left as i32 % 2);
                let right = match bseq.binary_search(&maxv) {
                    Ok(v) => v,
                    Err(v) => v,
                };
                ans ^= target * ((n - right) as i32 % 2);
                // println!("{} {} {} {} {} {}", target, a, left, right, minv, maxv);
            }
        }
        for i in 0..n {
            aseq[i] %= target;
            bseq[i] %= target;
        }
        aseq.sort();
        remove_same_values(&mut bseq);
        bseq.sort();
    }
    println!("{}", ans);
}

