fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = AtRead::from(i);
    let n = i.read::<usize>();
    let a = i.read_vec::<u32>(n);
    let b = i.read_vec::<u32>(n);

    writeln!(o, "{}", solve(a, b)).unwrap();
}
fn solve(a: Vec<u32>, mut b: Vec<u32>) -> u32 {
    let n = a.len();
    let mut result = 0;
    let mut mask = 0;
    for i in 0..28 {
        mask |= 1 << i;
        b.sort_by_key(|x| x & mask);

        let t1 = 1 << i;
        let t2 = 1 << (i + 1);
        let t3 = t1 + t2;
        let mut c = 0;
        for &a in &a {
            let j1 = b.lower_bound_by(|&b| (a & mask) + (b & mask) >= t1);
            let j2 = b.lower_bound_by(|&b| (a & mask) + (b & mask) >= t2);
            let j3 = b.lower_bound_by(|&b| (a & mask) + (b & mask) >= t3);
            c += j2 - j1;
            c += n - j3;
        }
        if c % 2 == 1 {
            result |= 1 << i;
        }
    }
    result
}

pub trait BinarySearchExt<T> {
    fn lower_bound_by<F: Fn(&T) -> bool>(&self, f: F) -> usize;
    fn lower_bound(&self, x: &T) -> usize;
    fn upper_bound(&self, x: &T) -> usize;
}
impl<T: Ord> BinarySearchExt<T> for [T] {
    fn lower_bound_by<F: Fn(&T) -> bool>(&self, f: F) -> usize {
        let mut low = 0;
        let mut high = self.len();
        while low < high {
            let mid = (low + high) / 2;
            if f(&self[mid]) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        low
    }
    fn lower_bound(&self, x: &T) -> usize {
        self.lower_bound_by(|y| y < x)
    }
    fn upper_bound(&self, x: &T) -> usize {
        self.lower_bound_by(|y| y <= x)
    }
}

