        let mut p = 0;
        b.sort_by_key(|&x| x & mask);
        let t = 1 << k;
        for i in 0..n {
            let ai = a[i] & mask;
            p += binary_search(&b, |&b| ai + (b & mask) >= 2*t) as i64 - binary_search(&b, |&b| ai + (b & mask) >= t) as i64;
            p += n as i64 - binary_search(&b, |&b| ai + (b & mask) >= 3*t) as i64;
            p %= 2;
        }
