}

#[allow(dead_code)]
fn binary_search<T, F>(arr: &[T], f: F) -> usize where F: Fn(&T) -> bool {
    let mut ok = arr.len() as i64;
    let mut ng = -1i64;
    while (ok - ng).abs() > 1 {
        let mid = (ok + ng) / 2;
        if f(&arr[mid as usize]) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    ok as usize
}

