    input! {n, a: [isize; n], b: [isize; n]};
    // outbuf! {out};
    let mut ans = 0;
    let mut k = 1;
    for _i in 0..29 {
        let mask = 2 * k - 1;
        let mut c = b.iter().map(|x| *x & mask).collect::<Vec<_>>();
        c.sort();
        let mut s = 0isize;
        for aa in &a {
            let am = aa & mask;
            s -= lower_bownd(&c, k-am);
            s += lower_bownd(&c, 2*k-am);
            s -= lower_bownd(&c, 3*k-am);
            s += lower_bownd(&c, 4*k-am);
        }
        ans += (s&1) * k;
        k <<= 1;
    }
    println!("{}", ans);
}

