            ::std::io::stdin().read_line(&mut line).unwrap();
            let iter = line.split_whitespace();
            iter.map(|v| v.parse::<$t>().unwrap()).collect::<Vec<_>>()
        }
    )
}

fn binary_search(i: u64, v: &Vec<u64>) -> usize {
    match v.binary_search(&(i)) {
        Ok(mut p) => {
            loop {
                if p == 0 { break; }
                if v[p] == v[p-1] {
                    p -= 1;
                } else { break; }
            }
            p
        },
        Err(p) => p,
    }
}

fn _solve(k: u8, a: u64, bb: &Vec<u64>) -> u64 {
    let cut = 1 << (k+1);
    let t = 1 << k;
    let a = a % cut;
    let mut bb = bb.iter().map(|b| b % cut).collect::<Vec<_>>();
    bb.sort();

    let p1 = binary_search(if t<a { 0 } else {t - a}, &bb);

    let p2 = binary_search(2*t - a, &bb);

    let p3 = binary_search(3*t - a, &bb);

    let p4 = binary_search(4*t - a, &bb);

    if ((p2 - p1) + (p4 - p3)) % 2 == 1 {
        1 << k
    } else {
        0
    }
}

fn solve(aa: Vec<u64>, bb: Vec<u64>) -> u64 {
    let mut ans = 0;
    for i in 0..29 {
        for a in aa.iter() {
            ans = ans ^ _solve(i, *a, &bb);
        }
    }
    ans
}

fn main() {
    read_line!();
    let aa = parse_vec!(u64);
    let bb = parse_vec!(u64);

    println!("{}", solve(aa, bb));
}

#[test]
fn solve_test() {
    assert_eq!(_solve(0, 0, &vec![1, 1, 1]), 1);
    assert_eq!(_solve(0, 0, &vec![1, 1, 1, 1]), 0);
    assert_eq!(_solve(0, 1, &vec![1, 1, 1, 1]), 0);

    assert_eq!(_solve(1, 1, &vec![0b11]), 0);
    assert_eq!(_solve(1, 1, &vec![0b11, 0b01]), 0b10);

    assert_eq!(solve(vec![1, 2], vec![3, 4]), 2);
    assert_eq!(solve(vec![4, 6, 0, 0, 3, 3], vec![0, 5, 6, 5, 0, 3]), 8);
    assert_eq!(solve(vec![1, 2, 3, 4, 5], vec![1, 2, 3, 4, 5]), 2);
    assert_eq!(solve(vec![0], vec![0]), 0);
}

