pub fn lower_bound<T: Ord>(a: &Vec<T>, x: &T) -> usize {
    use std::cmp::Ordering;
    let mut l = 0;
    let mut r = a.len();
    while l != r {
        let m = l + (r - l) / 2;
        match a[m].cmp(x) {
            Ordering::Less => l = m + 1,
            Ordering::Equal | Ordering::Greater => r = m,
        }
    }
    l
}

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      aa: [usize; n],
      bb: [usize; n],
    }

    let mut ans = 0;
    for d in 0..29 {
        let t = 1 << d;
        let mut vs = vec![];
        for &b in &bb {
            vs.push(b % (t << 1));
        }
        vs.sort();

        let mut ones = 0;
        for i in 0..n {
            let a = aa[i] % (t << 1);
            // (a+b) [T, 2T)
            let l1 = if t >= a { lower_bound(&vs, &(t-a)) } else { 0 };
            let r1 = lower_bound(&vs, &(2*t-a));

            // (a+b) [3T, 4T)
            let l2 = lower_bound(&vs, &(3*t-a));
            let r2 = lower_bound(&vs, &(4*t-a));

            ones += r1-l1 + r2-l2;
        }

        if ones%2 == 1 {
            ans += 1 << d;
        }
    }
    puts!("{}\n", ans);
}

