fn count_ones(arr1: &[usize], arr2: &[usize], bit: usize) -> usize {
    let div = 1 << (bit + 1);
    let arr1_mod = arr1.into_iter().map(|num| *num % div).collect::<Vec<_>>();
    let mut arr2_mod = arr2.into_iter().map(|num| *num % div).collect::<Vec<_>>();
    arr2_mod.sort();
    let mut count = 0;
    for num in arr1_mod {
        let threshold1 = max(1 << bit, num) - num;
        let threshold2 = (1 << (bit + 1)) - num;
        let threshold3 = 3 * (1 << bit) - num;
        let threshold4 = (1 << (bit + 2)) - num;
        count += count_less(threshold2, &arr2_mod) - count_less(threshold1, &arr2_mod);
        count += count_less(threshold4, &arr2_mod) - count_less(threshold3, &arr2_mod);
    }
    count
}

fn count_less(x: usize, arr: &[usize]) -> usize {
    if arr[0] >= x {
        return 0;
    }
    if arr[arr.len() - 1] < x {
        return arr.len();
    }
    let (mut l, mut r) = (0, arr.len() - 1);
    while r - l > 1 {
        let mid = (l + r) / 2;
        if arr[mid] < x {
            l = mid;
        } else {
            r = mid;
        }
    }
    l + 1
}

