            let ii = a[i] % (t * 2);
            for k in 0..b.len() {
                b[k] %= t * 2;
            }
            b.sort();
            let mut count =
                lower_bound(&b, (t << 1) - ii) - if t < ii { 0 } else { lower_bound(&b, t - ii) };
            count += lower_bound(&b, (t << 2) - ii) - lower_bound(&b, 3 * t - ii);
            if count % 2 != 0 {
                ans ^= 1 << j;
            }
        }
    }
    println!("{}", ans);
}

