    let mut ans = 0;
    for k in 0..28 {
        let mask = 1<<k;
        let lower_mask = mask-1;

        let mut aa = vec![vec![]; 2];
        let mut bb = vec![vec![]; 2];
        for i in 0..n {
            let ai = if a[i] & mask == mask { 1 } else { 0 };
            let bi = if b[i] & mask == mask { 1 } else { 0 };
            aa[ai].push(a[i] & lower_mask);
            bb[bi].push(b[i] & lower_mask);
        }
        for i in 0..2 {
            aa[i].sort();
            bb[i].sort();
        }

        let mut ones = 0;
        for i in 0..2 {
