    assert_eq!(_solve(0, 1, &vec![1, 1, 1, 1]), 0);

    assert_eq!(_solve(1, 1, &vec![0b11]), 0);
    assert_eq!(_solve(1, 1, &vec![0b11, 0b01]), 0b10);

    assert_eq!(solve(vec![1, 2], vec![3, 4]), 2);
    assert_eq!(solve(vec![4, 6, 0, 0, 3, 3], vec![0, 5, 6, 5, 0, 3]), 8);
    assert_eq!(solve(vec![1, 2, 3, 4, 5], vec![1, 2, 3, 4, 5]), 2);
